function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const rawLoopT = t % duration;
  const loopT = rawLoopT < 0 ? rawLoopT + duration : rawLoopT;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const u = loopT / duration;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, p) => a + (b - a) * p;
  const easeInOutCubic = (p) => {
    const x = clamp01(p);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  };
  const easeInOutSine = (p) => {
    const x = clamp01(p);
    return 0.5 * (1 - Math.cos(Math.PI * x));
  };
  const subRange = (p, a, b) => clamp01((p - a) / (b - a));

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  };

  // 1. Clean Carbon Slate Aesthetic Gradient Background (zero background glow)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#09090B");
  bgGrad.addColorStop(0.5, "#1E1B24");
  bgGrad.addColorStop(1, "#0D0C10");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Palette constants
  const COL_CARBON_DEEP = "#100F14";
  const COL_PANEL_BG = "#1A1822";
  const COL_KEY_BG = "#252230";
  const COL_BORDER = "#484359";
  const COL_CRIMSON = "#EF4444";
  const COL_CORAL = "#FB7185";
  const COL_SILVER = "#CBD5E1";
  const COL_WHITE_SILVER = "#F1F5F9";

  // 2. Scene Choreography (3 Scenes, 20s Seamless Loop)
  // Smooth key highlight intensities for 9 keys (indices 0..8, 8 = Equals key)
  const keyGlow = [0, 0, 0, 0, 0, 0, 0, 0, 0];
  let screenCurveDraw = 0.18; // resting baseline stub -> 1.0 full profit curve
  let coinReveals = [0.35, 0, 0, 0, 0]; // 5 recurring profit coins
  let chevronAlpha = 0;
  let leftBudgetBars = [0.38, 0.30, 0.26];
  let rightMarginGauge = 0.34;
  let rightSubBars = [0.36, 0.30];

  const calcSeq = [0, 1, 4, 2, 5, 7, 8]; // clean rhythmic business calculation keystroke order

  if (currentScene === 0) {
    // Scene 0 (0-6.67s): Sequential keypad calculation rhythm & display baseline prep
    for (let k = 0; k < calcSeq.length; k++) {
      const kIdx = calcSeq[k];
      const startP = k * 0.12;
      const endP = startP + 0.26;
      const localP = subRange(sceneProgress, startP, endP);
      if (localP > 0 && localP < 1) {
        keyGlow[kIdx] = Math.sin(localP * Math.PI);
      }
    }
    // Keep Equals key illuminated cleanly into end of Scene 0
    keyGlow[8] = Math.max(keyGlow[8], easeInOutCubic(subRange(sceneProgress, 0.72, 0.96)));
    screenCurveDraw = lerp(0.18, 0.42, easeInOutCubic(subRange(sceneProgress, 0.25, 0.95)));
    coinReveals = [lerp(0.35, 1.0, easeInOutCubic(subRange(sceneProgress, 0.25, 0.85))), 0, 0, 0, 0];

    const g0 = easeInOutCubic(sceneProgress);
    leftBudgetBars = [
      lerp(0.38, 0.70, g0),
      lerp(0.30, 0.60, easeInOutCubic(subRange(sceneProgress, 0.12, 0.90))),
      lerp(0.26, 0.56, easeInOutCubic(subRange(sceneProgress, 0.20, 0.96))),
    ];
    rightMarginGauge = lerp(0.34, 0.58, g0);
    rightSubBars = [lerp(0.36, 0.58, g0), lerp(0.30, 0.52, g0)];
  } else if (currentScene === 1) {
    // Scene 1 (6.67-13.33s): Profit curve draws to peak & 5-coin recurring stack rises sequentially
    keyGlow[8] = 1.0;
    screenCurveDraw = lerp(0.42, 1.0, easeInOutCubic(subRange(sceneProgress, 0.04, 0.72)));
    coinReveals = [
      1.0,
      easeInOutCubic(subRange(sceneProgress, 0.08, 0.34)),
      easeInOutCubic(subRange(sceneProgress, 0.22, 0.48)),
      easeInOutCubic(subRange(sceneProgress, 0.36, 0.62)),
      easeInOutCubic(subRange(sceneProgress, 0.50, 0.76)),
    ];
    chevronAlpha = easeInOutCubic(subRange(sceneProgress, 0.68, 0.94));

    const g1 = easeInOutCubic(subRange(sceneProgress, 0.06, 0.92));
    leftBudgetBars = [lerp(0.70, 0.94, g1), lerp(0.60, 0.88, g1), lerp(0.56, 0.96, g1)];
    rightMarginGauge = lerp(0.58, 0.96, g1);
    rightSubBars = [lerp(0.58, 0.94, g1), lerp(0.52, 0.88, g1)];
  } else {
    // Scene 2 (13.33-20s): Controlled hold -> chevron exits -> coins unstack top-down -> screen & keys reset to t=0
    keyGlow[8] = 1 - easeInOutCubic(subRange(sceneProgress, 0.20, 0.78));
    chevronAlpha = 1 - easeInOutCubic(subRange(sceneProgress, 0.10, 0.30));
    coinReveals = [
      lerp(1.0, 0.35, easeInOutCubic(subRange(sceneProgress, 0.68, 0.96))),
      1 - easeInOutCubic(subRange(sceneProgress, 0.54, 0.78)),
      1 - easeInOutCubic(subRange(sceneProgress, 0.40, 0.64)),
      1 - easeInOutCubic(subRange(sceneProgress, 0.26, 0.50)),
      1 - easeInOutCubic(subRange(sceneProgress, 0.14, 0.38)),
    ];
    screenCurveDraw = lerp(1.0, 0.18, easeInOutCubic(subRange(sceneProgress, 0.22, 0.92)));

    const retAll = easeInOutCubic(subRange(sceneProgress, 0.22, 0.96));
    leftBudgetBars = [lerp(0.94, 0.38, retAll), lerp(0.88, 0.30, retAll), lerp(0.96, 0.26, retAll)];
    rightMarginGauge = lerp(0.96, 0.34, retAll);
    rightSubBars = [lerp(0.94, 0.36, retAll), lerp(0.88, 0.30, retAll)];
  }

  const cycleWave = 0.5 + 0.5 * Math.sin(TAU * u);

  // 3. Central Hero Unit: Modern Financial Calculator + 5-Coin Profit Stack (Total width 0.480*m centered on cx)
  const calcW = 0.340 * minSide;
  const calcH = 0.460 * minSide;
  const calcX = cx - 0.240 * minSide; // spans [cx - 0.240*m .. cx + 0.100*m]
  const calcY = cy - calcH * 0.5;
  const calcBot = calcY + calcH;
  const cRad = 0.028 * minSide;

  ctx.save();
  // Calculator Outer Housing
  roundRectPath(calcX, calcY, calcW, calcH, cRad);
  const calcGrad = ctx.createLinearGradient(calcX, calcY, calcX + calcW, calcBot);
  calcGrad.addColorStop(0, "#23202E");
  calcGrad.addColorStop(1, COL_PANEL_BG);
  ctx.fillStyle = calcGrad;
  ctx.fill();
  ctx.lineWidth = 0.0028 * minSide;
  ctx.strokeStyle = COL_BORDER;
  ctx.stroke();

  // Wide Profit Display Screen (inset 0.026*m left/right, top 0.028*m)
  const scrPadX = 0.026 * minSide;
  const scrX = calcX + scrPadX;
  const scrY = calcY + 0.028 * minSide;
  const scrW = calcW - scrPadX * 2; // 0.288*m
  const scrH = 0.128 * minSide;

  roundRectPath(scrX, scrY, scrW, scrH, 0.014 * minSide);
  ctx.fillStyle = COL_CARBON_DEEP;
  ctx.fill();
  ctx.lineWidth = 0.0022 * minSide;
  ctx.strokeStyle = "#3E394F";
  ctx.stroke();

  // Subtle horizontal reference grid lines strictly inside screen
  const scrInLeft = scrX + 0.020 * minSide;
  const scrInRight = scrX + scrW - 0.020 * minSide;
  ctx.strokeStyle = "rgba(100, 94, 122, 0.26)";
  ctx.lineWidth = 0.002 * minSide;
  ctx.beginPath();
  ctx.moveTo(scrInLeft, scrY + 0.098 * minSide);
  ctx.lineTo(scrInRight, scrY + 0.098 * minSide);
  ctx.moveTo(scrInLeft, scrY + 0.062 * minSide);
  ctx.lineTo(scrInRight, scrY + 0.062 * minSide);
  ctx.stroke();

  // Profit Line Curve inside Display Screen (quadratic upward growth trajectory strictly inside margins)
  const sp0x = scrInLeft + 0.004 * minSide;
  const sp0y = scrY + 0.094 * minSide;
  const sp1x = scrX + scrW * 0.52;
  const sp1y = scrY + 0.088 * minSide;
  const sp2x = scrInRight - 0.006 * minSide;
  const sp2y = scrY + 0.030 * minSide;

  const evalCurve = (p) => {
    const inv = 1 - p;
    return {
      x: inv * inv * sp0x + 2 * inv * p * sp1x + p * p * sp2x,
      y: inv * inv * sp0y + 2 * inv * p * sp1y + p * p * sp2y,
    };
  };

  if (screenCurveDraw > 0.01) {
    const steps = 36;
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(sp0x, sp0y);
    for (let s = 1; s <= steps; s++) {
      const pt = evalCurve((s / steps) * screenCurveDraw);
      ctx.lineTo(pt.x, pt.y);
    }
    const scrLineGrad = ctx.createLinearGradient(sp0x, sp0y, sp2x, sp2y);
    scrLineGrad.addColorStop(0, COL_CRIMSON);
    scrLineGrad.addColorStop(0.6, COL_CORAL);
    scrLineGrad.addColorStop(1, COL_WHITE_SILVER);
    ctx.strokeStyle = scrLineGrad;
    ctx.lineWidth = 0.0046 * minSide;
    ctx.lineCap = "round";
    ctx.stroke();

    // Crisp leading dot at current curve tip
    const tip = evalCurve(screenCurveDraw);
    ctx.beginPath();
    ctx.arc(tip.x, tip.y, 0.006 * minSide, 0, TAU);
    ctx.fillStyle = COL_WHITE_SILVER;
    ctx.fill();
    ctx.lineWidth = 0.0022 * minSide;
    ctx.strokeStyle = COL_CRIMSON;
    ctx.stroke();
    ctx.restore();
  }

  // 3x3 Symmetrical Financial Keypad (exact alignment & clean internal spacing)
  const keyW = 0.082 * minSide;
  const keyH = 0.068 * minSide;
  const gapX = 0.021 * minSide;
  const gapY = 0.023 * minSide;
  const padTopY = calcY + 0.182 * minSide;

  for (let row = 0; row < 3; row++) {
    for (let col = 0; col < 3; col++) {
      const idx = row * 3 + col;
      const kx = scrX + col * (keyW + gapX);
      const ky = padTopY + row * (keyH + gapY);
      const kcx = kx + keyW * 0.5;
      const kcy = ky + keyH * 0.5;
      const active = keyGlow[idx];
      const isEquals = idx === 8;

      roundRectPath(kx, ky, keyW, keyH, 0.012 * minSide);
      if (isEquals) {
        const eqGrad = ctx.createLinearGradient(kx, ky, kx + keyW, ky + keyH);
        eqGrad.addColorStop(0, active > 0.4 ? COL_CORAL : COL_CRIMSON);
        eqGrad.addColorStop(1, "#B91C1C");
        ctx.fillStyle = eqGrad;
      } else {
        ctx.fillStyle = active > 0.25 ? "#352C42" : COL_KEY_BG;
      }
      ctx.fill();

      ctx.lineWidth = 0.0022 * minSide;
      ctx.strokeStyle = isEquals
        ? COL_CORAL
        : active > 0.25
        ? COL_CORAL
        : "#3B364C";
      ctx.stroke();

      // Clean geometric key glyphs (zero text font dependencies or overlap risk)
      ctx.strokeStyle = isEquals || active > 0.35 ? COL_WHITE_SILVER : COL_SILVER;
      ctx.fillStyle = isEquals || active > 0.35 ? COL_WHITE_SILVER : COL_SILVER;
      ctx.lineCap = "round";
      ctx.lineWidth = 0.0034 * minSide;

      if (isEquals) {
        // Equals sign (=)
        ctx.beginPath();
        ctx.moveTo(kcx - 0.014 * minSide, kcy - 0.006 * minSide);
        ctx.lineTo(kcx + 0.014 * minSide, kcy - 0.006 * minSide);
        ctx.moveTo(kcx - 0.014 * minSide, kcy + 0.006 * minSide);
        ctx.lineTo(kcx + 0.014 * minSide, kcy + 0.006 * minSide);
        ctx.stroke();
      } else if (col === 2 && row === 0) {
        // Plus sign (+)
        ctx.beginPath();
        ctx.moveTo(kcx - 0.011 * minSide, kcy);
        ctx.lineTo(kcx + 0.011 * minSide, kcy);
        ctx.moveTo(kcx, kcy - 0.011 * minSide);
        ctx.lineTo(kcx, kcy + 0.011 * minSide);
        ctx.stroke();
      } else if (col === 2 && row === 1) {
        // Minus sign (-)
        ctx.beginPath();
        ctx.moveTo(kcx - 0.011 * minSide, kcy);
        ctx.lineTo(kcx + 0.011 * minSide, kcy);
        ctx.stroke();
      } else {
        // Clean minimalist numeric key dot / short bar indicator
        roundRectPath(kcx - 0.010 * minSide, kcy - 0.004 * minSide, 0.020 * minSide, 0.008 * minSide, 0.004 * minSide);
        ctx.fill();
      }
    }
  }
  ctx.restore();

  // 4. Side 5-Coin Recurring Profit Stack (strictly clear to right of Calculator: gap = 0.046*m!)
  const coinCx = cx + 0.193 * minSide; // spans [cx + 0.146*m .. cx + 0.240*m]
  const coinW = 0.094 * minSide;
  const coinH = 0.024 * minSide;
  const coinPitchY = 0.034 * minSide; // 0.010*m clean vertical gap between coins
  const stackBaseY = calcBot - 0.016 * minSide;

  // Crisp base pedestal bar aligned cleanly with calculator bottom
  roundRectPath(coinCx - coinW * 0.5, calcBot - 0.006 * minSide, coinW, 0.006 * minSide, 0.003 * minSide);
  ctx.fillStyle = COL_BORDER;
  ctx.fill();

  for (let c = 0; c < 5; c++) {
    const rev = coinReveals[c];
    if (rev > 0.01) {
      const dropOff = lerp(-0.016 * minSide, 0, rev);
      const cyCoin = stackBaseY - coinH - c * coinPitchY + dropOff;

      ctx.save();
      ctx.globalAlpha = rev;
      roundRectPath(coinCx - coinW * 0.5, cyCoin, coinW, coinH, coinH * 0.45);
      const cGrad = ctx.createLinearGradient(coinCx - coinW * 0.5, cyCoin, coinCx + coinW * 0.5, cyCoin);
      cGrad.addColorStop(0, "#B91C1C");
      cGrad.addColorStop(0.5, COL_CRIMSON);
      cGrad.addColorStop(1, COL_CORAL);
      ctx.fillStyle = cGrad;
      ctx.fill();

      // Clean silver center highlight capsule inside each profit coin
      roundRectPath(coinCx - 0.020 * minSide, cyCoin + 0.008 * minSide, 0.040 * minSide, 0.008 * minSide, 0.004 * minSide);
      ctx.fillStyle = c === 4 ? COL_WHITE_SILVER : COL_SILVER;
      ctx.fill();
      ctx.restore();
    }
  }

  // Upward Profit Chevron Indicator cleanly floating above top coin (strict 0.028*m vertical clearance!)
  if (chevronAlpha > 0.01) {
    const topCoinTopY = stackBaseY - coinH - 4 * coinPitchY;
    const chevY = topCoinTopY - 0.030 * minSide + lerp(0.010 * minSide, 0, chevronAlpha);
    const chW = 0.016 * minSide;
    const chH = 0.010 * minSide;

    ctx.save();
    ctx.globalAlpha = chevronAlpha;
    ctx.strokeStyle = COL_WHITE_SILVER;
    ctx.lineWidth = 0.004 * minSide;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    for (let k = 0; k < 2; k++) {
      const yOff = k * 0.012 * minSide;
      ctx.beginPath();
      ctx.moveTo(coinCx - chW, chevY - yOff + chH * 0.5);
      ctx.lineTo(coinCx, chevY - yOff - chH * 0.5);
      ctx.lineTo(coinCx + chW, chevY - yOff + chH * 0.5);
      ctx.stroke();
    }
    ctx.restore();
  }

  // 5. Symmetrical Flanking Cashflow & Budget Cards (Strictly clear of central unit)
  const cardW = 0.210 * minSide;
  const cardH = 0.250 * minSide;
  const leftCardX = cx - 0.630 * minSide;
  const rightCardX = cx + 0.420 * minSide;
  const cardY = cy - cardH * 0.5;

  // Left Card: Budget Allocation & Profit Margin Rows
  if (leftCardX > 0.03 * width) {
    ctx.save();
    roundRectPath(leftCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_PANEL_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const padX = 0.024 * minSide;
    roundRectPath(leftCardX + padX, cardY + 0.028 * minSide, 0.088 * minSide, 0.012 * minSide, 0.006 * minSide);
    ctx.fillStyle = "#3A364A";
    ctx.fill();

    const rowStartY = cardY + 0.072 * minSide;
    const rowGapY = 0.054 * minSide;
    const dotR = 0.008 * minSide;
    const barX = leftCardX + padX + dotR * 2 + 0.012 * minSide;
    const barW = cardW - padX * 2 - dotR * 2 - 0.012 * minSide;
    const barH = 0.014 * minSide;

    for (let s = 0; s < 3; s++) {
      const ry = rowStartY + s * rowGapY;
      const val = leftBudgetBars[s];
      ctx.beginPath();
      ctx.arc(leftCardX + padX + dotR, ry + barH * 0.5, dotR, 0, TAU);
      ctx.fillStyle = s === 2 ? COL_WHITE_SILVER : s === 1 ? COL_CORAL : COL_CRIMSON;
      ctx.fill();

      roundRectPath(barX, ry, barW, barH, barH * 0.5);
      ctx.fillStyle = COL_CARBON_DEEP;
      ctx.fill();

      roundRectPath(barX, ry, Math.max(barH, barW * val), barH, barH * 0.5);
      const lGrad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
      lGrad.addColorStop(0, COL_CRIMSON);
      lGrad.addColorStop(1, s === 2 ? COL_WHITE_SILVER : COL_CORAL);
      ctx.fillStyle = lGrad;
      ctx.fill();
    }
    ctx.restore();
  }

  // Right Card: Cashflow Margin Ring & 2 Recurring Profit Bars
  if (rightCardX + cardW < width - 0.03 * width) {
    ctx.save();
    roundRectPath(rightCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_PANEL_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const gcx = rightCardX + cardW * 0.5;
    const gcy = cardY + 0.092 * minSide;
    const gr = 0.052 * minSide;
    const startA = Math.PI * 0.78;
    const spanA = Math.PI * 1.44;

    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA);
    ctx.lineWidth = 0.011 * minSide;
    ctx.strokeStyle = COL_CARBON_DEEP;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA * rightMarginGauge);
    const rGrad = ctx.createLinearGradient(gcx - gr, gcy, gcx + gr, gcy);
    rGrad.addColorStop(0, COL_CRIMSON);
    rGrad.addColorStop(1, COL_CORAL);
    ctx.strokeStyle = rGrad;
    ctx.stroke();

    // Clean Mini Stacked Bars / Margin Icon inside Ring Center
    for (let m = 0; m < 3; m++) {
      const mw = (0.026 - m * 0.004) * minSide;
      const my = gcy + 0.008 * minSide - m * 0.009 * minSide;
      roundRectPath(gcx - mw * 0.5, my, mw, 0.005 * minSide, 0.0025 * minSide);
      ctx.fillStyle = m === 2 ? COL_WHITE_SILVER : COL_CORAL;
      ctx.fill();
    }

    // 2 Horizontal Profit Bars beneath ring
    const rbPadX = 0.024 * minSide;
    const rbW = cardW - rbPadX * 2;
    const rbH = 0.013 * minSide;
    for (let i = 0; i < 2; i++) {
      const rby = cardY + 0.172 * minSide + i * 0.032 * minSide;
      roundRectPath(rightCardX + rbPadX, rby, rbW, rbH, rbH * 0.5);
      ctx.fillStyle = COL_CARBON_DEEP;
      ctx.fill();

      roundRectPath(rightCardX + rbPadX, rby, Math.max(rbH, rbW * rightSubBars[i]), rbH, rbH * 0.5);
      ctx.fillStyle = i === 0 ? COL_CORAL : COL_SILVER;
      ctx.fill();
    }
    ctx.restore();
  }

  void cycleWave;
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const rawLoopT = t % duration;
  const loopT = rawLoopT < 0 ? rawLoopT + duration : rawLoopT;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const u = loopT / duration;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, p) => a + (b - a) * p;
  const easeInOutCubic = (p) => {
    const x = clamp01(p);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  };
  const easeInOutSine = (p) => {
    const x = clamp01(p);
    return 0.5 * (1 - Math.cos(Math.PI * x));
  };
  const subRange = (p, a, b) => clamp01((p - a) / (b - a));

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  };

  // 1. Clean Smoked Bronze-Black Aesthetic Gradient Background (zero background glow)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#0F0C05");
  bgGrad.addColorStop(0.5, "#241D0B");
  bgGrad.addColorStop(1, "#120E06");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Palette constants
  const COL_UMBER_DEEP = "#151007";
  const COL_CARD_BG = "#1E170A";
  const COL_CASE_TOP = "#2F2410";
  const COL_CASE_BOT = "#1D1609";
  const COL_BORDER = "#614C20";
  const COL_SAFFRON = "#FACC15";
  const COL_AMBER = "#F59E0B";
  const COL_TERRACOTTA = "#EA580C";
  const COL_CREAM = "#FEF9C3";

  // 2. Scene Choreography (3 Scenes, 20s Seamless Loop)
  // Strict sequencing guarantees Briefcase shifts down BEFORE KPI zone appears,
  // and KPI zone retracts completely BEFORE Briefcase rises back!
  let claspUnlock = 0; // 0 = locked, 1 = unlocked
  let caseShift = 0; // 0 = centered resting, 1 = lowered creating upper KPI stage
  let kpiBaseDraw = 0; // 0..1 baseline draw
  let kpiBars = [0, 0, 0]; // 3 tiered KPI bars
  let flagDraw = 0; // 0..1 milestone flag trim-path
  let leftOkrBars = [0.36, 0.28, 0.24];
  let rightTargetGauge = 0.34;
  let rightSubBars = [0.36, 0.30];

  if (currentScene === 0) {
    // Scene 0 (0-6.67s): Clasps unlock symmetrically & briefcase glides smoothly downward
    claspUnlock = easeInOutCubic(subRange(sceneProgress, 0.04, 0.42));
    caseShift = easeInOutCubic(subRange(sceneProgress, 0.28, 0.92));
    kpiBaseDraw = easeInOutCubic(subRange(sceneProgress, 0.80, 1.0));

    const g0 = easeInOutCubic(sceneProgress);
    leftOkrBars = [
      lerp(0.36, 0.68, g0),
      lerp(0.28, 0.58, easeInOutCubic(subRange(sceneProgress, 0.12, 0.90))),
      lerp(0.24, 0.52, easeInOutCubic(subRange(sceneProgress, 0.20, 0.96))),
    ];
    rightTargetGauge = lerp(0.34, 0.58, g0);
    rightSubBars = [lerp(0.36, 0.58, g0), lerp(0.30, 0.52, g0)];
  } else if (currentScene === 1) {
    // Scene 1 (6.67-13.33s): 3 tiered KPI bars rise sequentially & peak Milestone Flag draws cleanly
    claspUnlock = 1;
    caseShift = 1;
    kpiBaseDraw = 1;
    kpiBars = [
      easeInOutCubic(subRange(sceneProgress, 0.04, 0.38)),
      easeInOutCubic(subRange(sceneProgress, 0.20, 0.54)),
      easeInOutCubic(subRange(sceneProgress, 0.36, 0.70)),
    ];
    flagDraw = easeInOutCubic(subRange(sceneProgress, 0.62, 0.94));

    const g1 = easeInOutCubic(subRange(sceneProgress, 0.06, 0.92));
    leftOkrBars = [lerp(0.68, 0.94, g1), lerp(0.58, 0.88, g1), lerp(0.52, 0.96, g1)];
    rightTargetGauge = lerp(0.58, 0.96, g1);
    rightSubBars = [lerp(0.58, 0.94, g1), lerp(0.52, 0.88, g1)];
  } else {
    // Scene 2 (13.33-20s): Flag & KPI bars retract completely -> Briefcase rises -> Clasps relock to t=0
    flagDraw = 1 - easeInOutCubic(subRange(sceneProgress, 0.10, 0.30));
    kpiBars = [
      1 - easeInOutCubic(subRange(sceneProgress, 0.26, 0.48)),
      1 - easeInOutCubic(subRange(sceneProgress, 0.20, 0.42)),
      1 - easeInOutCubic(subRange(sceneProgress, 0.14, 0.36)),
    ];
    kpiBaseDraw = 1 - easeInOutCubic(subRange(sceneProgress, 0.38, 0.50));

    // Briefcase only begins rising at 0.50 AFTER KPI zone is 100% gone!
    caseShift = 1 - easeInOutCubic(subRange(sceneProgress, 0.50, 0.86));
    claspUnlock = 1 - easeInOutCubic(subRange(sceneProgress, 0.72, 0.96));

    const retAll = easeInOutCubic(subRange(sceneProgress, 0.20, 0.96));
    leftOkrBars = [lerp(0.94, 0.36, retAll), lerp(0.88, 0.28, retAll), lerp(0.96, 0.24, retAll)];
    rightTargetGauge = lerp(0.96, 0.34, retAll);
    rightSubBars = [lerp(0.94, 0.36, retAll), lerp(0.88, 0.30, retAll)];
  }

  const cycleWave = 0.5 + 0.5 * Math.sin(TAU * u);

  // 3. Dedicated Upper KPI Milestone Stage (y <= cy - 0.095*m -> >= 0.030*m clear above lowered briefcase handle!)
  const kpiBaseY = cy - 0.095 * minSide;
  const kpiBarW = 0.062 * minSide;
  const kpiPitch = 0.104 * minSide;
  const kpiBarXs = [cx - kpiPitch, cx, cx + kpiPitch];
  const kpiMaxHs = [0.056 * minSide, 0.092 * minSide, 0.128 * minSide];
  const kpiColorsTop = [COL_TERRACOTTA, COL_AMBER, COL_SAFFRON];
  const kpiColorsBot = ["#9A3412", "#B45309", "#CA8A04"];

  // KPI Baseline (cleanly draws outward from center)
  if (kpiBaseDraw > 0.01) {
    const baseHalfW = 0.175 * minSide * kpiBaseDraw;
    ctx.save();
    ctx.globalAlpha = kpiBaseDraw;
    ctx.beginPath();
    ctx.moveTo(cx - baseHalfW, kpiBaseY);
    ctx.lineTo(cx + baseHalfW, kpiBaseY);
    ctx.lineWidth = 0.003 * minSide;
    ctx.lineCap = "round";
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();
    ctx.restore();
  }

  // 3 Tiered KPI Bars
  for (let i = 0; i < 3; i++) {
    const pBar = kpiBars[i];
    if (pBar > 0.01) {
      const hNow = kpiMaxHs[i] * pBar;
      const bx = kpiBarXs[i] - kpiBarW * 0.5;
      const byBar = kpiBaseY - 0.005 * minSide - hNow;

      ctx.save();
      ctx.globalAlpha = clamp01(pBar * 1.4);
      roundRectPath(bx, byBar, kpiBarW, hNow, 0.008 * minSide);
      const bGrad = ctx.createLinearGradient(bx, byBar, bx, kpiBaseY - 0.005 * minSide);
      bGrad.addColorStop(0, kpiColorsTop[i]);
      bGrad.addColorStop(1, kpiColorsBot[i]);
      ctx.fillStyle = bGrad;
      ctx.fill();

      // Clean top cap highlight inside bar
      if (hNow > 0.016 * minSide) {
        roundRectPath(bx + 0.009 * minSide, byBar + 0.006 * minSide, kpiBarW - 0.018 * minSide, 0.005 * minSide, 0.0025 * minSide);
        ctx.fillStyle = i === 2 ? COL_CREAM : "rgba(254, 249, 195, 0.55)";
        ctx.fill();
      }
      ctx.restore();
    }
  }

  // Peak Milestone Flag cleanly positioned ABOVE Bar 3 (gap = 0.014*m above Bar 3 top)
  if (flagDraw > 0.01) {
    const poleX = kpiBarXs[2] - 0.010 * minSide;
    const poleBotY = kpiBaseY - 0.005 * minSide - kpiMaxHs[2] - 0.014 * minSide; // cy - 0.242*m
    const poleFullH = 0.052 * minSide;
    const poleP = easeInOutCubic(subRange(flagDraw, 0.0, 0.55));
    const bannerP = easeInOutCubic(subRange(flagDraw, 0.42, 1.0));
    const poleTopY = poleBotY - poleFullH * poleP;

    ctx.save();
    ctx.globalAlpha = clamp01(flagDraw * 1.5);
    // Vertical flagpole
    ctx.beginPath();
    ctx.moveTo(poleX, poleBotY);
    ctx.lineTo(poleX, poleTopY);
    ctx.lineWidth = 0.0038 * minSide;
    ctx.lineCap = "round";
    ctx.strokeStyle = COL_CREAM;
    ctx.stroke();

    // Crisp flat-vector pennant banner extending right from top of flagpole
    if (bannerP > 0.01) {
      const fW = 0.044 * minSide * bannerP;
      const fH = 0.026 * minSide;
      const fyTop = poleBotY - poleFullH;
      ctx.beginPath();
      ctx.moveTo(poleX + 0.002 * minSide, fyTop);
      ctx.lineTo(poleX + 0.002 * minSide + fW, fyTop + fH * 0.5);
      ctx.lineTo(poleX + 0.002 * minSide, fyTop + fH);
      ctx.closePath();
      const fGrad = ctx.createLinearGradient(poleX, fyTop, poleX + fW, fyTop + fH);
      fGrad.addColorStop(0, COL_SAFFRON);
      fGrad.addColorStop(1, COL_TERRACOTTA);
      ctx.fillStyle = fGrad;
      ctx.fill();
    }
    ctx.restore();
  }

  // 4. Central Hero Icon: Modern Executive Briefcase (glides vertically to create KPI stage)
  const bcW = 0.420 * minSide;
  const bcH = 0.252 * minSide;
  const bcX = cx - bcW * 0.5;
  const bcTopY = lerp(cy - 0.105 * minSide, cy - 0.013 * minSide, caseShift);
  const bcRad = 0.028 * minSide;

  ctx.save();
  // Briefcase Top Carrying Handle (sits cleanly above bcTopY, top at bcTopY - 0.052*m)
  const hndW = 0.126 * minSide;
  const hndH = 0.052 * minSide;
  const hndX = cx - hndW * 0.5;
  const hndTopY = bcTopY - hndH;

  ctx.beginPath();
  ctx.moveTo(hndX, bcTopY + 0.004 * minSide);
  ctx.lineTo(hndX, hndTopY + 0.018 * minSide);
  ctx.arcTo(hndX, hndTopY, hndX + 0.018 * minSide, hndTopY, 0.018 * minSide);
  ctx.lineTo(hndX + hndW - 0.018 * minSide, hndTopY);
  ctx.arcTo(hndX + hndW, hndTopY, hndX + hndW, hndTopY + 0.018 * minSide, 0.018 * minSide);
  ctx.lineTo(hndX + hndW, bcTopY + 0.004 * minSide);
  ctx.lineWidth = 0.014 * minSide;
  ctx.lineCap = "butt";
  ctx.strokeStyle = "#3E3015";
  ctx.stroke();

  // Crisp inner highlight along handle arch
  ctx.lineWidth = 0.003 * minSide;
  ctx.strokeStyle = COL_AMBER;
  ctx.stroke();

  // Main Briefcase Body
  roundRectPath(bcX, bcTopY, bcW, bcH, bcRad);
  const bcGrad = ctx.createLinearGradient(bcX, bcTopY, bcX + bcW, bcTopY + bcH);
  bcGrad.addColorStop(0, COL_CASE_TOP);
  bcGrad.addColorStop(1, COL_CASE_BOT);
  ctx.fillStyle = bcGrad;
  ctx.fill();

  // Upper Briefcase Flap Panel (clipped strictly inside briefcase body)
  const flapH = 0.096 * minSide;
  ctx.save();
  roundRectPath(bcX, bcTopY, bcW, bcH, bcRad);
  ctx.clip();
  ctx.fillStyle = "#3A2C13";
  ctx.fillRect(bcX, bcTopY, bcW, flapH);

  // Subtle metallic trim along lower edge of briefcase body
  ctx.fillStyle = "rgba(250, 204, 21, 0.14)";
  ctx.fillRect(bcX, bcTopY + bcH - 0.012 * minSide, bcW, 0.012 * minSide);
  ctx.restore();

  // Briefcase Outer Crisp Rim
  roundRectPath(bcX, bcTopY, bcW, bcH, bcRad);
  ctx.lineWidth = 0.003 * minSide;
  ctx.strokeStyle = COL_BORDER;
  ctx.stroke();

  // Flap Seam Horizontal Line
  const flapSeamY = bcTopY + flapH;
  ctx.beginPath();
  ctx.moveTo(bcX + 0.003 * minSide, flapSeamY);
  ctx.lineTo(bcX + bcW - 0.003 * minSide, flapSeamY);
  ctx.lineWidth = 0.0028 * minSide;
  ctx.strokeStyle = COL_AMBER;
  ctx.globalAlpha = 0.65;
  ctx.stroke();
  ctx.globalAlpha = 1;

  // Dual Symmetrical Briefcase Clasps (centered at cx +- 0.106*m straddling flapSeamY)
  const claspW = 0.044 * minSide;
  const claspH = 0.056 * minSide;
  const claspXs = [cx - 0.106 * minSide, cx + 0.106 * minSide];

  for (let c = 0; c < 2; c++) {
    const clCx = claspXs[c];
    const clX = clCx - claspW * 0.5;
    const clY = flapSeamY - claspH * 0.5;

    // Clasp outer metallic plate
    roundRectPath(clX, clY, claspW, claspH, 0.009 * minSide);
    ctx.fillStyle = COL_UMBER_DEEP;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = claspUnlock > 0.5 ? COL_SAFFRON : COL_AMBER;
    ctx.stroke();

    // Inner recessed clasp track
    const trW = 0.016 * minSide;
    const trH = 0.036 * minSide;
    roundRectPath(clCx - trW * 0.5, flapSeamY - trH * 0.5, trW, trH, trW * 0.5);
    ctx.fillStyle = "#2A200D";
    ctx.fill();

    // Sliding clasp latch tab strictly inside track (moves cleanly upward on unlock)
    const tabW = 0.024 * minSide;
    const tabH = 0.016 * minSide;
    const tabY = lerp(flapSeamY + 0.002 * minSide, flapSeamY - 0.018 * minSide, claspUnlock);
    roundRectPath(clCx - tabW * 0.5, tabY, tabW, tabH, 0.005 * minSide);
    const tGrad = ctx.createLinearGradient(clCx - tabW * 0.5, tabY, clCx + tabW * 0.5, tabY + tabH);
    tGrad.addColorStop(0, COL_CREAM);
    tGrad.addColorStop(0.5, COL_SAFFRON);
    tGrad.addColorStop(1, COL_TERRACOTTA);
    ctx.fillStyle = tGrad;
    ctx.fill();
  }

  // Subtle Executive Status Pill Bar centered on lower briefcase front (strictly below clasps)
  const pillW = 0.156 * minSide;
  const pillH = 0.012 * minSide;
  const pillY = bcTopY + bcH - 0.044 * minSide;
  roundRectPath(cx - pillW * 0.5, pillY, pillW, pillH, pillH * 0.5);
  ctx.fillStyle = COL_UMBER_DEEP;
  ctx.fill();

  roundRectPath(
    cx - pillW * 0.5,
    pillY,
    Math.max(pillH, pillW * lerp(0.35, 1.0, rightTargetGauge * 0.8 + cycleWave * 0.2)),
    pillH,
    pillH * 0.5
  );
  const pGrad = ctx.createLinearGradient(cx - pillW * 0.5, 0, cx + pillW * 0.5, 0);
  pGrad.addColorStop(0, COL_TERRACOTTA);
  pGrad.addColorStop(1, COL_SAFFRON);
  ctx.fillStyle = pGrad;
  ctx.fill();
  ctx.restore();

  // 5. Symmetrical Flanking Executive KPI Cards (Strictly clear of briefcase & KPI stage)
  const cardW = 0.210 * minSide;
  const cardH = 0.250 * minSide;
  const leftCardX = cx - 0.630 * minSide;
  const rightCardX = cx + 0.420 * minSide;
  const cardY = cy - cardH * 0.5;

  // Left Card: Strategic OKR Milestones
  if (leftCardX > 0.03 * width) {
    ctx.save();
    roundRectPath(leftCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_CARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const padX = 0.024 * minSide;
    roundRectPath(leftCardX + padX, cardY + 0.028 * minSide, 0.088 * minSide, 0.012 * minSide, 0.006 * minSide);
    ctx.fillStyle = "#4D3B17";
    ctx.fill();

    const rowStartY = cardY + 0.072 * minSide;
    const rowGapY = 0.054 * minSide;
    const sqSz = 0.018 * minSide;
    const barX = leftCardX + padX + sqSz + 0.014 * minSide;
    const barW = cardW - padX * 2 - sqSz - 0.014 * minSide;
    const barH = 0.014 * minSide;

    for (let s = 0; s < 3; s++) {
      const ry = rowStartY + s * rowGapY;
      roundRectPath(leftCardX + padX, ry, sqSz, sqSz, 0.004 * minSide);
      ctx.fillStyle = s === 2 ? COL_SAFFRON : s === 1 ? COL_AMBER : COL_TERRACOTTA;
      ctx.fill();

      const byTrack = ry + (sqSz - barH) * 0.5;
      roundRectPath(barX, byTrack, barW, barH, barH * 0.5);
      ctx.fillStyle = COL_UMBER_DEEP;
      ctx.fill();

      roundRectPath(barX, byTrack, Math.max(barH, barW * leftOkrBars[s]), barH, barH * 0.5);
      const lGrad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
      lGrad.addColorStop(0, COL_TERRACOTTA);
      lGrad.addColorStop(1, COL_SAFFRON);
      ctx.fillStyle = lGrad;
      ctx.fill();
    }
    ctx.restore();
  }

  // Right Card: KPI Target Achievement Ring & 2 Strategy Bars
  if (rightCardX + cardW < width - 0.03 * width) {
    ctx.save();
    roundRectPath(rightCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_CARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const gcx = rightCardX + cardW * 0.5;
    const gcy = cardY + 0.092 * minSide;
    const gr = 0.052 * minSide;
    const startA = Math.PI * 0.78;
    const spanA = Math.PI * 1.44;

    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA);
    ctx.lineWidth = 0.011 * minSide;
    ctx.strokeStyle = COL_UMBER_DEEP;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA * rightTargetGauge);
    const rGrad = ctx.createLinearGradient(gcx - gr, gcy, gcx + gr, gcy);
    rGrad.addColorStop(0, COL_TERRACOTTA);
    rGrad.addColorStop(1, COL_SAFFRON);
    ctx.strokeStyle = rGrad;
    ctx.stroke();

    // Clean Mini Briefcase Icon inside Ring Center
    const mbW = 0.030 * minSide;
    const mbH = 0.021 * minSide;
    roundRectPath(gcx - mbW * 0.5, gcy - mbH * 0.35, mbW, mbH, 0.004 * minSide);
    ctx.fillStyle = rightTargetGauge > 0.72 ? COL_SAFFRON : COL_AMBER;
    ctx.fill();

    ctx.strokeStyle = rightTargetGauge > 0.72 ? COL_SAFFRON : COL_AMBER;
    ctx.lineWidth = 0.003 * minSide;
    ctx.beginPath();
    ctx.moveTo(gcx - 0.007 * minSide, gcy - mbH * 0.35);
    ctx.lineTo(gcx - 0.007 * minSide, gcy - mbH * 0.65);
    ctx.lineTo(gcx + 0.007 * minSide, gcy - mbH * 0.65);
    ctx.lineTo(gcx + 0.007 * minSide, gcy - mbH * 0.35);
    ctx.stroke();

    // 2 Horizontal Target Bars beneath ring
    const rbPadX = 0.024 * minSide;
    const rbW = cardW - rbPadX * 2;
    const rbH = 0.013 * minSide;
    for (let i = 0; i < 2; i++) {
      const rby = cardY + 0.172 * minSide + i * 0.032 * minSide;
      roundRectPath(rightCardX + rbPadX, rby, rbW, rbH, rbH * 0.5);
      ctx.fillStyle = COL_UMBER_DEEP;
      ctx.fill();

      roundRectPath(rightCardX + rbPadX, rby, Math.max(rbH, rbW * rightSubBars[i]), rbH, rbH * 0.5);
      ctx.fillStyle = i === 0 ? COL_SAFFRON : COL_AMBER;
      ctx.fill();
    }
    ctx.restore();
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const rawLoopT = t % duration;
  const loopT = rawLoopT < 0 ? rawLoopT + duration : rawLoopT;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const u = loopT / duration;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, p) => a + (b - a) * p;
  const easeInOutCubic = (p) => {
    const x = clamp01(p);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  };
  const easeInOutSine = (p) => {
    const x = clamp01(p);
    return 0.5 * (1 - Math.cos(Math.PI * x));
  };
  const subRange = (p, a, b) => clamp01((p - a) / (b - a));

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  };

  // 1. Clean Deep Teal-Black Aesthetic Gradient Background (zero background glow)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#041014");
  bgGrad.addColorStop(0.5, "#092834");
  bgGrad.addColorStop(1, "#05151B");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Palette constants
  const COL_PETROL_DEEP = "#06171E";
  const COL_DOC_BG = "#0B2530";
  const COL_FOLD_BG = "#154354";
  const COL_BORDER = "#1F5D70";
  const COL_TURQUOISE = "#06B6D4";
  const COL_TEAL = "#14B8A6";
  const COL_AQUA = "#67E8F9";
  const COL_SEAFOAM = "#CCFBF1";

  // 2. Scene Choreography (3 Scenes, 20s Seamless Loop)
  const restRows = [0.35, 0.28, 0.32, 0.24];
  const fullRows = [0.92, 0.80, 0.88, 0.74];
  let activeRows = restRows.slice();
  let totalFill = 0.28;
  let sealRingDraw = 0; // 0..1 ring trim-path
  let sealCheckDraw = 0; // 0..1 checkmark trim-path
  let coinReveals = [0.30, 0, 0, 0]; // 1 base resting coin + 3 stacked coins rising in Scene 1
  let leftCashBars = [0.36, 0.30, 0.26];
  let rightSettleGauge = 0.32;
  let rightSubBars = [0.34, 0.28];

  if (currentScene === 0) {
    // Scene 0 (0-6.67s): Sequential ledger rows & total summary box populate cleanly
    for (let r = 0; r < 4; r++) {
      const rp = easeInOutCubic(subRange(sceneProgress, r * 0.12, r * 0.12 + 0.50));
      activeRows[r] = lerp(restRows[r], fullRows[r], rp);
    }
    totalFill = lerp(0.28, 0.88, easeInOutCubic(subRange(sceneProgress, 0.45, 0.96)));
    coinReveals = [lerp(0.30, 1.0, easeInOutCubic(subRange(sceneProgress, 0.20, 0.85))), 0, 0, 0];

    const g0 = easeInOutCubic(sceneProgress);
    leftCashBars = [
      lerp(0.36, 0.74, g0),
      lerp(0.30, 0.66, easeInOutCubic(subRange(sceneProgress, 0.12, 0.90))),
      lerp(0.26, 0.62, easeInOutCubic(subRange(sceneProgress, 0.18, 0.96))),
    ];
    rightSettleGauge = lerp(0.32, 0.60, g0);
    rightSubBars = [lerp(0.34, 0.60, g0), lerp(0.28, 0.54, g0)];
  } else if (currentScene === 1) {
    // Scene 1 (6.67-13.33s): Approved stamp trim-path draws & 4-coin payment stack rises sequentially
    activeRows = fullRows.slice();
    totalFill = lerp(0.88, 1.0, easeInOutCubic(subRange(sceneProgress, 0.0, 0.45)));
    sealRingDraw = easeInOutCubic(subRange(sceneProgress, 0.06, 0.48));
    sealCheckDraw = easeInOutSine(subRange(sceneProgress, 0.38, 0.78));

    coinReveals = [
      1.0,
      easeInOutCubic(subRange(sceneProgress, 0.12, 0.44)),
      easeInOutCubic(subRange(sceneProgress, 0.32, 0.64)),
      easeInOutCubic(subRange(sceneProgress, 0.52, 0.84)),
    ];

    const g1 = easeInOutCubic(subRange(sceneProgress, 0.08, 0.92));
    leftCashBars = [lerp(0.74, 0.94, g1), lerp(0.66, 0.88, g1), lerp(0.62, 0.92, g1)];
    rightSettleGauge = lerp(0.60, 0.96, g1);
    rightSubBars = [lerp(0.60, 0.94, g1), lerp(0.54, 0.88, g1)];
  } else {
    // Scene 2 (13.33-20s): Controlled hold -> seal exits -> coins unstack top-down -> rows reset to t=0
    sealCheckDraw = 1 - easeInOutSine(subRange(sceneProgress, 0.12, 0.38));
    sealRingDraw = 1 - easeInOutCubic(subRange(sceneProgress, 0.24, 0.58));

    coinReveals = [
      lerp(1.0, 0.30, easeInOutCubic(subRange(sceneProgress, 0.62, 0.96))),
      1 - easeInOutCubic(subRange(sceneProgress, 0.46, 0.74)),
      1 - easeInOutCubic(subRange(sceneProgress, 0.30, 0.58)),
      1 - easeInOutCubic(subRange(sceneProgress, 0.14, 0.42)),
    ];

    for (let r = 0; r < 4; r++) {
      const rRet = easeInOutCubic(subRange(sceneProgress, 0.34 + (3 - r) * 0.07, 0.74 + (3 - r) * 0.07));
      activeRows[r] = lerp(fullRows[r], restRows[r], rRet);
    }
    totalFill = lerp(1.0, 0.28, easeInOutCubic(subRange(sceneProgress, 0.26, 0.92)));

    const retAll = easeInOutCubic(subRange(sceneProgress, 0.24, 0.96));
    leftCashBars = [lerp(0.94, 0.36, retAll), lerp(0.88, 0.30, retAll), lerp(0.92, 0.26, retAll)];
    rightSettleGauge = lerp(0.96, 0.32, retAll);
    rightSubBars = [lerp(0.94, 0.34, retAll), lerp(0.88, 0.28, retAll)];
  }

  const cycleWave = 0.5 + 0.5 * Math.sin(TAU * u);

  // 3. Central Hero Unit: Financial Invoice Document + Side Payment Coin Stack (Total width 0.480*m centered on cx)
  const docW = 0.360 * minSide;
  const docH = 0.460 * minSide;
  const docX = cx - 0.240 * minSide; // spans [cx - 0.240*m .. cx + 0.120*m]
  const docY = cy - docH * 0.5;
  const docRight = docX + docW;
  const docBot = docY + docH;
  const foldSz = 0.056 * minSide;
  const dRad = 0.022 * minSide;

  ctx.save();
  // Document Body with Folded Top-Right Corner
  ctx.beginPath();
  ctx.moveTo(docX + dRad, docY);
  ctx.lineTo(docRight - foldSz, docY);
  ctx.lineTo(docRight, docY + foldSz);
  ctx.lineTo(docRight, docBot - dRad);
  ctx.arcTo(docRight, docBot, docRight - dRad, docBot, dRad);
  ctx.lineTo(docX + dRad, docBot);
  ctx.arcTo(docX, docBot, docX, docBot - dRad, dRad);
  ctx.lineTo(docX, docY + dRad);
  ctx.arcTo(docX, docY, docX + dRad, docY, dRad);
  ctx.closePath();

  const docGrad = ctx.createLinearGradient(docX, docY, docRight, docBot);
  docGrad.addColorStop(0, "#0E303D");
  docGrad.addColorStop(1, COL_DOC_BG);
  ctx.fillStyle = docGrad;
  ctx.fill();
  ctx.lineWidth = 0.0028 * minSide;
  ctx.strokeStyle = COL_BORDER;
  ctx.stroke();

  // Folded Corner Flap (crisp flat-vector triangle)
  ctx.beginPath();
  ctx.moveTo(docRight - foldSz, docY);
  ctx.lineTo(docRight - foldSz, docY + foldSz - 0.008 * minSide);
  ctx.quadraticCurveTo(docRight - foldSz, docY + foldSz, docRight - foldSz + 0.008 * minSide, docY + foldSz);
  ctx.lineTo(docRight, docY + foldSz);
  ctx.closePath();
  ctx.fillStyle = COL_FOLD_BG;
  ctx.fill();
  ctx.lineWidth = 0.0024 * minSide;
  ctx.strokeStyle = "#29788F";
  ctx.stroke();

  // Document Header Zone (strictly clear of folded top-right corner!)
  const padX = 0.028 * minSide;
  const hdrBadgeSz = 0.038 * minSide;
  const hdrY = docY + 0.034 * minSide;

  // Mini Ledger Emblem Square in top-left of document
  roundRectPath(docX + padX, hdrY, hdrBadgeSz, hdrBadgeSz, 0.008 * minSide);
  const hbGrad = ctx.createLinearGradient(docX + padX, hdrY, docX + padX + hdrBadgeSz, hdrY + hdrBadgeSz);
  hbGrad.addColorStop(0, COL_AQUA);
  hbGrad.addColorStop(1, COL_TURQUOISE);
  ctx.fillStyle = hbGrad;
  ctx.fill();

  // 2 clean mini lines inside header emblem
  ctx.fillStyle = COL_PETROL_DEEP;
  roundRectPath(docX + padX + 0.008 * minSide, hdrY + 0.011 * minSide, 0.022 * minSide, 0.005 * minSide, 0.0025 * minSide);
  ctx.fill();
  roundRectPath(docX + padX + 0.008 * minSide, hdrY + 0.022 * minSide, 0.015 * minSide, 0.005 * minSide, 0.0025 * minSide);
  ctx.fill();

  // Header Title Bars strictly ending before foldSz margin
  const titleX = docX + padX + hdrBadgeSz + 0.016 * minSide;
  roundRectPath(titleX, hdrY + 0.004 * minSide, 0.145 * minSide, 0.012 * minSide, 0.006 * minSide);
  ctx.fillStyle = COL_AQUA;
  ctx.fill();

  roundRectPath(titleX, hdrY + 0.024 * minSide, 0.102 * minSide, 0.009 * minSide, 0.0045 * minSide);
  ctx.fillStyle = "#1E5C70";
  ctx.fill();

  // Header Divider Line
  const div1Y = docY + 0.100 * minSide;
  ctx.beginPath();
  ctx.moveTo(docX + padX, div1Y);
  ctx.lineTo(docRight - padX, div1Y);
  ctx.lineWidth = 0.0022 * minSide;
  ctx.strokeStyle = "#184A5A";
  ctx.stroke();

  // 4 Sequential Ledger Line Items (y in [docY + 0.124*m .. docY + 0.284*m])
  const rowStartY = docY + 0.124 * minSide;
  const rowPitch = 0.044 * minSide;
  const sqSz = 0.014 * minSide;
  const descX = docX + padX + sqSz + 0.014 * minSide;
  const descMaxW = 0.172 * minSide;
  const amtX = docRight - padX - 0.078 * minSide;
  const amtMaxW = 0.078 * minSide;
  const lineH = 0.012 * minSide;

  for (let r = 0; r < 4; r++) {
    const ry = rowStartY + r * rowPitch;
    const fillVal = activeRows[r];

    // Row index bullet
    roundRectPath(docX + padX, ry, sqSz, sqSz, 0.0035 * minSide);
    ctx.fillStyle = fillVal > 0.65 ? COL_AQUA : "#1E5C70";
    ctx.fill();

    // Description track & fill
    const ly = ry + (sqSz - lineH) * 0.5;
    roundRectPath(descX, ly, descMaxW, lineH, lineH * 0.5);
    ctx.fillStyle = COL_PETROL_DEEP;
    ctx.fill();

    roundRectPath(descX, ly, Math.max(lineH, descMaxW * fillVal), lineH, lineH * 0.5);
    ctx.fillStyle = r % 2 === 0 ? COL_TURQUOISE : COL_TEAL;
    ctx.fill();

    // Nominal Amount track & fill (clean 0.026*m horizontal gap from description track!)
    roundRectPath(amtX, ly, amtMaxW, lineH, lineH * 0.5);
    ctx.fillStyle = COL_PETROL_DEEP;
    ctx.fill();

    roundRectPath(amtX, ly, Math.max(lineH, amtMaxW * clamp01(fillVal * 0.95)), lineH, lineH * 0.5);
    ctx.fillStyle = COL_AQUA;
    ctx.fill();
  }

  // Summary Divider Line
  const div2Y = docY + 0.304 * minSide;
  ctx.beginPath();
  ctx.moveTo(docX + padX, div2Y);
  ctx.lineTo(docRight - padX, div2Y);
  ctx.lineWidth = 0.0022 * minSide;
  ctx.strokeStyle = "#184A5A";
  ctx.stroke();

  // Bottom Left: Total Summary Box (strictly clear of Approved Seal on right!)
  const totX = docX + padX;
  const totY = docY + 0.328 * minSide;
  const totW = 0.184 * minSide;
  const totH = 0.092 * minSide;

  roundRectPath(totX, totY, totW, totH, 0.014 * minSide);
  ctx.fillStyle = COL_PETROL_DEEP;
  ctx.fill();
  ctx.lineWidth = 0.0022 * minSide;
  ctx.strokeStyle = totalFill > 0.85 ? COL_TURQUOISE : "#184A5A";
  ctx.stroke();

  // Total Box Header Pill
  roundRectPath(totX + 0.018 * minSide, totY + 0.020 * minSide, 0.072 * minSide, 0.010 * minSide, 0.005 * minSide);
  ctx.fillStyle = "#1E5C70";
  ctx.fill();

  // Total Amount Bold Bar
  const tBarX = totX + 0.018 * minSide;
  const tBarY = totY + 0.050 * minSide;
  const tBarW = totW - 0.036 * minSide;
  const tBarH = 0.018 * minSide;
  roundRectPath(tBarX, tBarY, tBarW, tBarH, tBarH * 0.5);
  ctx.fillStyle = "#0D2D3A";
  ctx.fill();

  roundRectPath(tBarX, tBarY, Math.max(tBarH, tBarW * totalFill), tBarH, tBarH * 0.5);
  const tGrad = ctx.createLinearGradient(tBarX, 0, tBarX + tBarW, 0);
  tGrad.addColorStop(0, COL_TEAL);
  tGrad.addColorStop(0.55, COL_TURQUOISE);
  tGrad.addColorStop(1, COL_SEAFOAM);
  ctx.fillStyle = tGrad;
  ctx.fill();

  // Bottom Right: Dedicated Approved Verified Stamp Seal Zone (center=(docX+0.288*m, docY+0.374*m), r=0.038*m)
  const sealCx = docX + 0.288 * minSide;
  const sealCy = docY + 0.374 * minSide;
  const sealR = 0.038 * minSide;

  // Faint placeholder ring so reserved seal area looks architectural even before approval
  ctx.beginPath();
  ctx.arc(sealCx, sealCy, sealR, 0, TAU);
  ctx.fillStyle = COL_PETROL_DEEP;
  ctx.fill();
  ctx.lineWidth = 0.0022 * minSide;
  ctx.strokeStyle = "#164656";
  ctx.stroke();

  // Animated Approved Stamp Ring (trim-path)
  if (sealRingDraw > 0.01) {
    ctx.save();
    ctx.beginPath();
    ctx.arc(sealCx, sealCy, sealR, -Math.PI * 0.5, -Math.PI * 0.5 + TAU * sealRingDraw);
    ctx.lineWidth = 0.0048 * minSide;
    ctx.lineCap = "round";
    ctx.strokeStyle = COL_AQUA;
    ctx.stroke();
    ctx.restore();
  }

  // Animated Verified Checkmark inside Stamp Seal (trim-path)
  if (sealCheckDraw > 0.01) {
    ctx.save();
    ctx.translate(sealCx, sealCy);
    const pA = { x: -0.016 * minSide, y: 0.002 * minSide };
    const pB = { x: -0.004 * minSide, y: 0.014 * minSide };
    const pC = { x: 0.018 * minSide, y: -0.012 * minSide };

    const s1 = Math.hypot(pB.x - pA.x, pB.y - pA.y);
    const s2 = Math.hypot(pC.x - pB.x, pC.y - pB.y);
    const drawLen = (s1 + s2) * sealCheckDraw;

    ctx.beginPath();
    ctx.moveTo(pA.x, pA.y);
    if (drawLen <= s1) {
      const f = drawLen / s1;
      ctx.lineTo(lerp(pA.x, pB.x, f), lerp(pA.y, pB.y, f));
    } else {
      ctx.lineTo(pB.x, pB.y);
      const f = (drawLen - s1) / s2;
      ctx.lineTo(lerp(pB.x, pC.x, f), lerp(pB.y, pC.y, f));
    }
    ctx.strokeStyle = COL_SEAFOAM;
    ctx.lineWidth = 0.0052 * minSide;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();

  // 4. Side 4-Coin Payment Stack (strictly clear to the right of Document: gap = 0.036*m!)
  const coinCx = cx + 0.198 * minSide; // spans [cx + 0.156*m .. cx + 0.240*m]
  const coinW = 0.084 * minSide;
  const coinH = 0.020 * minSide;
  const coinPitchY = 0.028 * minSide; // 0.008*m clean vertical gap between coins
  const stackBaseY = docBot - 0.014 * minSide;

  // Clean horizontal payment base pedestal aligned with document bottom
  roundRectPath(coinCx - coinW * 0.5, docBot - 0.006 * minSide, coinW, 0.006 * minSide, 0.003 * minSide);
  ctx.fillStyle = COL_BORDER;
  ctx.fill();

  for (let c = 0; c < 4; c++) {
    const rev = coinReveals[c];
    if (rev > 0.01) {
      const dropOff = lerp(-0.018 * minSide, 0, rev);
      const cyCoin = stackBaseY - coinH - c * coinPitchY + dropOff;
      ctx.save();
      ctx.globalAlpha = rev;
      roundRectPath(coinCx - coinW * 0.5, cyCoin, coinW, coinH, coinH * 0.45);
      const cGrad = ctx.createLinearGradient(coinCx - coinW * 0.5, cyCoin, coinCx + coinW * 0.5, cyCoin);
      cGrad.addColorStop(0, COL_TEAL);
      cGrad.addColorStop(0.5, COL_TURQUOISE);
      cGrad.addColorStop(1, COL_AQUA);
      ctx.fillStyle = cGrad;
      ctx.fill();

      // Clean center ridge highlight inside each payment coin
      roundRectPath(coinCx - 0.018 * minSide, cyCoin + 0.006 * minSide, 0.036 * minSide, 0.008 * minSide, 0.004 * minSide);
      ctx.fillStyle = COL_SEAFOAM;
      ctx.fill();
      ctx.restore();
    }
  }

  // 5. Symmetrical Flanking Accounting Cards (Left Cashflow & Right Settlement Gauge)
  const cardW = 0.210 * minSide;
  const cardH = 0.250 * minSide;
  const leftCardX = cx - 0.630 * minSide;
  const rightCardX = cx + 0.420 * minSide;
  const cardY = cy - cardH * 0.5;

  // Left Card: Cashflow & Tax Ledger Summary Bars
  if (leftCardX > 0.03 * width) {
    ctx.save();
    roundRectPath(leftCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_DOC_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const cPadX = 0.024 * minSide;
    roundRectPath(leftCardX + cPadX, cardY + 0.028 * minSide, 0.088 * minSide, 0.012 * minSide, 0.006 * minSide);
    ctx.fillStyle = "#195264";
    ctx.fill();

    const rStartY = cardY + 0.072 * minSide;
    const rGapY = 0.054 * minSide;
    const dotR = 0.008 * minSide;
    const bX = leftCardX + cPadX + dotR * 2 + 0.012 * minSide;
    const bW = cardW - cPadX * 2 - dotR * 2 - 0.012 * minSide;
    const bH = 0.014 * minSide;

    for (let s = 0; s < 3; s++) {
      const ry = rStartY + s * rGapY;
      const val = leftCashBars[s];
      ctx.beginPath();
      ctx.arc(leftCardX + cPadX + dotR, ry + bH * 0.5, dotR, 0, TAU);
      ctx.fillStyle = s === 0 ? COL_AQUA : s === 1 ? COL_TURQUOISE : COL_TEAL;
      ctx.fill();

      roundRectPath(bX, ry, bW, bH, bH * 0.5);
      ctx.fillStyle = COL_PETROL_DEEP;
      ctx.fill();

      roundRectPath(bX, ry, Math.max(bH, bW * val), bH, bH * 0.5);
      const lGrad = ctx.createLinearGradient(bX, 0, bX + bW, 0);
      lGrad.addColorStop(0, COL_TEAL);
      lGrad.addColorStop(1, COL_AQUA);
      ctx.fillStyle = lGrad;
      ctx.fill();
    }
    ctx.restore();
  }

  // Right Card: Invoice Settlement Gauge & 2 Payment Status Bars
  if (rightCardX + cardW < width - 0.03 * width) {
    ctx.save();
    roundRectPath(rightCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_DOC_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const gcx = rightCardX + cardW * 0.5;
    const gcy = cardY + 0.092 * minSide;
    const gr = 0.052 * minSide;
    const startA = Math.PI * 0.78;
    const spanA = Math.PI * 1.44;

    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA);
    ctx.lineWidth = 0.011 * minSide;
    ctx.strokeStyle = COL_PETROL_DEEP;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA * rightSettleGauge);
    const rGrad = ctx.createLinearGradient(gcx - gr, gcy, gcx + gr, gcy);
    rGrad.addColorStop(0, COL_TEAL);
    rGrad.addColorStop(1, COL_AQUA);
    ctx.strokeStyle = rGrad;
    ctx.stroke();

    // Clean Mini Invoice Document Icon inside Gauge Center
    const mdW = 0.024 * minSide;
    const mdH = 0.030 * minSide;
    roundRectPath(gcx - mdW * 0.5, gcy - mdH * 0.5, mdW, mdH, 0.004 * minSide);
    ctx.fillStyle = rightSettleGauge > 0.72 ? COL_AQUA : COL_TURQUOISE;
    ctx.fill();

    ctx.fillStyle = COL_PETROL_DEEP;
    ctx.fillRect(gcx - 0.007 * minSide, gcy - 0.007 * minSide, 0.014 * minSide, 0.0035 * minSide);
    ctx.fillRect(gcx - 0.007 * minSide, gcy + 0.002 * minSide, 0.010 * minSide, 0.0035 * minSide);

    // 2 Horizontal Settlement Bars beneath gauge
    const rbPadX = 0.024 * minSide;
    const rbW = cardW - rbPadX * 2;
    const rbH = 0.013 * minSide;
    for (let i = 0; i < 2; i++) {
      const rby = cardY + 0.172 * minSide + i * 0.032 * minSide;
      roundRectPath(rightCardX + rbPadX, rby, rbW, rbH, rbH * 0.5);
      ctx.fillStyle = COL_PETROL_DEEP;
      ctx.fill();

      roundRectPath(rightCardX + rbPadX, rby, Math.max(rbH, rbW * rightSubBars[i]), rbH, rbH * 0.5);
      ctx.fillStyle = i === 0 ? COL_AQUA : COL_TURQUOISE;
      ctx.fill();
    }
    ctx.restore();
  }

  void cycleWave;
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const rawLoopT = t % duration;
  const loopT = rawLoopT < 0 ? rawLoopT + duration : rawLoopT;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const u = loopT / duration;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, p) => a + (b - a) * p;
  const easeInOutCubic = (p) => {
    const x = clamp01(p);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  };
  const easeInOutSine = (p) => {
    const x = clamp01(p);
    return 0.5 * (1 - Math.cos(Math.PI * x));
  };
  const subRange = (p, a, b) => clamp01((p - a) / (b - a));

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  };

  // 1. Clean Midnight Plum Aesthetic Gradient Background (zero background glow)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#120912");
  bgGrad.addColorStop(0.5, "#271324");
  bgGrad.addColorStop(1, "#140A15");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Palette constants
  const COL_PLUM_DEEP = "#180B18";
  const COL_CARD_BG = "#200F20";
  const COL_FOLDER_TAB = "#2E162D";
  const COL_BORDER = "#5C2F5A";
  const COL_PEACH = "#F4A261";
  const COL_ROSE = "#E5989B";
  const COL_PEARL = "#FAF0CA";
  const COL_MAUVE = "#B56576";
  const SEG_COLORS = [COL_PEACH, COL_ROSE, COL_PEARL, COL_MAUVE];

  // 2. Scene Choreography (4 Scenes, 20s Seamless Loop)
  const wBase = [0.28, 0.26, 0.24, 0.22];
  const wRebal = [0.40, 0.24, 0.20, 0.16];

  let weights = wBase.slice();
  let chartExpand = 0.72; // 0.72 -> 1.00 clean open-in without empty frame
  let explodeAmt = 0; // 0..1 radial offset of primary segment 0
  let yieldGauge = 0.38;
  let rightSubBars = [0.40, 0.32];

  if (currentScene === 0) {
    // Scene 0 (0-5s): Smooth expansion of 4 portfolio segments into full circle
    const p0 = easeInOutCubic(subRange(sceneProgress, 0.04, 0.94));
    chartExpand = lerp(0.72, 1.00, p0);
    weights = wBase.slice();
    explodeAmt = 0;
    yieldGauge = lerp(0.38, 0.62, p0);
    rightSubBars = [lerp(0.40, 0.64, p0), lerp(0.32, 0.56, p0)];
  } else if (currentScene === 1) {
    // Scene 1 (5-10s): Dynamic synchronized portfolio rebalancing
    const p1 = easeInOutCubic(subRange(sceneProgress, 0.06, 0.92));
    chartExpand = 1.00;
    weights = wBase.map((v, idx) => lerp(v, wRebal[idx], p1));
    explodeAmt = 0;
    yieldGauge = lerp(0.62, 0.82, p1);
    rightSubBars = [lerp(0.64, 0.82, p1), lerp(0.56, 0.74, p1)];
  } else if (currentScene === 2) {
    // Scene 2 (10-15s): Primary equity segment explodes outward cleanly (zero collision)
    const p2 = easeInOutCubic(subRange(sceneProgress, 0.08, 0.72));
    chartExpand = 1.00;
    weights = wRebal.slice();
    explodeAmt = p2;
    yieldGauge = lerp(0.82, 0.96, easeInOutCubic(subRange(sceneProgress, 0.08, 0.88)));
    rightSubBars = [
      lerp(0.82, 0.94, easeInOutCubic(subRange(sceneProgress, 0.08, 0.88))),
      lerp(0.74, 0.88, easeInOutCubic(subRange(sceneProgress, 0.12, 0.92))),
    ];
  } else {
    // Scene 3 (15-20s): Slice retracts cleanly -> weights & expansion return smoothly to t=0
    explodeAmt = 1 - easeInOutCubic(subRange(sceneProgress, 0.08, 0.44));
    const rebalRet = easeInOutCubic(subRange(sceneProgress, 0.34, 0.88));
    weights = wRebal.map((v, idx) => lerp(v, wBase[idx], rebalRet));
    chartExpand = lerp(1.00, 0.72, easeInOutCubic(subRange(sceneProgress, 0.42, 0.96)));

    const retAll = easeInOutCubic(subRange(sceneProgress, 0.22, 0.96));
    yieldGauge = lerp(0.96, 0.38, retAll);
    rightSubBars = [lerp(0.94, 0.40, retAll), lerp(0.88, 0.32, retAll)];
  }

  const cycleWave = 0.5 + 0.5 * Math.sin(TAU * u);

  // 3. Central Hero Icon: Investment Portfolio Folder Silhouette
  const fw = 0.560 * minSide;
  const fx = cx - fw * 0.5;
  const tabTopY = cy - 0.228 * minSide;
  const bodyTopY = cy - 0.180 * minSide;
  const bodyBotY = cy + 0.230 * minSide;
  const tabW = 0.196 * minSide;
  const fRad = 0.026 * minSide;

  ctx.save();
  // Unified crisp flat-vector Folder Path (top-left tab seamlessly merged into main folder body)
  ctx.beginPath();
  ctx.moveTo(fx + fRad, tabTopY);
  ctx.lineTo(fx + tabW - 0.022 * minSide, tabTopY);
  ctx.quadraticCurveTo(fx + tabW, tabTopY, fx + tabW + 0.014 * minSide, tabTopY + 0.024 * minSide);
  ctx.lineTo(fx + tabW + 0.026 * minSide, bodyTopY);
  ctx.lineTo(fx + fw - fRad, bodyTopY);
  ctx.arcTo(fx + fw, bodyTopY, fx + fw, bodyTopY + fRad, fRad);
  ctx.lineTo(fx + fw, bodyBotY - fRad);
  ctx.arcTo(fx + fw, bodyBotY, fx + fw - fRad, bodyBotY, fRad);
  ctx.lineTo(fx + fRad, bodyBotY);
  ctx.arcTo(fx, bodyBotY, fx, bodyBotY - fRad, fRad);
  ctx.lineTo(fx, tabTopY + fRad);
  ctx.arcTo(fx, tabTopY, fx + fRad, tabTopY, fRad);
  ctx.closePath();

  const folGrad = ctx.createLinearGradient(fx, tabTopY, fx + fw, bodyBotY);
  folGrad.addColorStop(0, COL_FOLDER_TAB);
  folGrad.addColorStop(0.24, COL_CARD_BG);
  folGrad.addColorStop(1, "#1A0C1A");
  ctx.fillStyle = folGrad;
  ctx.fill();
  ctx.lineWidth = 0.003 * minSide;
  ctx.strokeStyle = COL_BORDER;
  ctx.stroke();

  // Clean horizontal tab accent bar strictly inside upper-left folder tab
  roundRectPath(fx + 0.030 * minSide, tabTopY + 0.019 * minSide, 0.106 * minSide, 0.010 * minSide, 0.005 * minSide);
  ctx.fillStyle = COL_ROSE;
  ctx.fill();

  // Subtle horizontal folder fold seam separating tab region from front folio face
  const seamY = bodyTopY + 0.018 * minSide;
  ctx.beginPath();
  ctx.moveTo(fx + 0.028 * minSide, seamY);
  ctx.lineTo(fx + fw - 0.028 * minSide, seamY);
  ctx.lineWidth = 0.002 * minSide;
  ctx.strokeStyle = "rgba(155, 86, 140, 0.32)";
  ctx.stroke();

  // 4. Smart 4-Segment Donut Portfolio Chart (Strictly centered inside folder front face)
  const chartCy = (seamY + bodyBotY) * 0.5; // cy + 0.034*m (half-height to seam/bottom = 0.196*m)
  const rOut = 0.130 * minSide;
  const rIn = 0.074 * minSide;
  const explodeMax = 0.022 * minSide; // max radial reach = 0.152*m, leaving >= 0.044*m clear inside folder!
  const gapAngle = 0.085; // crisp ~4.9 deg uniform gap between all segments

  // Faint resting track ring behind segments for architectural grounding
  ctx.beginPath();
  ctx.arc(cx, chartCy, (rOut + rIn) * 0.5, 0, TAU);
  ctx.lineWidth = rOut - rIn;
  ctx.strokeStyle = COL_PLUM_DEEP;
  ctx.stroke();

  // Compute cumulative angles starting cleanly at 12 o'clock (-PI/2)
  const totalSpan = TAU * chartExpand;
  let curAngle = -Math.PI * 0.5;

  for (let i = 0; i < 4; i++) {
    const segSpan = totalSpan * weights[i];
    const a0 = curAngle + gapAngle * 0.5;
    const a1 = curAngle + segSpan - gapAngle * 0.5;
    curAngle += segSpan;

    if (a1 > a0 + 0.01) {
      const midA = (a0 + a1) * 0.5;
      const offsetR = i === 0 ? explodeAmt * explodeMax : 0;
      const ox = Math.cos(midA) * offsetR;
      const oy = Math.sin(midA) * offsetR;

      ctx.save();
      ctx.translate(cx + ox, chartCy + oy);

      // Clean annular wedge segment
      ctx.beginPath();
      ctx.arc(0, 0, rOut, a0, a1, false);
      ctx.arc(0, 0, rIn, a1, a0, true);
      ctx.closePath();
      ctx.fillStyle = SEG_COLORS[i];
      ctx.fill();

      // Subtle inner tonal edge rim on exploded primary segment for razor clarity
      if (i === 0 && explodeAmt > 0.05) {
        ctx.lineWidth = 0.0024 * minSide;
        ctx.strokeStyle = COL_PEARL;
        ctx.globalAlpha = explodeAmt * 0.85;
        ctx.stroke();
      }
      ctx.restore();
    }
  }

  // Central Portfolio Core Medallion (r = 0.054*m -> 0.020*m clean dark moat clear of rIn = 0.074*m!)
  const medR = 0.054 * minSide;
  ctx.beginPath();
  ctx.arc(cx, chartCy, medR, 0, TAU);
  ctx.fillStyle = COL_PLUM_DEEP;
  ctx.fill();
  ctx.lineWidth = 0.0026 * minSide;
  ctx.strokeStyle = explodeAmt > 0.4 ? COL_PEACH : COL_BORDER;
  ctx.stroke();

  // Clean Flat-Vector 3-Bar Portfolio Emblem inside Medallion Center
  const mbW = 0.010 * minSide;
  const mbGap = 0.007 * minSide;
  const mbBaseY = chartCy + 0.018 * minSide;
  const mbHeights = [0.020 * minSide, 0.032 * minSide, 0.026 * minSide];
  const mbColors = [COL_ROSE, COL_PEACH, COL_PEARL];
  const mbStartX = cx - (mbW * 3 + mbGap * 2) * 0.5;

  for (let b = 0; b < 3; b++) {
    const hNow = mbHeights[b] * lerp(0.92, 1.08, b === 1 ? explodeAmt : cycleWave * 0.35);
    roundRectPath(mbStartX + b * (mbW + mbGap), mbBaseY - hNow, mbW, hNow, 0.003 * minSide);
    ctx.fillStyle = mbColors[b];
    ctx.fill();
  }
  ctx.restore();

  // 5. Symmetrical Flanking Portfolio Telemetry Cards (Strictly clear of central folder)
  const cardW = 0.210 * minSide;
  const cardH = 0.250 * minSide;
  const leftCardX = cx - 0.630 * minSide;
  const rightCardX = cx + 0.420 * minSide;
  const cardY = cy - cardH * 0.5;

  // Left Card: Live 4-Asset Allocation Weight Breakdown (color-matched to all 4 donut segments!)
  if (leftCardX > 0.03 * width) {
    ctx.save();
    roundRectPath(leftCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_CARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const padX = 0.024 * minSide;
    roundRectPath(leftCardX + padX, cardY + 0.026 * minSide, 0.088 * minSide, 0.011 * minSide, 0.0055 * minSide);
    ctx.fillStyle = "#4B2549";
    ctx.fill();

    const rowStartY = cardY + 0.062 * minSide;
    const rowGapY = 0.043 * minSide;
    const dotR = 0.0068 * minSide;
    const barX = leftCardX + padX + dotR * 2 + 0.012 * minSide;
    const barW = cardW - padX * 2 - dotR * 2 - 0.012 * minSide;
    const barH = 0.013 * minSide;

    for (let i = 0; i < 4; i++) {
      const ry = rowStartY + i * rowGapY;
      // Exact matching segment color swatch
      ctx.beginPath();
      ctx.arc(leftCardX + padX + dotR, ry + barH * 0.5, dotR, 0, TAU);
      ctx.fillStyle = SEG_COLORS[i];
      ctx.fill();

      roundRectPath(barX, ry, barW, barH, barH * 0.5);
      ctx.fillStyle = COL_PLUM_DEEP;
      ctx.fill();

      // Scale visual bar proportionally to live weight (weights range ~0.16..0.40 -> map cleanly to 0.34..0.95)
      const fillFrac = clamp01(weights[i] * 2.25);
      roundRectPath(barX, ry, Math.max(barH, barW * fillFrac), barH, barH * 0.5);
      ctx.fillStyle = SEG_COLORS[i];
      ctx.fill();
    }
    ctx.restore();
  }

  // Right Card: Portfolio Return Gauge & 2 Diversification Metrics
  if (rightCardX + cardW < width - 0.03 * width) {
    ctx.save();
    roundRectPath(rightCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_CARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const gcx = rightCardX + cardW * 0.5;
    const gcy = cardY + 0.092 * minSide;
    const gr = 0.052 * minSide;
    const startA = Math.PI * 0.78;
    const spanA = Math.PI * 1.44;

    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA);
    ctx.lineWidth = 0.011 * minSide;
    ctx.strokeStyle = COL_PLUM_DEEP;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA * yieldGauge);
    const gGrad = ctx.createLinearGradient(gcx - gr, gcy, gcx + gr, gcy);
    gGrad.addColorStop(0, COL_ROSE);
    gGrad.addColorStop(1, COL_PEACH);
    ctx.strokeStyle = gGrad;
    ctx.stroke();

    // Clean Mini Pie-Slice Icon inside Gauge Center
    const mpR = 0.018 * minSide;
    ctx.beginPath();
    ctx.moveTo(gcx, gcy);
    ctx.arc(gcx, gcy, mpR, -Math.PI * 0.5, Math.PI * 1.15);
    ctx.closePath();
    ctx.fillStyle = COL_ROSE;
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(gcx + 0.003 * minSide, gcy - 0.002 * minSide);
    ctx.arc(gcx + 0.003 * minSide, gcy - 0.002 * minSide, mpR * 0.92, Math.PI * 1.25, Math.PI * 1.92);
    ctx.closePath();
    ctx.fillStyle = COL_PEACH;
    ctx.fill();

    // 2 Horizontal Metric Bars beneath gauge
    const rbPadX = 0.024 * minSide;
    const rbW = cardW - rbPadX * 2;
    const rbH = 0.013 * minSide;
    for (let i = 0; i < 2; i++) {
      const rby = cardY + 0.172 * minSide + i * 0.032 * minSide;
      roundRectPath(rightCardX + rbPadX, rby, rbW, rbH, rbH * 0.5);
      ctx.fillStyle = COL_PLUM_DEEP;
      ctx.fill();

      roundRectPath(rightCardX + rbPadX, rby, Math.max(rbH, rbW * rightSubBars[i]), rbH, rbH * 0.5);
      ctx.fillStyle = i === 0 ? COL_PEACH : COL_ROSE;
      ctx.fill();
    }
    ctx.restore();
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const rawLoopT = t % duration;
  const loopT = rawLoopT < 0 ? rawLoopT + duration : rawLoopT;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const u = loopT / duration;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, p) => a + (b - a) * p;
  const easeInOutCubic = (p) => {
    const x = clamp01(p);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  };
  const easeInOutSine = (p) => {
    const x = clamp01(p);
    return 0.5 * (1 - Math.cos(Math.PI * x));
  };
  const subRange = (p, a, b) => clamp01((p - a) / (b - a));

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  };

  // 1. Clean Steel Graphite Aesthetic Gradient Background (zero background glow)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#070D17");
  bgGrad.addColorStop(0.5, "#132238");
  bgGrad.addColorStop(1, "#09111E");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Palette constants
  const COL_SLATE_DEEP = "#0A1424";
  const COL_BOARD_BG = "#0F1D33";
  const COL_HEADER_BG = "#142642";
  const COL_BORDER = "#29497A";
  const COL_COBALT = "#3B82F6";
  const COL_AZURE = "#38BDF8";
  const COL_ICE_BLUE = "#93C5FD";
  const COL_SILVER = "#E2E8F0";

  // 2. Scene Choreography (3 Scenes, 20s Seamless Loop, Consistent Clockwise Exchange)
  let orbitAngle = 0; // 0 -> PI (Scene 1) -> TAU (Scene 2)
  let arrowDraw = 0.35; // 0.35..1.0 arrow extension
  let exchangePulse = 0;
  let leftRates = [0.76, 0.42, 0.58];
  let rightFxBars = [0.44, 0.58, 0.50, 0.66, 0.54];
  let spreadFill = 0.40;

  if (currentScene === 0) {
    // Scene 0 (0-6.67s): Currency pair initialization & parallel conversion arrows draw
    orbitAngle = 0;
    const arrP = easeInOutCubic(subRange(sceneProgress, 0.08, 0.85));
    arrowDraw = lerp(0.35, 1.0, arrP);
    exchangePulse = easeInOutSine(subRange(sceneProgress, 0.25, 0.95)) * 0.4;

    leftRates = [
      lerp(0.76, 0.84, arrP),
      lerp(0.42, 0.54, arrP),
      lerp(0.58, 0.68, arrP),
    ];
    const fxBase = [0.44, 0.58, 0.50, 0.66, 0.54];
    const fxMid = [0.54, 0.68, 0.62, 0.76, 0.64];
    rightFxBars = fxBase.map((v, idx) => lerp(v, fxMid[idx], arrP));
    spreadFill = lerp(0.40, 0.68, arrP);
  } else if (currentScene === 1) {
    // Scene 1 (6.67-13.33s): Smooth 180-deg clockwise non-colliding parallel currency swap
    const swapP = easeInOutCubic(subRange(sceneProgress, 0.08, 0.90));
    orbitAngle = lerp(0, Math.PI, swapP);
    arrowDraw = 1.0;
    exchangePulse = lerp(0.4, 1.0, easeInOutSine(sceneProgress));

    leftRates = [
      lerp(0.84, 0.52, swapP),
      lerp(0.54, 0.92, swapP),
      lerp(0.68, 0.86, swapP),
    ];
    const fxMid = [0.54, 0.68, 0.62, 0.76, 0.64];
    const fxPeak = [0.72, 0.88, 0.80, 0.94, 0.84];
    rightFxBars = fxMid.map((v, idx) => {
      const bp = easeInOutCubic(subRange(sceneProgress, 0.12 + idx * 0.05, 0.76 + idx * 0.04));
      return lerp(v, fxPeak[idx], bp);
    });
    spreadFill = lerp(0.68, 0.96, swapP);
  } else {
    // Scene 2 (13.33-20s): Controlled pause -> consistent clockwise completion to 360 (exact t=0)
    const retSwap = easeInOutCubic(subRange(sceneProgress, 0.14, 0.92));
    orbitAngle = lerp(Math.PI, TAU, retSwap);
    arrowDraw = lerp(1.0, 0.35, easeInOutCubic(subRange(sceneProgress, 0.30, 0.96)));
    exchangePulse = lerp(1.0, 0.0, easeInOutCubic(subRange(sceneProgress, 0.15, 0.95)));

    leftRates = [
      lerp(0.52, 0.76, retSwap),
      lerp(0.92, 0.42, retSwap),
      lerp(0.86, 0.58, retSwap),
    ];
    const fxPeak = [0.72, 0.88, 0.80, 0.94, 0.84];
    const fxBase = [0.44, 0.58, 0.50, 0.66, 0.54];
    rightFxBars = fxPeak.map((v, idx) => lerp(v, fxBase[idx], retSwap));
    spreadFill = lerp(0.96, 0.40, retSwap);
  }

  const cycleWave = 0.5 + 0.5 * Math.sin(TAU * u);

  // 3. Central Hero Icon: Global Currency Exchange & Dual-Coin Panel
  const bw = 0.620 * minSide;
  const bh = 0.460 * minSide;
  const bx = cx - bw * 0.5;
  const by = cy - bh * 0.5;
  const bRad = 0.028 * minSide;

  ctx.save();
  roundRectPath(bx, by, bw, bh, bRad);
  ctx.fillStyle = COL_BOARD_BG;
  ctx.fill();

  // Header strip clipped inside board top
  ctx.save();
  roundRectPath(bx, by, bw, bh, bRad);
  ctx.clip();
  ctx.fillStyle = COL_HEADER_BG;
  ctx.fillRect(bx, by, bw, 0.066 * minSide);
  ctx.restore();

  roundRectPath(bx, by, bw, bh, bRad);
  ctx.lineWidth = 0.003 * minSide;
  ctx.strokeStyle = COL_BORDER;
  ctx.stroke();

  const headerBotY = by + 0.066 * minSide;
  ctx.beginPath();
  ctx.moveTo(bx + 0.002 * minSide, headerBotY);
  ctx.lineTo(bx + bw - 0.002 * minSide, headerBotY);
  ctx.lineWidth = 0.0022 * minSide;
  ctx.strokeStyle = COL_BORDER;
  ctx.stroke();

  // Header Left: FX Market Status Indicators
  const hMidY = by + 0.033 * minSide;
  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(bx + 0.034 * minSide + d * 0.020 * minSide, hMidY, 0.005 * minSide, 0, TAU);
    ctx.fillStyle = d === 0 ? COL_AZURE : d === 1 ? COL_COBALT : "#2D528A";
    ctx.fill();
  }
  roundRectPath(bx + 0.104 * minSide, hMidY - 0.0065 * minSide, 0.110 * minSide, 0.013 * minSide, 0.0065 * minSide);
  ctx.fillStyle = "#1A3359";
  ctx.fill();
  roundRectPath(
    bx + 0.104 * minSide,
    hMidY - 0.0065 * minSide,
    0.110 * minSide * lerp(0.54, 0.94, spreadFill * 0.78 + cycleWave * 0.22),
    0.013 * minSide,
    0.0065 * minSide
  );
  ctx.fillStyle = COL_AZURE;
  ctx.fill();

  // Header Right: Clean FX Active Exchange Pill
  const hBadgeW = 0.118 * minSide;
  const hBadgeH = 0.030 * minSide;
  const hBadgeX = bx + bw - 0.028 * minSide - hBadgeW;
  const hBadgeY = hMidY - hBadgeH * 0.5;
  roundRectPath(hBadgeX, hBadgeY, hBadgeW, hBadgeH, hBadgeH * 0.5);
  ctx.fillStyle = COL_SLATE_DEEP;
  ctx.fill();
  ctx.lineWidth = 0.002 * minSide;
  ctx.strokeStyle = exchangePulse > 0.45 ? COL_AZURE : COL_BORDER;
  ctx.stroke();

  // Mini bi-directional arrows icon inside header pill
  const maX = hBadgeX + 0.024 * minSide;
  ctx.strokeStyle = COL_AZURE;
  ctx.lineWidth = 0.0024 * minSide;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(maX - 0.008 * minSide, hMidY - 0.004 * minSide);
  ctx.lineTo(maX + 0.008 * minSide, hMidY - 0.004 * minSide);
  ctx.moveTo(maX + 0.004 * minSide, hMidY - 0.008 * minSide);
  ctx.lineTo(maX + 0.008 * minSide, hMidY - 0.004 * minSide);
  ctx.moveTo(maX + 0.008 * minSide, hMidY + 0.004 * minSide);
  ctx.lineTo(maX - 0.008 * minSide, hMidY + 0.004 * minSide);
  ctx.moveTo(maX - 0.004 * minSide, hMidY + 0.008 * minSide);
  ctx.lineTo(maX - 0.008 * minSide, hMidY + 0.004 * minSide);
  ctx.stroke();

  // Mini fill pill inside header badge
  roundRectPath(hBadgeX + 0.046 * minSide, hMidY - 0.004 * minSide, 0.056 * minSide, 0.008 * minSide, 0.004 * minSide);
  ctx.fillStyle = "#1A3359";
  ctx.fill();
  roundRectPath(
    hBadgeX + 0.046 * minSide,
    hMidY - 0.004 * minSide,
    0.056 * minSide * lerp(0.40, 1.0, spreadFill),
    0.008 * minSide,
    0.004 * minSide
  );
  ctx.fillStyle = COL_COBALT;
  ctx.fill();

  // 4. Non-Colliding Parallel Currency Exchange Arena (centered at (cx, exCy))
  const exCy = headerBotY + (bh - 0.066 * minSide) * 0.5;
  const rx = 0.172 * minSide;
  const ry = 0.115 * minSide;
  const rCoin = 0.056 * minSide;

  // Subtle dashed elliptical path track showing the exact parallel lane trajectory
  ctx.save();
  ctx.setLineDash([0.008 * minSide, 0.008 * minSide]);
  ctx.beginPath();
  ctx.ellipse(cx, exCy, rx, ry, 0, 0, TAU);
  ctx.lineWidth = 0.0024 * minSide;
  ctx.strokeStyle = "rgba(56, 189, 248, 0.30)";
  ctx.stroke();
  ctx.restore();

  // Central Parallel Exchange Arrows (strictly inside |x - cx| <= 0.054*m, |y - exCy| <= 0.020*m -> >= 0.028*m clear of coins at ALL angles!)
  const arrowHalfLen = 0.048 * minSide * arrowDraw;
  const arrowGapY = 0.014 * minSide;
  const headSz = 0.009 * minSide;

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.lineWidth = 0.0046 * minSide;

  // Top arrow pointing RIGHT (Cobalt -> Azure)
  const topY = exCy - arrowGapY;
  const topGrad = ctx.createLinearGradient(cx - 0.048 * minSide, topY, cx + 0.048 * minSide, topY);
  topGrad.addColorStop(0, COL_COBALT);
  topGrad.addColorStop(1, COL_AZURE);
  ctx.strokeStyle = topGrad;
  ctx.beginPath();
  ctx.moveTo(cx - arrowHalfLen, topY);
  ctx.lineTo(cx + arrowHalfLen, topY);
  ctx.moveTo(cx + arrowHalfLen - headSz, topY - headSz * 0.72);
  ctx.lineTo(cx + arrowHalfLen, topY);
  ctx.lineTo(cx + arrowHalfLen - headSz, topY + headSz * 0.72);
  ctx.stroke();

  // Bottom arrow pointing LEFT (Azure -> Silver-Cobalt)
  const botY = exCy + arrowGapY;
  const botGrad = ctx.createLinearGradient(cx + 0.048 * minSide, botY, cx - 0.048 * minSide, botY);
  botGrad.addColorStop(0, COL_AZURE);
  botGrad.addColorStop(1, COL_ICE_BLUE);
  ctx.strokeStyle = botGrad;
  ctx.beginPath();
  ctx.moveTo(cx + arrowHalfLen, botY);
  ctx.lineTo(cx - arrowHalfLen, botY);
  ctx.moveTo(cx - arrowHalfLen + headSz, botY - headSz * 0.72);
  ctx.lineTo(cx - arrowHalfLen, botY);
  ctx.lineTo(cx - arrowHalfLen + headSz, botY + headSz * 0.72);
  ctx.stroke();
  ctx.restore();

  // Helper: Draw a clean Modern Flat-Vector Currency Coin (zero brand logos!)
  const drawCurrencyCoin = (x, y, variant) => {
    ctx.save();
    ctx.translate(x, y);

    // Outer metallic ring
    const cGrad = ctx.createLinearGradient(-rCoin, -rCoin, rCoin, rCoin);
    if (variant === 0) {
      cGrad.addColorStop(0, "#60A5FA");
      cGrad.addColorStop(0.5, COL_COBALT);
      cGrad.addColorStop(1, "#1D4ED8");
    } else {
      cGrad.addColorStop(0, "#7DD3FC");
      cGrad.addColorStop(0.5, COL_AZURE);
      cGrad.addColorStop(1, "#0284C7");
    }
    ctx.beginPath();
    ctx.arc(0, 0, rCoin, 0, TAU);
    ctx.fillStyle = cGrad;
    ctx.fill();

    // Inner recessed dark slate face
    ctx.beginPath();
    ctx.arc(0, 0, rCoin * 0.80, 0, TAU);
    ctx.fillStyle = COL_SLATE_DEEP;
    ctx.fill();
    ctx.lineWidth = 0.0024 * minSide;
    ctx.strokeStyle = variant === 0 ? COL_ICE_BLUE : COL_SILVER;
    ctx.stroke();

    // Universal geometric value emblem inside coin (strictly non-brand!)
    if (variant === 0) {
      // Coin A: Crisp Dual Horizontal Monetary Bars + Vertical Spine
      ctx.strokeStyle = COL_SILVER;
      ctx.lineWidth = 0.0052 * minSide;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(0, -rCoin * 0.38);
      ctx.lineTo(0, rCoin * 0.38);
      ctx.moveTo(-rCoin * 0.28, -rCoin * 0.14);
      ctx.lineTo(rCoin * 0.28, -rCoin * 0.14);
      ctx.moveTo(-rCoin * 0.28, rCoin * 0.14);
      ctx.lineTo(rCoin * 0.28, rCoin * 0.14);
      ctx.stroke();
    } else {
      // Coin B: Crisp Faceted Geometric Value Diamond
      const dH = rCoin * 0.40;
      const dW = rCoin * 0.28;
      ctx.beginPath();
      ctx.moveTo(0, -dH);
      ctx.lineTo(dW, 0);
      ctx.lineTo(0, dH);
      ctx.lineTo(-dW, 0);
      ctx.closePath();
      ctx.fillStyle = COL_AZURE;
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(0, -dH);
      ctx.lineTo(0, dH);
      ctx.lineTo(-dW, 0);
      ctx.closePath();
      ctx.fillStyle = COL_SILVER;
      ctx.fill();
    }
    ctx.restore();
  };

  // Coin A starts at Left (angle = PI), orbits clockwise (PI -> 2*PI -> 3*PI)
  // Coin B starts at Right (angle = 0), orbits clockwise (0 -> PI -> 2*PI)
  const angA = Math.PI + orbitAngle;
  const angB = orbitAngle;

  const coinAx = cx + Math.cos(angA) * rx;
  const coinAy = exCy + Math.sin(angA) * ry;
  const coinBx = cx + Math.cos(angB) * rx;
  const coinBy = exCy + Math.sin(angB) * ry;

  drawCurrencyCoin(coinAx, coinAy, 0);
  drawCurrencyCoin(coinBx, coinBy, 1);

  ctx.restore();

  // 5. Symmetrical Flanking FX Telemetry Cards (Left Rate Pairs & Right FX Liquidity Bars)
  const cardW = 0.210 * minSide;
  const cardH = 0.250 * minSide;
  const leftCardX = cx - 0.630 * minSide;
  const rightCardX = cx + 0.420 * minSide;
  const cardY = cy - cardH * 0.5;

  // Left Card: FX Pair Allocation & Conversion Ratios
  if (leftCardX > 0.03 * width) {
    ctx.save();
    roundRectPath(leftCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_BOARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const padX = 0.024 * minSide;
    roundRectPath(leftCardX + padX, cardY + 0.028 * minSide, 0.088 * minSide, 0.012 * minSide, 0.006 * minSide);
    ctx.fillStyle = "#1E3A66";
    ctx.fill();

    const rowStartY = cardY + 0.072 * minSide;
    const rowGapY = 0.054 * minSide;
    const dotR = 0.008 * minSide;
    const barX = leftCardX + padX + dotR * 2 + 0.012 * minSide;
    const barW = cardW - padX * 2 - dotR * 2 - 0.012 * minSide;
    const barH = 0.014 * minSide;

    for (let s = 0; s < 3; s++) {
      const ryRow = rowStartY + s * rowGapY;
      const val = leftRates[s];
      ctx.beginPath();
      ctx.arc(leftCardX + padX + dotR, ryRow + barH * 0.5, dotR, 0, TAU);
      ctx.fillStyle = s === 0 ? COL_COBALT : s === 1 ? COL_AZURE : COL_SILVER;
      ctx.fill();

      roundRectPath(barX, ryRow, barW, barH, barH * 0.5);
      ctx.fillStyle = COL_SLATE_DEEP;
      ctx.fill();

      roundRectPath(barX, ryRow, Math.max(barH, barW * val), barH, barH * 0.5);
      const lGrad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
      lGrad.addColorStop(0, COL_COBALT);
      lGrad.addColorStop(1, COL_AZURE);
      ctx.fillStyle = lGrad;
      ctx.fill();
    }
    ctx.restore();
  }

  // Right Card: FX Rate Mini Bar Chart & Spread Bar
  if (rightCardX + cardW < width - 0.03 * width) {
    ctx.save();
    roundRectPath(rightCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_BOARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const rPadX = 0.024 * minSide;
    const topBarW = cardW - rPadX * 2;
    const topBarH = 0.012 * minSide;
    const topBarY = cardY + 0.030 * minSide;

    roundRectPath(rightCardX + rPadX, topBarY, topBarW, topBarH, topBarH * 0.5);
    ctx.fillStyle = COL_SLATE_DEEP;
    ctx.fill();

    roundRectPath(rightCardX + rPadX, topBarY, Math.max(topBarH, topBarW * spreadFill), topBarH, topBarH * 0.5);
    ctx.fillStyle = COL_AZURE;
    ctx.fill();

    // 5 strictly separated vertical FX bars
    const baselineY = cardY + cardH - 0.030 * minSide;
    const maxBarH = 0.146 * minSide;
    const vBarW = 0.019 * minSide;
    const vPitch = 0.033 * minSide;
    const vStartX = rightCardX + cardW * 0.5 - 2 * vPitch - vBarW * 0.5;

    for (let i = 0; i < 5; i++) {
      const barLeft = vStartX + i * vPitch;
      roundRectPath(barLeft, baselineY - maxBarH, vBarW, maxBarH, 0.005 * minSide);
      ctx.fillStyle = COL_SLATE_DEEP;
      ctx.fill();

      const fh = Math.max(0.015 * minSide, maxBarH * rightFxBars[i]);
      roundRectPath(barLeft, baselineY - fh, vBarW, fh, 0.005 * minSide);
      const vGrad = ctx.createLinearGradient(barLeft, baselineY - fh, barLeft, baselineY);
      vGrad.addColorStop(0, COL_SILVER);
      vGrad.addColorStop(0.45, COL_AZURE);
      vGrad.addColorStop(1, COL_COBALT);
      ctx.fillStyle = vGrad;
      ctx.fill();
    }
    ctx.restore();
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const rawLoopT = t % duration;
  const loopT = rawLoopT < 0 ? rawLoopT + duration : rawLoopT;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const u = loopT / duration;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, p) => a + (b - a) * p;
  const easeInOutCubic = (p) => {
    const x = clamp01(p);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  };
  const easeInOutSine = (p) => {
    const x = clamp01(p);
    return 0.5 * (1 - Math.cos(Math.PI * x));
  };
  const subRange = (p, a, b) => clamp01((p - a) / (b - a));

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  };

  // Helper: Clean modern flat-vector Shield contour centered around (cx, cy)
  const traceShieldPath = (scale) => {
    const hw = 0.180 * minSide * scale;
    const topY = cy - 0.214 * minSide * scale;
    const shoulderY = cy - 0.156 * minSide * scale;
    const midY = cy + 0.020 * minSide * scale;
    const botY = cy + 0.224 * minSide * scale;

    ctx.beginPath();
    ctx.moveTo(cx, topY);
    ctx.bezierCurveTo(cx + hw * 0.42, topY + 0.010 * minSide * scale, cx + hw * 0.84, shoulderY - 0.008 * minSide * scale, cx + hw, shoulderY);
    ctx.lineTo(cx + hw, midY);
    ctx.bezierCurveTo(cx + hw, cy + 0.125 * minSide * scale, cx + hw * 0.48, cy + 0.192 * minSide * scale, cx, botY);
    ctx.bezierCurveTo(cx - hw * 0.48, cy + 0.192 * minSide * scale, cx - hw, cy + 0.125 * minSide * scale, cx - hw, midY);
    ctx.lineTo(cx - hw, shoulderY);
    ctx.bezierCurveTo(cx - hw * 0.84, shoulderY - 0.008 * minSide * scale, cx - hw * 0.42, topY + 0.010 * minSide * scale, cx, topY);
    ctx.closePath();
  };

  // 1. Clean Dark Crimson Slate Aesthetic Gradient Background (zero background glow)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#14070B");
  bgGrad.addColorStop(0.5, "#2B0F1A");
  bgGrad.addColorStop(1, "#17080E");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Palette constants
  const COL_BURGUNDY_DEEP = "#18080F";
  const COL_CARD_BG = "#210B14";
  const COL_SHIELD_OUT = "#2B101B";
  const COL_BORDER = "#61253D";
  const COL_CORAL = "#FF4D6D";
  const COL_ROSE = "#FB7185";
  const COL_TANGERINE = "#FF7B3B";
  const COL_BLUSH = "#FFE5EC";

  // 2. Scene Choreography (3 Scenes, 20s Seamless Loop)
  // Padlock & Checkmark use strictly non-overlapping alpha windows so they NEVER intersect
  let shackleLock = 0; // 0 = standby raised, 1 = locked down
  let padlockAlpha = 1;
  let padlockScale = 1;
  let checkAlpha = 0;
  let checkDraw = 0; // 0..1 trim-path draw
  let ringFill = 0.25;
  let leftProtBars = [0.36, 0.28, 0.24];
  let rightTrustGauge = 0.34;
  let rightSubBars = [0.36, 0.30];

  if (currentScene === 0) {
    // Scene 0 (0-6.67s): Padlock shackle drops cleanly to lock & protection checks fill
    shackleLock = easeInOutCubic(subRange(sceneProgress, 0.14, 0.72));
    padlockAlpha = 1;
    padlockScale = 1;
    checkAlpha = 0;
    checkDraw = 0;

    const g0 = easeInOutCubic(sceneProgress);
    ringFill = lerp(0.25, 0.62, g0);
    leftProtBars = [
      lerp(0.36, 0.94, easeInOutCubic(subRange(sceneProgress, 0.05, 0.55))),
      lerp(0.28, 0.90, easeInOutCubic(subRange(sceneProgress, 0.24, 0.76))),
      lerp(0.24, 0.86, easeInOutCubic(subRange(sceneProgress, 0.42, 0.95))),
    ];
    rightTrustGauge = lerp(0.34, 0.64, g0);
    rightSubBars = [lerp(0.36, 0.62, g0), lerp(0.30, 0.56, g0)];
  } else if (currentScene === 1) {
    // Scene 1 (6.67-13.33s): Outer verification ring completes & clean handoff from Padlock -> Verified Checkmark
    shackleLock = 1;
    const lockOut = easeInOutCubic(subRange(sceneProgress, 0.10, 0.36));
    padlockAlpha = 1 - lockOut;
    padlockScale = lerp(1.0, 0.84, lockOut);

    // Strictly begins after padlockAlpha reaches 0 (0.38 > 0.36)
    const chkIn = easeInOutSine(subRange(sceneProgress, 0.38, 0.50));
    checkAlpha = chkIn;
    checkDraw = easeInOutSine(subRange(sceneProgress, 0.38, 0.78));

    const g1 = easeInOutCubic(subRange(sceneProgress, 0.06, 0.92));
    ringFill = lerp(0.62, 1.00, g1);
    leftProtBars = [0.94, 0.90, 0.86];
    rightTrustGauge = lerp(0.64, 0.96, g1);
    rightSubBars = [lerp(0.62, 0.94, g1), lerp(0.56, 0.88, g1)];
  } else {
    // Scene 2 (13.33-20s): Controlled hold -> Checkmark exits -> Padlock returns -> Shackle rises back to t=0
    const chkOut = easeInOutSine(subRange(sceneProgress, 0.16, 0.38));
    checkAlpha = 1 - chkOut;
    checkDraw = 1 - easeInOutSine(subRange(sceneProgress, 0.16, 0.38));

    // Padlock strictly enters after checkAlpha reaches 0 (0.40 > 0.38)
    const lockIn = easeInOutCubic(subRange(sceneProgress, 0.40, 0.62));
    padlockAlpha = lockIn;
    padlockScale = lerp(0.84, 1.0, lockIn);
    shackleLock = 1 - easeInOutCubic(subRange(sceneProgress, 0.60, 0.95));

    const retP = easeInOutCubic(subRange(sceneProgress, 0.22, 0.96));
    ringFill = lerp(1.00, 0.25, retP);
    leftProtBars = [
      lerp(0.94, 0.36, easeInOutCubic(subRange(sceneProgress, 0.30, 0.90))),
      lerp(0.90, 0.28, easeInOutCubic(subRange(sceneProgress, 0.36, 0.93))),
      lerp(0.86, 0.24, easeInOutCubic(subRange(sceneProgress, 0.42, 0.96))),
    ];
    rightTrustGauge = lerp(0.96, 0.34, retP);
    rightSubBars = [lerp(0.94, 0.36, retP), lerp(0.88, 0.30, retP)];
  }

  const cycleWave = 0.5 + 0.5 * Math.sin(TAU * u);

  // 3. Outer Segmented Verification Progress Ring (r = 0.304*m — >= 0.062*m clear outside shield!)
  ctx.save();
  ctx.translate(cx, cy);
  const rRing = 0.304 * minSide;
  const quadCenters = [Math.PI * 0.25, Math.PI * 0.75, Math.PI * 1.25, Math.PI * 1.75];
  const halfSpan = (32 * Math.PI) / 180; // 64 deg arc per quadrant, crisp 26 deg gaps at cardinal axes
  ctx.lineCap = "round";

  for (let q = 0; q < 4; q++) {
    const midA = quadCenters[q];
    // Background track
    ctx.beginPath();
    ctx.arc(0, 0, rRing, midA - halfSpan, midA + halfSpan);
    ctx.lineWidth = 0.010 * minSide;
    ctx.strokeStyle = "#321220";
    ctx.stroke();

    // Symmetrical fill from midpoint outward
    const fillSpan = halfSpan * ringFill;
    if (fillSpan > 0.005) {
      ctx.beginPath();
      ctx.arc(0, 0, rRing, midA - fillSpan, midA + fillSpan);
      ctx.lineWidth = 0.010 * minSide;
      const aGrad = ctx.createLinearGradient(
        Math.cos(midA - halfSpan) * rRing,
        Math.sin(midA - halfSpan) * rRing,
        Math.cos(midA + halfSpan) * rRing,
        Math.sin(midA + halfSpan) * rRing
      );
      aGrad.addColorStop(0, COL_CORAL);
      aGrad.addColorStop(0.5, COL_TANGERINE);
      aGrad.addColorStop(1, COL_CORAL);
      ctx.strokeStyle = aGrad;
      ctx.stroke();
    }
  }
  ctx.restore();

  // 4. Central Hero Icon: Multi-Layered Financial Security Shield
  ctx.save();
  // Outer shield frame
  traceShieldPath(1.0);
  const outGrad = ctx.createLinearGradient(cx, cy - 0.214 * minSide, cx, cy + 0.224 * minSide);
  outGrad.addColorStop(0, "#3A1626");
  outGrad.addColorStop(1, COL_SHIELD_OUT);
  ctx.fillStyle = outGrad;
  ctx.fill();

  const rimGrad = ctx.createLinearGradient(cx - 0.18 * minSide, cy - 0.21 * minSide, cx + 0.18 * minSide, cy + 0.22 * minSide);
  rimGrad.addColorStop(0, COL_TANGERINE);
  rimGrad.addColorStop(0.5, COL_CORAL);
  rimGrad.addColorStop(1, "#9E2A47");
  ctx.lineWidth = 0.005 * minSide;
  ctx.strokeStyle = rimGrad;
  ctx.stroke();

  // Inner recessed shield plate (strictly inset at scale = 0.84)
  traceShieldPath(0.84);
  ctx.fillStyle = COL_BURGUNDY_DEEP;
  ctx.fill();

  // Crisp flat-vector two-tone left facet shading clipped inside inner shield
  ctx.save();
  traceShieldPath(0.84);
  ctx.clip();
  ctx.fillStyle = "#200A13";
  ctx.fillRect(cx - 0.18 * minSide, cy - 0.22 * minSide, 0.18 * minSide, 0.46 * minSide);
  ctx.restore();

  // Inner shield clean hairline rim
  traceShieldPath(0.84);
  ctx.lineWidth = 0.0024 * minSide;
  ctx.strokeStyle = COL_BORDER;
  ctx.stroke();

  // Central Emblem Medallion inside shield belly (r = 0.088*m, centered at (cx, cy - 0.008*m))
  const medCy = cy - 0.008 * minSide;
  const medR = 0.088 * minSide;

  ctx.beginPath();
  ctx.arc(cx, medCy, medR, 0, TAU);
  ctx.fillStyle = "#250D17";
  ctx.fill();
  ctx.lineWidth = 0.0032 * minSide;
  ctx.strokeStyle = checkAlpha > 0.3 ? COL_TANGERINE : COL_CORAL;
  ctx.stroke();

  // --- STATE A: Banking Security Padlock (strictly separated alpha window from Checkmark) ---
  if (padlockAlpha > 0.01) {
    ctx.save();
    ctx.translate(cx, medCy);
    ctx.scale(padlockScale, padlockScale);
    ctx.globalAlpha = padlockAlpha;

    const lockW = 0.072 * minSide;
    const lockH = 0.054 * minSide;
    const lockTopY = -0.008 * minSide;

    // Shackle clipped strictly above lockTopY so legs tuck cleanly behind lock body
    ctx.save();
    ctx.beginPath();
    ctx.rect(-0.06 * minSide, -0.08 * minSide, 0.12 * minSide, lockTopY + 0.08 * minSide);
    ctx.clip();

    const shackleR = 0.022 * minSide;
    const shackleOffset = lerp(-0.014 * minSide, 0, shackleLock);
    const shackleArchCy = lockTopY - 0.014 * minSide + shackleOffset;

    ctx.beginPath();
    ctx.moveTo(-shackleR, lockTopY + 0.006 * minSide);
    ctx.lineTo(-shackleR, shackleArchCy);
    ctx.arc(0, shackleArchCy, shackleR, Math.PI, 0, false);
    ctx.lineTo(shackleR, lockTopY + 0.006 * minSide);
    ctx.lineWidth = 0.0085 * minSide;
    ctx.lineCap = "round";
    ctx.strokeStyle = COL_BLUSH;
    ctx.stroke();
    ctx.restore();

    // Padlock body
    roundRectPath(-lockW * 0.5, lockTopY, lockW, lockH, 0.010 * minSide);
    const lockGrad = ctx.createLinearGradient(-lockW * 0.5, lockTopY, lockW * 0.5, lockTopY + lockH);
    lockGrad.addColorStop(0, COL_TANGERINE);
    lockGrad.addColorStop(1, COL_CORAL);
    ctx.fillStyle = lockGrad;
    ctx.fill();

    // Keyhole emblem inside padlock body
    const keyY = lockTopY + lockH * 0.42;
    ctx.beginPath();
    ctx.arc(0, keyY, 0.0075 * minSide, 0, TAU);
    ctx.fillStyle = COL_BURGUNDY_DEEP;
    ctx.fill();

    roundRectPath(-0.0035 * minSide, keyY + 0.003 * minSide, 0.007 * minSide, 0.015 * minSide, 0.003 * minSide);
    ctx.fillStyle = COL_BURGUNDY_DEEP;
    ctx.fill();

    ctx.restore();
  }

  // --- STATE B: Verified Transaction Checkmark (strictly after padlockAlpha == 0) ---
  if (checkAlpha > 0.01 && checkDraw > 0.01) {
    ctx.save();
    ctx.translate(cx, medCy);
    ctx.globalAlpha = checkAlpha;

    // 3 vertices of crisp centered checkmark strictly inside medallion
    const pA = { x: -0.036 * minSide, y: 0.002 * minSide };
    const pB = { x: -0.009 * minSide, y: 0.028 * minSide };
    const pC = { x: 0.040 * minSide, y: -0.026 * minSide };

    const seg1Len = Math.hypot(pB.x - pA.x, pB.y - pA.y);
    const seg2Len = Math.hypot(pC.x - pB.x, pC.y - pB.y);
    const totalLen = seg1Len + seg2Len;
    const drawLen = totalLen * checkDraw;

    ctx.beginPath();
    ctx.moveTo(pA.x, pA.y);
    if (drawLen <= seg1Len) {
      const f = drawLen / seg1Len;
      ctx.lineTo(lerp(pA.x, pB.x, f), lerp(pA.y, pB.y, f));
    } else {
      ctx.lineTo(pB.x, pB.y);
      const f = (drawLen - seg1Len) / seg2Len;
      ctx.lineTo(lerp(pB.x, pC.x, f), lerp(pB.y, pC.y, f));
    }

    const chkGrad = ctx.createLinearGradient(pA.x, pB.y, pC.x, pC.y);
    chkGrad.addColorStop(0, COL_CORAL);
    chkGrad.addColorStop(0.5, COL_TANGERINE);
    chkGrad.addColorStop(1, COL_BLUSH);
    ctx.strokeStyle = chkGrad;
    ctx.lineWidth = 0.011 * minSide;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.stroke();

    ctx.restore();
  }
  ctx.restore();

  // 5. Symmetrical Flanking Security & Audit Cards (Strictly clear of outer verification ring)
  const cardW = 0.210 * minSide;
  const cardH = 0.250 * minSide;
  const leftCardX = cx - 0.630 * minSide;
  const rightCardX = cx + 0.420 * minSide;
  const cardY = cy - cardH * 0.5;

  // Left Card: 3 Banking Protection Layers
  if (leftCardX > 0.03 * width) {
    ctx.save();
    roundRectPath(leftCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_CARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const padX = 0.024 * minSide;
    roundRectPath(leftCardX + padX, cardY + 0.028 * minSide, 0.088 * minSide, 0.012 * minSide, 0.006 * minSide);
    ctx.fillStyle = "#542035";
    ctx.fill();

    const rowStartY = cardY + 0.072 * minSide;
    const rowGapY = 0.054 * minSide;
    const dotR = 0.008 * minSide;
    const barX = leftCardX + padX + dotR * 2 + 0.012 * minSide;
    const barW = cardW - padX * 2 - dotR * 2 - 0.012 * minSide;
    const barH = 0.014 * minSide;

    for (let s = 0; s < 3; s++) {
      const ry = rowStartY + s * rowGapY;
      const val = leftProtBars[s];
      ctx.beginPath();
      ctx.arc(leftCardX + padX + dotR, ry + barH * 0.5, dotR, 0, TAU);
      ctx.fillStyle = val > 0.72 ? COL_TANGERINE : "#63263E";
      ctx.fill();

      roundRectPath(barX, ry, barW, barH, barH * 0.5);
      ctx.fillStyle = COL_BURGUNDY_DEEP;
      ctx.fill();

      roundRectPath(barX, ry, Math.max(barH, barW * val), barH, barH * 0.5);
      const bGrad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
      bGrad.addColorStop(0, COL_CORAL);
      bGrad.addColorStop(1, COL_TANGERINE);
      ctx.fillStyle = bGrad;
      ctx.fill();
    }
    ctx.restore();
  }

  // Right Card: Trust & Compliance Verification Gauge + 2 Audit Bars
  if (rightCardX + cardW < width - 0.03 * width) {
    ctx.save();
    roundRectPath(rightCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_CARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const gcx = rightCardX + cardW * 0.5;
    const gcy = cardY + 0.092 * minSide;
    const gr = 0.052 * minSide;
    const startA = Math.PI * 0.78;
    const spanA = Math.PI * 1.44;

    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA);
    ctx.lineWidth = 0.011 * minSide;
    ctx.strokeStyle = COL_BURGUNDY_DEEP;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA * rightTrustGauge);
    const gGrad = ctx.createLinearGradient(gcx - gr, gcy, gcx + gr, gcy);
    gGrad.addColorStop(0, COL_CORAL);
    gGrad.addColorStop(1, COL_TANGERINE);
    ctx.strokeStyle = gGrad;
    ctx.stroke();

    // Clean Mini Shield Emblem inside Gauge Center
    const msW = 0.015 * minSide;
    const msTop = gcy - 0.017 * minSide;
    const msBot = gcy + 0.019 * minSide;
    ctx.beginPath();
    ctx.moveTo(gcx, msTop);
    ctx.lineTo(gcx + msW, msTop + 0.006 * minSide);
    ctx.lineTo(gcx + msW, gcy + 0.003 * minSide);
    ctx.quadraticCurveTo(gcx + msW, msBot - 0.004 * minSide, gcx, msBot);
    ctx.quadraticCurveTo(gcx - msW, msBot - 0.004 * minSide, gcx - msW, gcy + 0.003 * minSide);
    ctx.lineTo(gcx - msW, msTop + 0.006 * minSide);
    ctx.closePath();
    ctx.fillStyle = rightTrustGauge > 0.72 ? COL_TANGERINE : COL_ROSE;
    ctx.fill();

    // 2 Horizontal Audit Bars beneath gauge
    const rbPadX = 0.024 * minSide;
    const rbW = cardW - rbPadX * 2;
    const rbH = 0.013 * minSide;
    for (let i = 0; i < 2; i++) {
      const rby = cardY + 0.172 * minSide + i * 0.032 * minSide;
      roundRectPath(rightCardX + rbPadX, rby, rbW, rbH, rbH * 0.5);
      ctx.fillStyle = COL_BURGUNDY_DEEP;
      ctx.fill();

      roundRectPath(rightCardX + rbPadX, rby, Math.max(rbH, rbW * rightSubBars[i]), rbH, rbH * 0.5);
      ctx.fillStyle = i === 0 ? COL_TANGERINE : COL_CORAL;
      ctx.fill();
    }
    ctx.restore();
  }

  void cycleWave;
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const rawLoopT = t % duration;
  const loopT = rawLoopT < 0 ? rawLoopT + duration : rawLoopT;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const u = loopT / duration;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, p) => a + (b - a) * p;
  const easeInOutCubic = (p) => {
    const x = clamp01(p);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  };
  const easeInOutSine = (p) => {
    const x = clamp01(p);
    return 0.5 * (1 - Math.cos(Math.PI * x));
  };
  const subRange = (p, a, b) => clamp01((p - a) / (b - a));

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  };

  // 1. Clean Abyssal Indigo Aesthetic Gradient Background (zero background glow)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#090518");
  bgGrad.addColorStop(0.5, "#1A0F3B");
  bgGrad.addColorStop(1, "#0C0720");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Palette constants
  const COL_INDIGO_DEEP = "#100826";
  const COL_CARD_BG = "#160D33";
  const COL_WALLET_TOP = "#261854";
  const COL_WALLET_BOT = "#180E38";
  const COL_BORDER = "#422D85";
  const COL_VIOLET = "#8B5CF6";
  const COL_ORCHID = "#C084FC";
  const COL_MAGENTA = "#EC4899";
  const COL_LAVENDER = "#EDE9FE";

  // 2. Scene Choreography (3 Scenes, 20s Seamless Loop)
  let claspUnlock = 0; // 0 = locked, 1 = unlocked
  let cardSlide = 0; // 0 = tucked in wallet, 1 = extended
  let nfcActive = 0; // 0..1 wave activation
  let nfcPulsePhase = 0; // 0..2 cycles during scene 1
  let coinLaneActive = 0;
  let coinStreamT = 0; // 0..1 continuous travel during scene 1
  let leftStatus = [0.36, 0.30, 0.24];
  let rightBalanceRing = 0.34;
  let rightSubBars = [0.38, 0.30];
  let walletFill = 0.42;

  if (currentScene === 0) {
    // Scene 0 (0-6.67s): Wallet clasp unlocks & payment card smoothly slides out
    claspUnlock = easeInOutCubic(subRange(sceneProgress, 0.0, 0.38));
    cardSlide = easeInOutCubic(subRange(sceneProgress, 0.24, 0.94));
    const g0 = easeInOutCubic(sceneProgress);

    leftStatus = [
      lerp(0.36, 0.92, easeInOutCubic(subRange(sceneProgress, 0.05, 0.55))),
      lerp(0.30, 0.86, easeInOutCubic(subRange(sceneProgress, 0.22, 0.76))),
      lerp(0.24, 0.80, easeInOutCubic(subRange(sceneProgress, 0.42, 0.95))),
    ];
    rightBalanceRing = lerp(0.34, 0.54, g0);
    rightSubBars = [lerp(0.38, 0.56, g0), lerp(0.30, 0.48, g0)];
    walletFill = lerp(0.42, 0.62, g0);
  } else if (currentScene === 1) {
    // Scene 1 (6.67-13.33s): Sequential contactless NFC waves & spaced coin transfer to balance card
    claspUnlock = 1;
    cardSlide = 1;
    nfcActive = easeInOutSine(subRange(sceneProgress, 0.0, 0.16)) * (1 - easeInOutSine(subRange(sceneProgress, 0.86, 1.0)));
    nfcPulsePhase = sceneProgress * 2.0; // 2 clean sequential wave ripples
    coinLaneActive = easeInOutSine(subRange(sceneProgress, 0.04, 0.16)) * (1 - easeInOutSine(subRange(sceneProgress, 0.84, 0.98)));
    coinStreamT = sceneProgress;

    const pFill = easeInOutCubic(subRange(sceneProgress, 0.12, 0.92));
    leftStatus = [0.92, 0.86, 0.80];
    rightBalanceRing = lerp(0.54, 0.95, pFill);
    rightSubBars = [lerp(0.56, 0.94, pFill), lerp(0.48, 0.86, pFill)];
    walletFill = lerp(0.62, 0.96, pFill);
  } else {
    // Scene 2 (13.33-20s): Controlled hold, card glides back in, clasp locks, exact return to t=0
    cardSlide = 1 - easeInOutCubic(subRange(sceneProgress, 0.16, 0.72));
    claspUnlock = 1 - easeInOutCubic(subRange(sceneProgress, 0.62, 0.96));
    const retP = easeInOutCubic(subRange(sceneProgress, 0.22, 0.95));

    leftStatus = [
      lerp(0.92, 0.36, easeInOutCubic(subRange(sceneProgress, 0.28, 0.90))),
      lerp(0.86, 0.30, easeInOutCubic(subRange(sceneProgress, 0.34, 0.93))),
      lerp(0.80, 0.24, easeInOutCubic(subRange(sceneProgress, 0.40, 0.96))),
    ];
    rightBalanceRing = lerp(0.95, 0.34, retP);
    rightSubBars = [lerp(0.94, 0.38, retP), lerp(0.86, 0.30, retP)];
    walletFill = lerp(0.96, 0.42, retP);
  }

  const cycleWave = 0.5 + 0.5 * Math.sin(TAU * u);

  // Core Wallet & Card Layout Constants
  const walletW = 0.420 * minSide;
  const walletH = 0.250 * minSide;
  const walletX = cx - walletW * 0.5; // cx - 0.210*m .. cx + 0.210*m
  const walletTopY = cy - 0.015 * minSide;
  const walletRad = 0.030 * minSide;

  // 3. Wallet Rear Pocket Lip (sits cleanly behind payment card)
  ctx.save();
  roundRectPath(walletX + 0.016 * minSide, walletTopY - 0.014 * minSide, walletW - 0.032 * minSide, 0.038 * minSide, 0.014 * minSide);
  ctx.fillStyle = "#130A2C";
  ctx.fill();
  ctx.lineWidth = 0.0022 * minSide;
  ctx.strokeStyle = "#3A2675";
  ctx.stroke();
  ctx.restore();

  // 4. Sliding Corporate Payment Card (Clipped strictly above walletTopY so clean emergence from pocket)
  const payCardW = 0.340 * minSide;
  const payCardH = 0.205 * minSide;
  const payCardX = cx - payCardW * 0.5; // cx - 0.170*m .. cx + 0.170*m
  const payCardTopY = lerp(walletTopY - 0.044 * minSide, walletTopY - 0.172 * minSide, cardSlide);

  ctx.save();
  ctx.beginPath();
  ctx.rect(payCardX - 0.01 * minSide, 0, payCardW + 0.02 * minSide, walletTopY);
  ctx.clip();

  // Payment Card Base Gradient Body
  roundRectPath(payCardX, payCardTopY, payCardW, payCardH, 0.022 * minSide);
  const pcGrad = ctx.createLinearGradient(payCardX, payCardTopY, payCardX + payCardW, payCardTopY + payCardH);
  pcGrad.addColorStop(0, COL_MAGENTA);
  pcGrad.addColorStop(0.52, COL_VIOLET);
  pcGrad.addColorStop(1, "#5B21B6");
  ctx.fillStyle = pcGrad;
  ctx.fill();

  // Crisp light rim along payment card
  ctx.lineWidth = 0.0026 * minSide;
  ctx.strokeStyle = "rgba(237, 233, 254, 0.45)";
  ctx.stroke();

  // Subtle top geometric highlight band inside top 0.030*m of card (always clear of wallet lip)
  roundRectPath(payCardX + 0.018 * minSide, payCardTopY + 0.012 * minSide, payCardW - 0.036 * minSide, 0.008 * minSide, 0.004 * minSide);
  ctx.fillStyle = "rgba(237, 233, 254, 0.26)";
  ctx.fill();

  // Post-clearance reveals for internal card elements (never sliced by wallet lip!)
  const chipReveal = easeInOutCubic(subRange(cardSlide, 0.26, 0.58));
  const numReveal = easeInOutCubic(subRange(cardSlide, 0.56, 0.84));
  const footerReveal = easeInOutCubic(subRange(cardSlide, 0.78, 0.98));

  // EMV Chip & Corporate Geometric Emblem (bottom at payCardTopY + 0.064*m)
  if (chipReveal > 0.01) {
    ctx.save();
    ctx.globalAlpha = chipReveal;

    // EMV Chip left
    const chipX = payCardX + 0.030 * minSide;
    const chipY = payCardTopY + 0.032 * minSide;
    const chipW = 0.044 * minSide;
    const chipH = 0.032 * minSide;
    roundRectPath(chipX, chipY, chipW, chipH, 0.006 * minSide);
    const chipGrad = ctx.createLinearGradient(chipX, chipY, chipX + chipW, chipY + chipH);
    chipGrad.addColorStop(0, COL_LAVENDER);
    chipGrad.addColorStop(1, "#D8B4FE");
    ctx.fillStyle = chipGrad;
    ctx.fill();

    // Clean internal EMV grid lines (inset neatly inside chip)
    ctx.strokeStyle = "#6D28D9";
    ctx.lineWidth = 0.002 * minSide;
    ctx.beginPath();
    ctx.moveTo(chipX + chipW * 0.34, chipY + 0.003 * minSide);
    ctx.lineTo(chipX + chipW * 0.34, chipY + chipH - 0.003 * minSide);
    ctx.moveTo(chipX + chipW * 0.66, chipY + 0.003 * minSide);
    ctx.lineTo(chipX + chipW * 0.66, chipY + chipH - 0.003 * minSide);
    ctx.moveTo(chipX + 0.003 * minSide, chipY + chipH * 0.5);
    ctx.lineTo(chipX + chipW - 0.003 * minSide, chipY + chipH * 0.5);
    ctx.stroke();

    // Clean Right-Side Geometric Issuer Badge (2 strictly separated crisp diamonds, zero brand logo)
    const badgeY = chipY + chipH * 0.5;
    const dSz = 0.011 * minSide;
    const dCenters = [payCardX + payCardW - 0.062 * minSide, payCardX + payCardW - 0.034 * minSide];
    for (let d = 0; d < 2; d++) {
      const dx = dCenters[d];
      ctx.beginPath();
      ctx.moveTo(dx, badgeY - dSz);
      ctx.lineTo(dx + dSz, badgeY);
      ctx.lineTo(dx, badgeY + dSz);
      ctx.lineTo(dx - dSz, badgeY);
      ctx.closePath();
      ctx.fillStyle = d === 0 ? COL_LAVENDER : "rgba(237, 233, 254, 0.55)";
      ctx.fill();
    }
    ctx.restore();
  }

  // 4 Masked Card Number Segments (bottom at payCardTopY + 0.104*m)
  if (numReveal > 0.01) {
    ctx.save();
    ctx.globalAlpha = numReveal;
    const segW = 0.056 * minSide;
    const segH = 0.012 * minSide;
    const segGap = 0.018 * minSide;
    const totalW = segW * 4 + segGap * 3;
    const segStartX = cx - totalW * 0.5;
    const segY = payCardTopY + 0.092 * minSide;

    for (let s = 0; s < 4; s++) {
      roundRectPath(segStartX + s * (segW + segGap), segY, segW, segH, segH * 0.5);
      ctx.fillStyle = s === 3 ? COL_LAVENDER : "rgba(237, 233, 254, 0.72)";
      ctx.fill();
    }
    ctx.restore();
  }

  // Cardholder & Validity Footer Bars (bottom at payCardTopY + 0.138*m)
  if (footerReveal > 0.01) {
    ctx.save();
    ctx.globalAlpha = footerReveal;
    const footY = payCardTopY + 0.128 * minSide;
    roundRectPath(payCardX + 0.030 * minSide, footY, 0.120 * minSide, 0.010 * minSide, 0.005 * minSide);
    ctx.fillStyle = "rgba(237, 233, 254, 0.55)";
    ctx.fill();

    roundRectPath(payCardX + payCardW - 0.088 * minSide, footY, 0.058 * minSide, 0.010 * minSide, 0.005 * minSide);
    ctx.fillStyle = "rgba(237, 233, 254, 0.75)";
    ctx.fill();
    ctx.restore();
  }
  ctx.restore(); // end card clip above walletTopY

  // 5. Wallet Main Front Body
  ctx.save();
  roundRectPath(walletX, walletTopY, walletW, walletH, walletRad);
  const wGrad = ctx.createLinearGradient(walletX, walletTopY, walletX + walletW, walletTopY + walletH);
  wGrad.addColorStop(0, COL_WALLET_TOP);
  wGrad.addColorStop(1, COL_WALLET_BOT);
  ctx.fillStyle = wGrad;
  ctx.fill();
  ctx.lineWidth = 0.003 * minSide;
  ctx.strokeStyle = COL_BORDER;
  ctx.stroke();

  // Clean inset architectural border line inside wallet front face
  const insetPad = 0.016 * minSide;
  roundRectPath(walletX + insetPad, walletTopY + insetPad, walletW - insetPad * 2, walletH - insetPad * 2, walletRad - 0.010 * minSide);
  ctx.setLineDash([0.008 * minSide, 0.007 * minSide]);
  ctx.lineWidth = 0.002 * minSide;
  ctx.strokeStyle = "rgba(139, 92, 246, 0.28)";
  ctx.stroke();
  ctx.setLineDash([]);

  // Left-side Wallet Identity & Balance Progress Strip (strictly clear of right clasp flap)
  const wBarX = walletX + 0.036 * minSide;
  roundRectPath(wBarX, walletTopY + 0.054 * minSide, 0.110 * minSide, 0.012 * minSide, 0.006 * minSide);
  ctx.fillStyle = "#342269";
  ctx.fill();

  roundRectPath(wBarX, walletTopY + 0.086 * minSide, 0.178 * minSide, 0.012 * minSide, 0.006 * minSide);
  ctx.fillStyle = "#2A1B57";
  ctx.fill();

  // Live synced balance meter inside wallet lower-left
  const wTrackY = walletTopY + 0.180 * minSide;
  const wTrackW = 0.186 * minSide;
  const wTrackH = 0.016 * minSide;
  roundRectPath(wBarX, wTrackY, wTrackW, wTrackH, wTrackH * 0.5);
  ctx.fillStyle = COL_INDIGO_DEEP;
  ctx.fill();

  roundRectPath(wBarX, wTrackY, Math.max(wTrackH, wTrackW * walletFill), wTrackH, wTrackH * 0.5);
  const wfGrad = ctx.createLinearGradient(wBarX, 0, wBarX + wTrackW, 0);
  wfGrad.addColorStop(0, COL_VIOLET);
  wfGrad.addColorStop(1, COL_MAGENTA);
  ctx.fillStyle = wfGrad;
  ctx.fill();

  // Right-side Wallet Clasp Strap (flush on right side, strictly separated from left bars)
  const claspW = 0.114 * minSide;
  const claspH = 0.074 * minSide;
  const claspX = walletX + walletW - claspW + 0.002 * minSide;
  const claspY = walletTopY + (walletH - claspH) * 0.5;
  const claspRad = claspH * 0.5;

  ctx.beginPath();
  ctx.moveTo(claspX + claspRad, claspY);
  ctx.lineTo(walletX + walletW, claspY);
  ctx.lineTo(walletX + walletW, claspY + claspH);
  ctx.lineTo(claspX + claspRad, claspY + claspH);
  ctx.arc(claspX + claspRad, claspY + claspRad, claspRad, Math.PI * 0.5, Math.PI * 1.5);
  ctx.closePath();
  const clGrad = ctx.createLinearGradient(claspX, claspY, claspX + claspW, claspY + claspH);
  clGrad.addColorStop(0, "#33216B");
  clGrad.addColorStop(1, "#22154A");
  ctx.fillStyle = clGrad;
  ctx.fill();
  ctx.lineWidth = 0.0026 * minSide;
  ctx.strokeStyle = claspUnlock > 0.5 ? COL_ORCHID : "#523A9E";
  ctx.stroke();

  // Sliding Clasp Snap Track & Button strictly inside clasp strap
  const slotX = claspX + 0.022 * minSide;
  const slotY = claspY + claspH * 0.5 - 0.011 * minSide;
  const slotW = 0.056 * minSide;
  const slotH = 0.022 * minSide;
  roundRectPath(slotX, slotY, slotW, slotH, slotH * 0.5);
  ctx.fillStyle = COL_INDIGO_DEEP;
  ctx.fill();

  const btnX = lerp(slotX + 0.014 * minSide, slotX + slotW - 0.014 * minSide, claspUnlock);
  const btnY = claspY + claspH * 0.5;
  ctx.beginPath();
  ctx.arc(btnX, btnY, 0.012 * minSide, 0, TAU);
  ctx.fillStyle = claspUnlock > 0.5 ? COL_MAGENTA : COL_VIOLET;
  ctx.fill();
  ctx.lineWidth = 0.0022 * minSide;
  ctx.strokeStyle = COL_LAVENDER;
  ctx.stroke();
  ctx.restore();

  // 6. Contactless NFC Waves & Spaced Transaction Coin Lane (y = cy - 0.095*m, strictly clear of wallet, card, and side cards)
  const laneY = cy - 0.095 * minSide;
  const nfcOriginX = cx + 0.194 * minSide; // 0.024*m right of payment card edge (cx + 0.170*m)
  const arcRadii = [0.015 * minSide, 0.028 * minSide, 0.041 * minSide]; // max reach = cx + 0.235*m
  const arcSpan = (38 * Math.PI) / 180;

  ctx.save();
  ctx.lineCap = "round";
  for (let a = 0; a < 3; a++) {
    // Base faint resting arc indicator
    ctx.beginPath();
    ctx.arc(nfcOriginX, laneY, arcRadii[a], -arcSpan, arcSpan);
    ctx.lineWidth = 0.0038 * minSide;
    ctx.strokeStyle = "rgba(139, 92, 246, 0.22)";
    ctx.stroke();

    // Sequential active wave pulse during Scene 1
    if (nfcActive > 0.01) {
      const localPhase = (nfcPulsePhase - a * 0.22) % 1;
      const waveVal = localPhase >= 0 ? Math.sin(clamp01(localPhase) * Math.PI) : 0;
      const alpha = nfcActive * (0.35 + 0.65 * waveVal);
      ctx.beginPath();
      ctx.arc(nfcOriginX, laneY, arcRadii[a], -arcSpan, arcSpan);
      ctx.lineWidth = 0.0044 * minSide;
      ctx.strokeStyle = a === 2 ? `rgba(236, 72, 153, ${alpha})` : `rgba(192, 132, 252, ${alpha})`;
      ctx.stroke();
    }
  }
  ctx.restore();

  // Spaced Transaction Coin Lane (x in [cx + 0.262*m, cx + 0.394*m] -> >= 0.026*m clearance on both sides)
  const laneStartX = cx + 0.262 * minSide;
  const laneEndX = cx + 0.394 * minSide;

  // Clean subtle horizontal lane guide
  ctx.save();
  ctx.setLineDash([0.006 * minSide, 0.008 * minSide]);
  ctx.beginPath();
  ctx.moveTo(laneStartX, laneY);
  ctx.lineTo(laneEndX, laneY);
  ctx.lineWidth = 0.0022 * minSide;
  ctx.strokeStyle = "rgba(139, 92, 246, 0.32)";
  ctx.stroke();
  ctx.restore();

  // 2 Spaced Flat-Vector Transaction Coins traveling smoothly across lane during Scene 1
  if (coinLaneActive > 0.01) {
    const coinR = 0.0125 * minSide;
    const coinCount = 2;
    for (let c = 0; c < coinCount; c++) {
      // Exact 2-pass continuous travel spaced 0.5 apart so coins are always >= 0.036*m apart
      const pRaw = (coinStreamT * 2.0 + c * 0.5) % 1.0;
      const edgeFade = easeInOutSine(subRange(pRaw, 0.0, 0.22)) * (1 - easeInOutSine(subRange(pRaw, 0.78, 1.0)));
      const alpha = coinLaneActive * edgeFade;
      if (alpha > 0.01) {
        const coinX = lerp(laneStartX + coinR, laneEndX - coinR, pRaw);
        ctx.save();
        ctx.globalAlpha = alpha;
        ctx.beginPath();
        ctx.arc(coinX, laneY, coinR, 0, TAU);
        const cg = ctx.createLinearGradient(coinX - coinR, laneY - coinR, coinX + coinR, laneY + coinR);
        cg.addColorStop(0, COL_MAGENTA);
        cg.addColorStop(1, COL_VIOLET);
        ctx.fillStyle = cg;
        ctx.fill();

        ctx.beginPath();
        ctx.arc(coinX, laneY, coinR * 0.62, 0, TAU);
        ctx.fillStyle = COL_INDIGO_DEEP;
        ctx.fill();

        // Crisp center value diamond inside transaction coin
        const dr = coinR * 0.32;
        ctx.beginPath();
        ctx.moveTo(coinX, laneY - dr);
        ctx.lineTo(coinX + dr, laneY);
        ctx.lineTo(coinX, laneY + dr);
        ctx.lineTo(coinX - dr, laneY);
        ctx.closePath();
        ctx.fillStyle = COL_LAVENDER;
        ctx.fill();
        ctx.restore();
      }
    }
  }

  // 7. Symmetrical Flanking Fintech KPI Cards (Left Security Card & Right Balance Card)
  const sideCardW = 0.210 * minSide;
  const sideCardH = 0.250 * minSide;
  const leftCardX = cx - 0.630 * minSide;
  const rightCardX = cx + 0.420 * minSide;
  const sideCardY = cy - sideCardH * 0.5;

  // Left Card: Card Authentication & Verification Status
  if (leftCardX > 0.03 * width) {
    ctx.save();
    roundRectPath(leftCardX, sideCardY, sideCardW, sideCardH, 0.024 * minSide);
    ctx.fillStyle = COL_CARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const padX = 0.024 * minSide;
    roundRectPath(leftCardX + padX, sideCardY + 0.028 * minSide, 0.088 * minSide, 0.012 * minSide, 0.006 * minSide);
    ctx.fillStyle = "#342269";
    ctx.fill();

    const rowStartY = sideCardY + 0.072 * minSide;
    const rowGapY = 0.054 * minSide;
    const dotR = 0.008 * minSide;
    const barX = leftCardX + padX + dotR * 2 + 0.012 * minSide;
    const barW = sideCardW - padX * 2 - dotR * 2 - 0.012 * minSide;
    const barH = 0.014 * minSide;

    for (let s = 0; s < 3; s++) {
      const ry = rowStartY + s * rowGapY;
      const val = leftStatus[s];
      ctx.beginPath();
      ctx.arc(leftCardX + padX + dotR, ry + barH * 0.5, dotR, 0, TAU);
      ctx.fillStyle = val > 0.72 ? COL_MAGENTA : "#4C3494";
      ctx.fill();

      roundRectPath(barX, ry, barW, barH, barH * 0.5);
      ctx.fillStyle = COL_INDIGO_DEEP;
      ctx.fill();

      roundRectPath(barX, ry, Math.max(barH, barW * val), barH, barH * 0.5);
      const lGrad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
      lGrad.addColorStop(0, COL_VIOLET);
      lGrad.addColorStop(1, COL_MAGENTA);
      ctx.fillStyle = lGrad;
      ctx.fill();
    }
    ctx.restore();
  }

  // Right Card: Corporate Account Balance Ring & Transfer Summary Bars
  if (rightCardX + sideCardW < width - 0.03 * width) {
    ctx.save();
    roundRectPath(rightCardX, sideCardY, sideCardW, sideCardH, 0.024 * minSide);
    ctx.fillStyle = COL_CARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const gcx = rightCardX + sideCardW * 0.5;
    const gcy = sideCardY + 0.092 * minSide;
    const gr = 0.052 * minSide;
    const startA = Math.PI * 0.78;
    const spanA = Math.PI * 1.44;

    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA);
    ctx.lineWidth = 0.011 * minSide;
    ctx.strokeStyle = COL_INDIGO_DEEP;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA * rightBalanceRing);
    const rGrad = ctx.createLinearGradient(gcx - gr, gcy, gcx + gr, gcy);
    rGrad.addColorStop(0, COL_VIOLET);
    rGrad.addColorStop(1, COL_MAGENTA);
    ctx.strokeStyle = rGrad;
    ctx.stroke();

    // Clean Mini Card Emblem inside Balance Ring Center
    const mcW = 0.036 * minSide;
    const mcH = 0.024 * minSide;
    roundRectPath(gcx - mcW * 0.5, gcy - mcH * 0.5, mcW, mcH, 0.005 * minSide);
    ctx.fillStyle = rightBalanceRing > 0.72 ? COL_MAGENTA : COL_VIOLET;
    ctx.fill();
    ctx.fillStyle = COL_LAVENDER;
    ctx.fillRect(gcx - mcW * 0.5 + 0.005 * minSide, gcy - 0.003 * minSide, mcW - 0.010 * minSide, 0.004 * minSide);

    // 2 Horizontal Account Balance Bars beneath ring
    const rbPadX = 0.024 * minSide;
    const rbW = sideCardW - rbPadX * 2;
    const rbH = 0.013 * minSide;
    for (let i = 0; i < 2; i++) {
      const rby = sideCardY + 0.172 * minSide + i * 0.032 * minSide;
      roundRectPath(rightCardX + rbPadX, rby, rbW, rbH, rbH * 0.5);
      ctx.fillStyle = COL_INDIGO_DEEP;
      ctx.fill();

      roundRectPath(rightCardX + rbPadX, rby, Math.max(rbH, rbW * rightSubBars[i]), rbH, rbH * 0.5);
      ctx.fillStyle = i === 0 ? COL_MAGENTA : COL_ORCHID;
      ctx.fill();
    }
    ctx.restore();
  }

  void cycleWave;
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const rawLoopT = t % duration;
  const loopT = rawLoopT < 0 ? rawLoopT + duration : rawLoopT;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const u = loopT / duration;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, p) => a + (b - a) * p;
  const easeInOutCubic = (p) => {
    const x = clamp01(p);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  };
  const easeInOutSine = (p) => {
    const x = clamp01(p);
    return 0.5 * (1 - Math.cos(Math.PI * x));
  };
  const subRange = (p, a, b) => clamp01((p - a) / (b - a));

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  };

  // 1. Clean Deep Forest Slate Aesthetic Gradient Background (zero background glow)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#04120E");
  bgGrad.addColorStop(0.5, "#0A2920");
  bgGrad.addColorStop(1, "#051712");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Palette constants
  const COL_PINE_DEEP = "#061914";
  const COL_CARD_BG = "#0A221B";
  const COL_HEADER_BG = "#0E2E24";
  const COL_BORDER = "#1C5241";
  const COL_SLOT = "#0D2920";
  const COL_EMERALD = "#10B981";
  const COL_EMERALD_BRIGHT = "#34D399";
  const COL_LIME = "#84CC16";
  const COL_LIME_LIGHT = "#BEF264";
  const COL_MINT = "#D1FAE5";

  // 2. Scene Choreography (4 Scenes, 20s Seamless Loop)
  const restBars = [0.20, 0.25, 0.30, 0.35, 0.40];
  const peakBars = [0.40, 0.54, 0.68, 0.82, 0.96];

  let activeBars = restBars.slice();
  let arrowDraw = 0; // 0..1 along growth curve
  let coinReveals = [0, 0, 0]; // 3 milestone coins
  let leftMargins = [0.36, 0.30, 0.42];
  let roiGauge = 0.32;
  let rightSubBars = [0.34, 0.28];

  if (currentScene === 0) {
    // Scene 0 (0-5s): Staggered 5-pillar revenue growth
    for (let i = 0; i < 5; i++) {
      const bp = easeInOutCubic(subRange(sceneProgress, i * 0.10, i * 0.10 + 0.58));
      activeBars[i] = lerp(restBars[i], peakBars[i], bp);
    }
    const g0 = easeInOutCubic(sceneProgress);
    leftMargins = [
      lerp(0.36, 0.64, g0),
      lerp(0.30, 0.56, easeInOutCubic(subRange(sceneProgress, 0.10, 0.90))),
      lerp(0.42, 0.68, easeInOutCubic(subRange(sceneProgress, 0.16, 0.96))),
    ];
    roiGauge = lerp(0.32, 0.58, g0);
    rightSubBars = [lerp(0.34, 0.58, g0), lerp(0.28, 0.50, g0)];
  } else if (currentScene === 1) {
    // Scene 1 (5-10s): Exponential profit growth arrow projection in dedicated upper zone
    activeBars = peakBars.slice();
    arrowDraw = easeInOutCubic(subRange(sceneProgress, 0.05, 0.92));
    const g1 = easeInOutCubic(sceneProgress);
    leftMargins = [
      lerp(0.64, 0.82, g1),
      lerp(0.56, 0.74, g1),
      lerp(0.68, 0.86, g1),
    ];
    roiGauge = lerp(0.58, 0.82, g1);
    rightSubBars = [lerp(0.58, 0.80, g1), lerp(0.50, 0.72, g1)];
  } else if (currentScene === 2) {
    // Scene 2 (10-15s): Sequential 3 milestone profit coins reveal & full ROI lock-in
    activeBars = peakBars.slice();
    arrowDraw = 1;
    for (let c = 0; c < 3; c++) {
      coinReveals[c] = easeInOutCubic(subRange(sceneProgress, 0.06 + c * 0.22, 0.42 + c * 0.22));
    }
    const g2 = easeInOutCubic(subRange(sceneProgress, 0.10, 0.90));
    leftMargins = [
      lerp(0.82, 0.94, g2),
      lerp(0.74, 0.88, g2),
      lerp(0.86, 0.96, g2),
    ];
    roiGauge = lerp(0.82, 0.96, g2);
    rightSubBars = [lerp(0.80, 0.94, g2), lerp(0.72, 0.88, g2)];
  } else {
    // Scene 3 (15-20s): Controlled hold & smooth harmonic retraction back to exact t=0
    const coinRet = 1 - easeInOutCubic(subRange(sceneProgress, 0.12, 0.48));
    coinReveals = [
      1 - easeInOutCubic(subRange(sceneProgress, 0.18, 0.48)),
      1 - easeInOutCubic(subRange(sceneProgress, 0.14, 0.44)),
      1 - easeInOutCubic(subRange(sceneProgress, 0.10, 0.40)),
    ];
    arrowDraw = 1 - easeInOutCubic(subRange(sceneProgress, 0.22, 0.68));
    for (let i = 0; i < 5; i++) {
      const bRet = easeInOutCubic(subRange(sceneProgress, 0.34 + (4 - i) * 0.06, 0.74 + (4 - i) * 0.06));
      activeBars[i] = lerp(peakBars[i], restBars[i], bRet);
    }
    const g3 = easeInOutCubic(subRange(sceneProgress, 0.25, 0.96));
    leftMargins = [
      lerp(0.94, 0.36, g3),
      lerp(0.88, 0.30, g3),
      lerp(0.96, 0.42, g3),
    ];
    roiGauge = lerp(0.96, 0.32, g3);
    rightSubBars = [lerp(0.94, 0.34, g3), lerp(0.88, 0.28, g3)];
    void coinRet;
  }

  // Smooth periodic wave synchronized to 20s duration (exact match at u=0 and u=1)
  const cycleWave = 0.5 + 0.5 * Math.sin(TAU * u);

  // 3. Central Hero Icon: Corporate Revenue Report & Growth Board
  const bw = 0.620 * minSide;
  const bh = 0.460 * minSide;
  const bx = cx - bw * 0.5;
  const by = cy - bh * 0.5;
  const bRad = 0.028 * minSide;

  ctx.save();
  // Board Body
  roundRectPath(bx, by, bw, bh, bRad);
  ctx.fillStyle = COL_CARD_BG;
  ctx.fill();

  // Header band clipped strictly inside board top
  ctx.save();
  roundRectPath(bx, by, bw, bh, bRad);
  ctx.clip();
  ctx.fillStyle = COL_HEADER_BG;
  ctx.fillRect(bx, by, bw, 0.066 * minSide);
  ctx.restore();

  // Outer crisp border
  roundRectPath(bx, by, bw, bh, bRad);
  ctx.lineWidth = 0.003 * minSide;
  ctx.strokeStyle = COL_BORDER;
  ctx.stroke();

  // Header divider line
  const headerBotY = by + 0.066 * minSide;
  ctx.beginPath();
  ctx.moveTo(bx + 0.002 * minSide, headerBotY);
  ctx.lineTo(bx + bw - 0.002 * minSide, headerBotY);
  ctx.lineWidth = 0.0022 * minSide;
  ctx.strokeStyle = COL_BORDER;
  ctx.stroke();

  // Header Left: Corporate Report Indicators
  const hMidY = by + 0.033 * minSide;
  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(bx + 0.034 * minSide + d * 0.020 * minSide, hMidY, 0.005 * minSide, 0, TAU);
    ctx.fillStyle = d === 0 ? COL_LIME : d === 1 ? COL_EMERALD : "#266853";
    ctx.fill();
  }
  roundRectPath(bx + 0.104 * minSide, hMidY - 0.0065 * minSide, 0.110 * minSide, 0.013 * minSide, 0.0065 * minSide);
  ctx.fillStyle = "#143D30";
  ctx.fill();
  roundRectPath(
    bx + 0.104 * minSide,
    hMidY - 0.0065 * minSide,
    0.110 * minSide * lerp(0.52, 0.94, roiGauge * 0.78 + cycleWave * 0.22),
    0.013 * minSide,
    0.0065 * minSide
  );
  ctx.fillStyle = COL_EMERALD;
  ctx.fill();

  // Header Right: Clean Mini Revenue Growth Badge Pill
  const hBadgeW = 0.118 * minSide;
  const hBadgeH = 0.030 * minSide;
  const hBadgeX = bx + bw - 0.028 * minSide - hBadgeW;
  const hBadgeY = hMidY - hBadgeH * 0.5;
  roundRectPath(hBadgeX, hBadgeY, hBadgeW, hBadgeH, hBadgeH * 0.5);
  ctx.fillStyle = COL_PINE_DEEP;
  ctx.fill();
  ctx.lineWidth = 0.002 * minSide;
  ctx.strokeStyle = arrowDraw > 0.5 ? COL_LIME : COL_BORDER;
  ctx.stroke();

  // 3 mini rising step bars inside header badge
  for (let s = 0; s < 3; s++) {
    const sbH = (0.006 + s * 0.0038) * minSide;
    roundRectPath(
      hBadgeX + 0.018 * minSide + s * 0.009 * minSide,
      hMidY + 0.007 * minSide - sbH,
      0.0055 * minSide,
      sbH,
      0.002 * minSide
    );
    ctx.fillStyle = s === 2 ? COL_LIME : COL_EMERALD;
    ctx.fill();
  }
  // Status fill pill inside header badge
  roundRectPath(hBadgeX + 0.056 * minSide, hMidY - 0.004 * minSide, 0.046 * minSide, 0.008 * minSide, 0.004 * minSide);
  ctx.fillStyle = "#143D30";
  ctx.fill();
  roundRectPath(
    hBadgeX + 0.056 * minSide,
    hMidY - 0.004 * minSide,
    0.046 * minSide * lerp(0.40, 1.0, roiGauge),
    0.008 * minSide,
    0.004 * minSide
  );
  ctx.fillStyle = COL_LIME;
  ctx.fill();

  // 4. Strictly Partitioned Interior Zones (Zero Overlap Guaranteed)
  const colPitch = 0.098 * minSide;
  const colStartX = cx - 2 * colPitch; // 5 columns: cx - 0.196*m .. cx + 0.196*m
  const colXs = [];
  for (let i = 0; i < 5; i++) {
    colXs.push(colStartX + i * colPitch);
  }
  const innerLeft = bx + 0.044 * minSide;
  const innerRight = bx + bw - 0.044 * minSide;

  // --- ZONE A: Dedicated Milestone Coin Rail (y in [by + 0.084*m, by + 0.132*m]) ---
  const railY = by + 0.108 * minSide;
  const coinXs = [colXs[0], colXs[2], colXs[4]];
  const coinR = 0.018 * minSide;

  // Subtle horizontal rail guide dashes strictly between coins (clear gap >= 0.014*m from each coin)
  ctx.save();
  ctx.strokeStyle = "#1B4C3D";
  ctx.lineWidth = 0.0022 * minSide;
  ctx.setLineDash([0.007 * minSide, 0.007 * minSide]);
  for (let s = 0; s < 2; s++) {
    const xA = coinXs[s] + coinR + 0.014 * minSide;
    const xB = coinXs[s + 1] - coinR - 0.014 * minSide;
    ctx.beginPath();
    ctx.moveTo(xA, railY);
    ctx.lineTo(xB, railY);
    ctx.stroke();
  }
  ctx.restore();

  // 3 Milestone Profit Coin Badges
  for (let c = 0; c < 3; c++) {
    const rev = coinReveals[c];
    const mcx = coinXs[c];

    // Subtle resting placeholder ring so layout rhythm is always clean
    ctx.beginPath();
    ctx.arc(mcx, railY, coinR, 0, TAU);
    ctx.fillStyle = COL_PINE_DEEP;
    ctx.fill();
    ctx.lineWidth = 0.0022 * minSide;
    ctx.strokeStyle = "#1C4F3E";
    ctx.stroke();

    if (rev > 0.01) {
      ctx.save();
      ctx.translate(mcx, railY);
      const sc = lerp(0.82, 1.0, rev);
      ctx.scale(sc, sc);
      ctx.globalAlpha = rev;

      // Coin outer gold-lime gradient disc
      const cGrad = ctx.createLinearGradient(-coinR, -coinR, coinR, coinR);
      cGrad.addColorStop(0, COL_LIME_LIGHT);
      cGrad.addColorStop(0.5, COL_LIME);
      cGrad.addColorStop(1, COL_EMERALD);
      ctx.beginPath();
      ctx.arc(0, 0, coinR, 0, TAU);
      ctx.fillStyle = cGrad;
      ctx.fill();

      // Inner dark emerald inset circle
      ctx.beginPath();
      ctx.arc(0, 0, coinR * 0.74, 0, TAU);
      ctx.fillStyle = COL_PINE_DEEP;
      ctx.fill();

      // Clean upward profit chevron inside coin
      const ch = coinR * 0.34;
      ctx.beginPath();
      ctx.moveTo(-ch, ch * 0.45);
      ctx.lineTo(0, -ch * 0.55);
      ctx.lineTo(ch, ch * 0.45);
      ctx.lineWidth = 0.003 * minSide;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.strokeStyle = COL_MINT;
      ctx.stroke();

      ctx.restore();
    }
  }

  // --- ZONE B: Dedicated Exponential Profit Growth Arrow Band (y in [by + 0.148*m, by + 0.214*m]) ---
  // Quadratic Bezier curve strictly bounded above bar ceiling (by + 0.236*m) & below coin rail (by + 0.132*m)
  const p0x = colXs[0] - 0.018 * minSide;
  const p0y = by + 0.206 * minSide;
  const p1x = cx + 0.025 * minSide;
  const p1y = by + 0.200 * minSide;
  const p2x = colXs[4] + 0.022 * minSide;
  const p2y = by + 0.156 * minSide;

  // Faint dashed trajectory guide along entire curve
  ctx.save();
  ctx.setLineDash([0.008 * minSide, 0.008 * minSide]);
  ctx.beginPath();
  ctx.moveTo(p0x, p0y);
  ctx.quadraticCurveTo(p1x, p1y, p2x, p2y);
  ctx.lineWidth = 0.0022 * minSide;
  ctx.strokeStyle = "rgba(52, 211, 153, 0.22)";
  ctx.stroke();
  ctx.restore();

  // Animated exponential profit growth arrow (exact analytical sub-curve sampling)
  if (arrowDraw > 0.01) {
    const steps = 40;
    const maxStep = Math.max(1, Math.floor(steps * arrowDraw));
    const evalQ = (s) => {
      const inv = 1 - s;
      return {
        x: inv * inv * p0x + 2 * inv * s * p1x + s * s * p2x,
        y: inv * inv * p0y + 2 * inv * s * p1y + s * s * p2y,
        dx: 2 * inv * (p1x - p0x) + 2 * s * (p2x - p1x),
        dy: 2 * inv * (p1y - p0y) + 2 * s * (p2y - p1y),
      };
    };

    ctx.save();
    ctx.beginPath();
    ctx.moveTo(p0x, p0y);
    for (let i = 1; i <= maxStep; i++) {
      const pt = evalQ((i / steps) * (arrowDraw / (maxStep / steps)));
      ctx.lineTo(pt.x, pt.y);
    }
    const tip = evalQ(arrowDraw);
    ctx.lineTo(tip.x, tip.y);

    const arrGrad = ctx.createLinearGradient(p0x, p0y, p2x, p2y);
    arrGrad.addColorStop(0, COL_EMERALD);
    arrGrad.addColorStop(0.6, COL_EMERALD_BRIGHT);
    arrGrad.addColorStop(1, COL_LIME);
    ctx.strokeStyle = arrGrad;
    ctx.lineWidth = 0.0052 * minSide;
    ctx.lineCap = "round";
    ctx.stroke();

    // Crisp tangent-aligned arrowhead at exact curve tip
    const ang = Math.atan2(tip.dy, tip.dx);
    const headLen = 0.014 * minSide * Math.min(1, arrowDraw * 3);
    ctx.save();
    ctx.translate(tip.x, tip.y);
    ctx.rotate(ang);
    ctx.beginPath();
    ctx.moveTo(-headLen, -headLen * 0.68);
    ctx.lineTo(0, 0);
    ctx.lineTo(-headLen, headLen * 0.68);
    ctx.lineWidth = 0.0052 * minSide;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.strokeStyle = COL_LIME;
    ctx.stroke();
    ctx.restore();
    ctx.restore();
  }

  // Clean subtle horizontal band divider between growth arrow & revenue bar chart
  const divY = by + 0.224 * minSide;
  ctx.beginPath();
  ctx.moveTo(innerLeft, divY);
  ctx.lineTo(innerRight, divY);
  ctx.lineWidth = 0.002 * minSide;
  ctx.strokeStyle = "#164033";
  ctx.stroke();

  // --- ZONE C: 5 Corporate Revenue Pillars & Accounting Baseline (y in [by + 0.238*m, by + 0.404*m]) ---
  const baseY = by + 0.404 * minSide;
  const barCeilY = by + 0.238 * minSide;
  const maxBarH = baseY - barCeilY; // 0.166*m
  const barW = 0.052 * minSide;

  for (let i = 0; i < 5; i++) {
    const bxCol = colXs[i] - barW * 0.5;

    // Clean recessed capacity track behind bar
    roundRectPath(bxCol, barCeilY, barW, maxBarH, 0.008 * minSide);
    ctx.fillStyle = COL_SLOT;
    ctx.fill();

    // Active revenue pillar bar
    const bhVal = Math.max(0.018 * minSide, maxBarH * activeBars[i]);
    const barTop = baseY - bhVal;
    roundRectPath(bxCol, barTop, barW, bhVal, 0.008 * minSide);
    const barGrad = ctx.createLinearGradient(bxCol, barTop, bxCol, baseY);
    if (i === 4) {
      barGrad.addColorStop(0, COL_LIME);
      barGrad.addColorStop(0.55, COL_EMERALD_BRIGHT);
      barGrad.addColorStop(1, COL_EMERALD);
    } else {
      barGrad.addColorStop(0, COL_EMERALD_BRIGHT);
      barGrad.addColorStop(1, "#0B7D5A");
    }
    ctx.fillStyle = barGrad;
    ctx.fill();

    // Crisp inner top highlight bar inside top of pillar (strictly inset by 0.007*m)
    const capPad = 0.007 * minSide;
    roundRectPath(bxCol + capPad, barTop + 0.006 * minSide, barW - capPad * 2, 0.005 * minSide, 0.0025 * minSide);
    ctx.fillStyle = i === 4 ? COL_MINT : "rgba(209, 250, 229, 0.55)";
    ctx.fill();

    // Aligned column indicator dot beneath accounting baseline
    ctx.beginPath();
    ctx.arc(colXs[i], by + 0.426 * minSide, 0.0042 * minSide, 0, TAU);
    ctx.fillStyle = activeBars[i] > 0.72 ? COL_LIME : activeBars[i] > 0.45 ? COL_EMERALD : "#1D5241";
    ctx.fill();
  }

  // Crisp Accounting Baseline strictly underneath bars
  ctx.beginPath();
  ctx.moveTo(innerLeft, baseY + 0.003 * minSide);
  ctx.lineTo(innerRight, baseY + 0.003 * minSide);
  ctx.lineWidth = 0.0028 * minSide;
  ctx.strokeStyle = "#266D57";
  ctx.stroke();

  ctx.restore();

  // 5. Symmetrical Flanking Business KPI Cards (Strictly separated from central board)
  const cardW = 0.210 * minSide;
  const cardH = 0.250 * minSide;
  const leftCardX = cx - 0.630 * minSide;
  const rightCardX = cx + 0.420 * minSide;
  const cardY = cy - cardH * 0.5;

  // Left KPI Card: 3 Corporate Margin & Profit Share Rows
  if (leftCardX > 0.03 * width) {
    ctx.save();
    roundRectPath(leftCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_CARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const padX = 0.024 * minSide;
    roundRectPath(leftCardX + padX, cardY + 0.028 * minSide, 0.088 * minSide, 0.012 * minSide, 0.006 * minSide);
    ctx.fillStyle = "#194C3C";
    ctx.fill();

    const rowStartY = cardY + 0.072 * minSide;
    const rowGapY = 0.054 * minSide;
    const sqSize = 0.018 * minSide;
    const barX = leftCardX + padX + sqSize + 0.014 * minSide;
    const barW = cardW - padX * 2 - sqSize - 0.014 * minSide;
    const barH = 0.014 * minSide;

    for (let r = 0; r < 3; r++) {
      const ry = rowStartY + r * rowGapY;
      roundRectPath(leftCardX + padX, ry, sqSize, sqSize, 0.004 * minSide);
      ctx.fillStyle = r === 2 ? COL_LIME : COL_EMERALD;
      ctx.fill();

      const byTrack = ry + (sqSize - barH) * 0.5;
      roundRectPath(barX, byTrack, barW, barH, barH * 0.5);
      ctx.fillStyle = COL_PINE_DEEP;
      ctx.fill();

      roundRectPath(barX, byTrack, Math.max(barH, barW * leftMargins[r]), barH, barH * 0.5);
      const mGrad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
      mGrad.addColorStop(0, COL_EMERALD);
      mGrad.addColorStop(1, r >= 1 ? COL_LIME : COL_EMERALD_BRIGHT);
      ctx.fillStyle = mGrad;
      ctx.fill();
    }
    ctx.restore();
  }

  // Right KPI Card: ROI Target Ring & 2 Efficiency Bars
  if (rightCardX + cardW < width - 0.03 * width) {
    ctx.save();
    roundRectPath(rightCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_CARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    const gcx = rightCardX + cardW * 0.5;
    const gcy = cardY + 0.092 * minSide;
    const gr = 0.052 * minSide;
    const startA = Math.PI * 0.78;
    const spanA = Math.PI * 1.44;

    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA);
    ctx.lineWidth = 0.011 * minSide;
    ctx.strokeStyle = COL_PINE_DEEP;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA * roiGauge);
    const rGrad = ctx.createLinearGradient(gcx - gr, gcy, gcx + gr, gcy);
    rGrad.addColorStop(0, COL_EMERALD);
    rGrad.addColorStop(1, COL_LIME);
    ctx.strokeStyle = rGrad;
    ctx.stroke();

    // Clean Double-Chevron Growth Emblem inside ring center
    const chW = 0.014 * minSide;
    const chH = 0.009 * minSide;
    ctx.lineWidth = 0.0038 * minSide;
    ctx.lineJoin = "round";
    ctx.strokeStyle = roiGauge > 0.7 ? COL_LIME : COL_EMERALD_BRIGHT;
    for (let k = 0; k < 2; k++) {
      const yOff = (k === 0 ? -0.007 : 0.007) * minSide;
      ctx.beginPath();
      ctx.moveTo(gcx - chW, gcy + yOff + chH * 0.5);
      ctx.lineTo(gcx, gcy + yOff - chH * 0.5);
      ctx.lineTo(gcx + chW, gcy + yOff + chH * 0.5);
      ctx.stroke();
    }

    // 2 Horizontal Efficiency Bars beneath ring
    const rbPadX = 0.024 * minSide;
    const rbW = cardW - rbPadX * 2;
    const rbH = 0.013 * minSide;
    for (let i = 0; i < 2; i++) {
      const rby = cardY + 0.172 * minSide + i * 0.032 * minSide;
      roundRectPath(rightCardX + rbPadX, rby, rbW, rbH, rbH * 0.5);
      ctx.fillStyle = COL_PINE_DEEP;
      ctx.fill();

      roundRectPath(rightCardX + rbPadX, rby, Math.max(rbH, rbW * rightSubBars[i]), rbH, rbH * 0.5);
      ctx.fillStyle = i === 0 ? COL_LIME : COL_EMERALD;
      ctx.fill();
    }
    ctx.restore();
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const rawLoopT = t % duration;
  const loopT = rawLoopT < 0 ? rawLoopT + duration : rawLoopT;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const u = loopT / duration;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, p) => a + (b - a) * p;
  const easeInOutCubic = (p) => {
    const x = clamp01(p);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  };
  const easeInOutSine = (p) => {
    const x = clamp01(p);
    return 0.5 * (1 - Math.cos(Math.PI * x));
  };
  const subRange = (p, a, b) => clamp01((p - a) / (b - a));

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  };

  // 1. Clean Dark Obsidian-Charcoal Aesthetic Gradient (zero background glow)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#090806");
  bgGrad.addColorStop(0.5, "#1A140B");
  bgGrad.addColorStop(1, "#0C0A06");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Palette constants
  const COL_OBSIDIAN = "#0E0B07";
  const COL_CARD_BG = "#16110A";
  const COL_SAFE_BODY = "#1C150D";
  const COL_SAFE_MID = "#281F13";
  const COL_BRONZE_EDGE = "#524027";
  const COL_GOLD = "#F5C451";
  const COL_GOLD_LIGHT = "#FCE39D";
  const COL_AMBER = "#FF8A00";
  const COL_AMBER_DARK = "#C96A04";
  const COL_IVORY = "#FFF6E0";

  // 2. Scene Choreography (Seamless 20s Loop)
  let wheelAngle = 0;
  let boltLockAmt = 1; // 1 = extended locked, 0 = retracted unlocked
  let doorOpenAmt = 0; // 0 = closed, 1 = fully open
  let bullionSheen = 0;
  let securitySteps = [0.38, 0.28, 0.22];
  let reserveBars = [0.32, 0.44, 0.36, 0.48, 0.34];
  let reserveSummary = 0.30;

  if (currentScene === 0) {
    // Scene 0: Twin vault wheels unlock & side locking bolts retract
    const wheelP = easeInOutCubic(subRange(sceneProgress, 0.0, 0.65));
    const boltP = easeInOutCubic(subRange(sceneProgress, 0.48, 0.96));
    const barP = easeInOutCubic(subRange(sceneProgress, 0.15, 0.96));

    wheelAngle = lerp(0, Math.PI, wheelP);
    boltLockAmt = 1 - boltP;
    doorOpenAmt = 0;
    reserveSummary = lerp(0.30, 0.62, barP);

    securitySteps = [
      lerp(0.38, 0.95, easeInOutCubic(subRange(sceneProgress, 0.05, 0.55))),
      lerp(0.28, 0.90, easeInOutCubic(subRange(sceneProgress, 0.25, 0.75))),
      lerp(0.22, 0.88, easeInOutCubic(subRange(sceneProgress, 0.45, 0.95))),
    ];
    const barBase = [0.32, 0.44, 0.36, 0.48, 0.34];
    const barMid = [0.48, 0.60, 0.52, 0.65, 0.50];
    reserveBars = barBase.map((v, idx) => lerp(v, barMid[idx], barP));
  } else if (currentScene === 1) {
    // Scene 1: Symmetric double doors open -> gold bullion pyramid & coin stack reveal
    doorOpenAmt = easeInOutCubic(subRange(sceneProgress, 0.0, 0.52));
    wheelAngle = lerp(Math.PI, Math.PI * 1.15, easeInOutSine(sceneProgress));
    boltLockAmt = 0;
    bullionSheen = easeInOutCubic(subRange(sceneProgress, 0.55, 0.95));
    reserveSummary = lerp(0.62, 0.98, easeInOutCubic(subRange(sceneProgress, 0.10, 0.90)));
    securitySteps = [0.95, 0.90, 0.88];

    const barMid = [0.48, 0.60, 0.52, 0.65, 0.50];
    const barPeak = [0.76, 0.92, 0.84, 0.96, 0.80];
    reserveBars = barMid.map((v, idx) => {
      const bp = easeInOutCubic(subRange(sceneProgress, 0.12 + idx * 0.06, 0.78 + idx * 0.04));
      return lerp(v, barPeak[idx], bp);
    });
  } else {
    // Scene 2: Clean reveal fade-out -> doors close -> bolts relock -> wheel returns 360
    const closeP = easeInOutCubic(subRange(sceneProgress, 0.14, 0.62));
    const relockP = easeInOutCubic(subRange(sceneProgress, 0.56, 0.96));
    const wheelRetP = easeInOutCubic(subRange(sceneProgress, 0.24, 0.98));
    const barRetP = easeInOutCubic(subRange(sceneProgress, 0.18, 0.94));

    wheelAngle = lerp(Math.PI * 1.15, TAU, wheelRetP);
    boltLockAmt = relockP;
    doorOpenAmt = 1 - closeP;
    bullionSheen = 1 - easeInOutCubic(subRange(sceneProgress, 0.05, 0.28));
    reserveSummary = lerp(0.98, 0.30, barRetP);

    securitySteps = [
      lerp(0.95, 0.38, easeInOutCubic(subRange(sceneProgress, 0.34, 0.92))),
      lerp(0.90, 0.28, easeInOutCubic(subRange(sceneProgress, 0.40, 0.94))),
      lerp(0.88, 0.22, easeInOutCubic(subRange(sceneProgress, 0.45, 0.96))),
    ];
    const barPeak = [0.76, 0.92, 0.84, 0.96, 0.80];
    const barBase = [0.32, 0.44, 0.36, 0.48, 0.34];
    reserveBars = barPeak.map((v, idx) => lerp(v, barBase[idx], barRetP));
  }

  const cycleWave = 0.5 + 0.5 * Math.sin(TAU * u);

  // Dimensions of Central Treasury Safe
  const safeSide = 0.500 * minSide;
  const safeHalf = safeSide * 0.5; // 0.250*m
  const frameSide = 0.410 * minSide;
  const frameHalf = frameSide * 0.5; // 0.205*m
  const chamberSide = 0.370 * minSide;
  const chamberHalf = chamberSide * 0.5; // 0.185*m

  // 3. Side Hydraulic Locking Bolts (2 Left, 2 Right — strictly clear of chamber & side cards)
  const boltH = 0.036 * minSide;
  const boltLen = 0.048 * minSide;
  const boltOffsetOut = lerp(0.256 * minSide, 0.284 * minSide, boltLockAmt); // retracted=0.256, locked=0.284
  const boltYs = [cy - 0.112 * minSide, cy + 0.112 * minSide];

  for (let side = -1; side <= 1; side += 2) {
    for (let row = 0; row < 2; row++) {
      const by = boltYs[row] - boltH * 0.5;
      const bx = side < 0 ? cx - boltOffsetOut : cx + boltOffsetOut - boltLen;

      roundRectPath(bx, by, boltLen, boltH, 0.007 * minSide);
      const bGrad = ctx.createLinearGradient(bx, by, bx, by + boltH);
      bGrad.addColorStop(0, "#755B34");
      bGrad.addColorStop(0.5, COL_GOLD);
      bGrad.addColorStop(1, "#9B7538");
      ctx.fillStyle = bGrad;
      ctx.fill();
      ctx.lineWidth = 0.0022 * minSide;
      ctx.strokeStyle = COL_GOLD_LIGHT;
      ctx.stroke();

      // Recessed groove inside bolt
      const grooveW = 0.016 * minSide;
      const grooveH = 0.008 * minSide;
      const gx = side < 0 ? bx + 0.009 * minSide : bx + boltLen - grooveW - 0.009 * minSide;
      roundRectPath(gx, by + (boltH - grooveH) * 0.5, grooveW, grooveH, grooveH * 0.5);
      ctx.fillStyle = COL_OBSIDIAN;
      ctx.fill();
    }
  }

  // 4. Outer Safe Chassis Body
  roundRectPath(cx - safeHalf, cy - safeHalf, safeSide, safeSide, 0.044 * minSide);
  const safeGrad = ctx.createLinearGradient(cx - safeHalf, cy - safeHalf, cx + safeHalf, cy + safeHalf);
  safeGrad.addColorStop(0, "#231B11");
  safeGrad.addColorStop(1, "#140F09");
  ctx.fillStyle = safeGrad;
  ctx.fill();
  ctx.lineWidth = 0.003 * minSide;
  ctx.strokeStyle = COL_BRONZE_EDGE;
  ctx.stroke();

  // Four clean corner structural rivets on safe body (inset neatly inside safe chassis margin)
  const rivetOff = 0.214 * minSide;
  const rivets = [
    [-rivetOff, -rivetOff],
    [rivetOff, -rivetOff],
    [-rivetOff, rivetOff],
    [rivetOff, rivetOff],
  ];
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.arc(cx + rivets[i][0], cy + rivets[i][1], 0.006 * minSide, 0, TAU);
    ctx.fillStyle = "#5C472A";
    ctx.fill();
  }

  // Stepped Inner Frame Collar
  roundRectPath(cx - frameHalf, cy - frameHalf, frameSide, frameSide, 0.030 * minSide);
  ctx.fillStyle = COL_SAFE_MID;
  ctx.fill();
  ctx.lineWidth = 0.0024 * minSide;
  ctx.strokeStyle = "#695130";
  ctx.stroke();

  // 5. Inner Recessed Treasury Chamber (Clipped strictly inside chamberSide = 0.370 * minSide)
  ctx.save();
  roundRectPath(cx - chamberHalf, cy - chamberHalf, chamberSide, chamberSide, 0.024 * minSide);
  ctx.fillStyle = COL_OBSIDIAN;
  ctx.fill();
  ctx.clip();

  // Compute safe post-clearance reveal: doors clear x = +-0.130*m once doorOpenAmt >= 0.72
  const interiorReveal = easeInOutCubic(subRange(doorOpenAmt, 0.70, 0.96));

  if (interiorReveal > 0.01) {
    ctx.save();
    ctx.globalAlpha = interiorReveal;

    // Treasury Shelf Line
    const shelfY = cy + 0.098 * minSide;
    roundRectPath(cx - 0.136 * minSide, shelfY, 0.272 * minSide, 0.007 * minSide, 0.0035 * minSide);
    ctx.fillStyle = "#5D4728";
    ctx.fill();

    // Helper: Draw a crisp flat-vector Gold Bullion Bar
    const drawBullionBar = (barCx, barBotY, sheenPhase) => {
      const botW = 0.068 * minSide;
      const topW = 0.050 * minSide;
      const barH = 0.030 * minSide;
      const topY = barBotY - barH;

      // Main trapezoid face
      ctx.beginPath();
      ctx.moveTo(barCx - topW * 0.5, topY);
      ctx.lineTo(barCx + topW * 0.5, topY);
      ctx.lineTo(barCx + botW * 0.5, barBotY);
      ctx.lineTo(barCx - botW * 0.5, barBotY);
      ctx.closePath();
      const bGrad = ctx.createLinearGradient(barCx - botW * 0.5, topY, barCx + botW * 0.5, barBotY);
      bGrad.addColorStop(0, COL_GOLD_LIGHT);
      bGrad.addColorStop(0.55, COL_GOLD);
      bGrad.addColorStop(1, COL_AMBER);
      ctx.fillStyle = bGrad;
      ctx.fill();

      // Lower chamfer bevel strip
      ctx.beginPath();
      ctx.moveTo(barCx - botW * 0.46, barBotY - 0.007 * minSide);
      ctx.lineTo(barCx + botW * 0.46, barBotY - 0.007 * minSide);
      ctx.lineTo(barCx + botW * 0.5, barBotY);
      ctx.lineTo(barCx - botW * 0.5, barBotY);
      ctx.closePath();
      ctx.fillStyle = COL_AMBER_DARK;
      ctx.fill();

      // Top inset ingot recess rectangle
      const inW = 0.030 * minSide;
      const inH = 0.008 * minSide;
      roundRectPath(barCx - inW * 0.5, topY + 0.007 * minSide, inW, inH, 0.003 * minSide);
      ctx.fillStyle = sheenPhase > 0.45 ? COL_IVORY : "#D9820B";
      ctx.fill();
    };

    // 3-Bar Gold Bullion Pyramid on left-center of shelf (strict spacing: 0.010*m gap)
    const riseOffset = lerp(0.014 * minSide, 0, interiorReveal);
    drawBullionBar(cx - 0.092 * minSide, shelfY - 0.006 * minSide + riseOffset, bullionSheen);
    drawBullionBar(cx - 0.014 * minSide, shelfY - 0.006 * minSide + riseOffset, bullionSheen * 0.8);
    drawBullionBar(cx - 0.053 * minSide, shelfY - 0.044 * minSide + riseOffset, bullionSheen);

    // 4-Coin Reserve Stack on right-center of shelf (x = cx + 0.088*m, 0.034*m clear gap from bullion)
    const coinStackX = cx + 0.086 * minSide;
    const coinW = 0.066 * minSide;
    const coinH = 0.014 * minSide;
    const coinPitchY = 0.020 * minSide; // leaves 0.006*m crisp gap between coins

    for (let c = 0; c < 4; c++) {
      const localC = easeInOutCubic(subRange(interiorReveal, c * 0.12, 0.55 + c * 0.11));
      if (localC > 0.01) {
        const cyCoin = shelfY - 0.006 * minSide - coinH - c * coinPitchY + lerp(0.010 * minSide, 0, localC);
        ctx.save();
        ctx.globalAlpha = interiorReveal * localC;
        roundRectPath(coinStackX - coinW * 0.5, cyCoin, coinW, coinH, coinH * 0.45);
        const cGrad = ctx.createLinearGradient(coinStackX - coinW * 0.5, cyCoin, coinStackX + coinW * 0.5, cyCoin);
        cGrad.addColorStop(0, COL_AMBER);
        cGrad.addColorStop(0.5, COL_GOLD);
        cGrad.addColorStop(1, COL_GOLD_LIGHT);
        ctx.fillStyle = cGrad;
        ctx.fill();

        // Crisp center ridge highlight on each coin
        roundRectPath(coinStackX - 0.014 * minSide, cyCoin + 0.004 * minSide, 0.028 * minSide, 0.006 * minSide, 0.003 * minSide);
        ctx.fillStyle = COL_IVORY;
        ctx.fill();
        ctx.restore();
      }
    }

    // Verified Treasury Status Pill cleanly in upper zone above bullion & coins
    const sealW = 0.146 * minSide;
    const sealH = 0.036 * minSide;
    const sealX = cx - sealW * 0.5;
    const sealY = cy - 0.118 * minSide;
    roundRectPath(sealX, sealY, sealW, sealH, sealH * 0.5);
    ctx.fillStyle = "#1F170D";
    ctx.fill();
    ctx.lineWidth = 0.0022 * minSide;
    ctx.strokeStyle = COL_GOLD;
    ctx.stroke();

    // Checkmark circle badge on left side of pill
    const chkCx = sealX + 0.020 * minSide;
    const chkCy = sealY + sealH * 0.5;
    ctx.beginPath();
    ctx.arc(chkCx, chkCy, 0.010 * minSide, 0, TAU);
    ctx.fillStyle = COL_GOLD;
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(chkCx - 0.005 * minSide, chkCy);
    ctx.lineTo(chkCx - 0.002 * minSide, chkCy + 0.0038 * minSide);
    ctx.lineTo(chkCx + 0.005 * minSide, chkCy - 0.0035 * minSide);
    ctx.lineWidth = 0.0024 * minSide;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.strokeStyle = COL_OBSIDIAN;
    ctx.stroke();

    // Clean horizontal status bar inside pill beside checkmark
    roundRectPath(sealX + 0.040 * minSide, chkCy - 0.0045 * minSide, 0.088 * minSide, 0.009 * minSide, 0.0045 * minSide);
    ctx.fillStyle = "#3A2C1A";
    ctx.fill();

    roundRectPath(
      sealX + 0.040 * minSide,
      chkCy - 0.0045 * minSide,
      0.088 * minSide * lerp(0.55, 1.0, bullionSheen * 0.75 + cycleWave * 0.25),
      0.009 * minSide,
      0.0045 * minSide
    );
    ctx.fillStyle = COL_GOLD_LIGHT;
    ctx.fill();

    ctx.restore();
  }

  // 6. Symmetric Double Vault Doors (Slide smoothly into side pockets inside chamber clip)
  const slideDx = doorOpenAmt * 0.180 * minSide;
  const seamHalf = 0.0045 * minSide; // 0.009*minSide crisp center seam gap when closed
  const doorW = chamberHalf + 0.012 * minSide;
  const doorH = chamberSide;
  const doorTopY = cy - chamberHalf;

  // Helper: Draw Twin Safe Lock Wheel centered strictly on each door leaf
  const drawLockWheel = (wx, wy, ang) => {
    const rWheel = 0.044 * minSide;
    ctx.save();
    ctx.translate(wx, wy);
    ctx.rotate(ang);

    // 4 spokes
    ctx.strokeStyle = COL_GOLD;
    ctx.lineWidth = 0.0055 * minSide;
    ctx.lineCap = "round";
    for (let s = 0; s < 4; s++) {
      const sa = (s * Math.PI) / 2;
      ctx.beginPath();
      ctx.moveTo(Math.cos(sa) * 0.012 * minSide, Math.sin(sa) * 0.012 * minSide);
      ctx.lineTo(Math.cos(sa) * (rWheel - 0.005 * minSide), Math.sin(sa) * (rWheel - 0.005 * minSide));
      ctx.stroke();
    }

    // Outer wheel ring
    ctx.beginPath();
    ctx.arc(0, 0, rWheel, 0, TAU);
    ctx.lineWidth = 0.0075 * minSide;
    ctx.strokeStyle = COL_GOLD_LIGHT;
    ctx.stroke();

    // Inner hub cap
    ctx.beginPath();
    ctx.arc(0, 0, 0.014 * minSide, 0, TAU);
    ctx.fillStyle = COL_AMBER;
    ctx.fill();
    ctx.lineWidth = 0.0022 * minSide;
    ctx.strokeStyle = COL_IVORY;
    ctx.stroke();

    ctx.restore();
  };

  // Left Door Leaf
  const leftDoorRight = cx - seamHalf - slideDx;
  const leftDoorX = leftDoorRight - doorW;
  const lGrad = ctx.createLinearGradient(leftDoorX, doorTopY, leftDoorRight, doorTopY + doorH);
  lGrad.addColorStop(0, "#1E170E");
  lGrad.addColorStop(1, "#2D2315");
  ctx.fillStyle = lGrad;
  ctx.fillRect(leftDoorX, doorTopY, doorW, doorH);

  // Left Door seam gold trim & lock wheel centered at cx - 0.092*m - slideDx
  ctx.fillStyle = COL_GOLD;
  ctx.fillRect(leftDoorRight - 0.005 * minSide, doorTopY, 0.005 * minSide, doorH);
  drawLockWheel(cx - 0.092 * minSide - slideDx, cy, wheelAngle);

  // Right Door Leaf
  const rightDoorLeft = cx + seamHalf + slideDx;
  const rGrad = ctx.createLinearGradient(rightDoorLeft, doorTopY, rightDoorLeft + doorW, doorTopY + doorH);
  rGrad.addColorStop(0, "#2D2315");
  rGrad.addColorStop(1, "#1E170E");
  ctx.fillStyle = rGrad;
  ctx.fillRect(rightDoorLeft, doorTopY, doorW, doorH);

  // Right Door seam amber trim & lock wheel centered at cx + 0.092*m + slideDx
  ctx.fillStyle = COL_AMBER;
  ctx.fillRect(rightDoorLeft, doorTopY, 0.005 * minSide, doorH);
  drawLockWheel(cx + 0.092 * minSide + slideDx, cy, -wheelAngle);

  ctx.restore(); // end chamber clip

  // Crisp chamber border rim drawn on top
  roundRectPath(cx - chamberHalf, cy - chamberHalf, chamberSide, chamberSide, 0.024 * minSide);
  ctx.lineWidth = 0.0028 * minSide;
  ctx.strokeStyle = COL_GOLD;
  ctx.globalAlpha = 0.72;
  ctx.stroke();
  ctx.globalAlpha = 1;

  // 7. Left & Right Symmetrical Treasury Telemetry Cards (Strictly clear of safe & bolts)
  const cardW = 0.210 * minSide;
  const cardH = 0.250 * minSide;
  const leftCardX = cx - 0.630 * minSide;
  const rightCardX = cx + 0.420 * minSide;
  const cardY = cy - cardH * 0.5;

  // Left Card: 3 Vault Security & Audit Status Bars
  if (leftCardX > 0.03 * width) {
    ctx.save();
    roundRectPath(leftCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_CARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BRONZE_EDGE;
    ctx.stroke();

    const padX = 0.024 * minSide;
    // Clean top pill header
    roundRectPath(leftCardX + padX, cardY + 0.028 * minSide, 0.088 * minSide, 0.012 * minSide, 0.006 * minSide);
    ctx.fillStyle = "#4A3921";
    ctx.fill();

    const rowStartY = cardY + 0.072 * minSide;
    const rowGapY = 0.054 * minSide;
    const dotR = 0.008 * minSide;
    const barX = leftCardX + padX + dotR * 2 + 0.012 * minSide;
    const barW = cardW - padX * 2 - dotR * 2 - 0.012 * minSide;
    const barH = 0.014 * minSide;

    for (let s = 0; s < 3; s++) {
      const ry = rowStartY + s * rowGapY;
      const val = securitySteps[s];

      ctx.beginPath();
      ctx.arc(leftCardX + padX + dotR, ry + barH * 0.5, dotR, 0, TAU);
      ctx.fillStyle = val > 0.75 ? COL_GOLD : "#4E3D25";
      ctx.fill();

      roundRectPath(barX, ry, barW, barH, barH * 0.5);
      ctx.fillStyle = COL_OBSIDIAN;
      ctx.fill();

      roundRectPath(barX, ry, Math.max(barH, barW * val), barH, barH * 0.5);
      const sGrad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
      sGrad.addColorStop(0, COL_AMBER);
      sGrad.addColorStop(1, COL_GOLD);
      ctx.fillStyle = sGrad;
      ctx.fill();
    }
    ctx.restore();
  }

  // Right Card: Gold Reserve Capacity Bars & Summary Track
  if (rightCardX + cardW < width - 0.03 * width) {
    ctx.save();
    roundRectPath(rightCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_CARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BRONZE_EDGE;
    ctx.stroke();

    const rPadX = 0.024 * minSide;
    const topBarW = cardW - rPadX * 2;
    const topBarH = 0.012 * minSide;
    const topBarY = cardY + 0.030 * minSide;

    roundRectPath(rightCardX + rPadX, topBarY, topBarW, topBarH, topBarH * 0.5);
    ctx.fillStyle = COL_OBSIDIAN;
    ctx.fill();

    roundRectPath(rightCardX + rPadX, topBarY, Math.max(topBarH, topBarW * reserveSummary), topBarH, topBarH * 0.5);
    ctx.fillStyle = COL_GOLD;
    ctx.fill();

    // 5 strictly separated vertical gold reserve bars
    const baselineY = cardY + cardH - 0.030 * minSide;
    const maxBarH = 0.146 * minSide;
    const vBarW = 0.019 * minSide;
    const vPitch = 0.033 * minSide;
    const vStartX = rightCardX + cardW * 0.5 - 2 * vPitch - vBarW * 0.5;

    for (let i = 0; i < 5; i++) {
      const bx = vStartX + i * vPitch;
      roundRectPath(bx, baselineY - maxBarH, vBarW, maxBarH, 0.005 * minSide);
      ctx.fillStyle = COL_OBSIDIAN;
      ctx.fill();

      const fh = Math.max(0.015 * minSide, maxBarH * reserveBars[i]);
      roundRectPath(bx, baselineY - fh, vBarW, fh, 0.005 * minSide);
      const vGrad = ctx.createLinearGradient(bx, baselineY - fh, bx, baselineY);
      vGrad.addColorStop(0, COL_GOLD_LIGHT);
      vGrad.addColorStop(0.5, COL_GOLD);
      vGrad.addColorStop(1, COL_AMBER);
      ctx.fillStyle = vGrad;
      ctx.fill();
    }
    ctx.restore();
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const rawLoopT = t % duration;
  const loopT = rawLoopT < 0 ? rawLoopT + duration : rawLoopT;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.5;
  const u = loopT / duration;
  const TAU = Math.PI * 2;

  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const lerp = (a, b, p) => a + (b - a) * p;
  const easeInOutCubic = (p) => {
    const x = clamp01(p);
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  };
  const easeInOutSine = (p) => {
    const x = clamp01(p);
    return 0.5 * (1 - Math.cos(Math.PI * x));
  };
  const subRange = (p, a, b) => clamp01((p - a) / (b - a));

  const roundRectPath = (x, y, w, h, r) => {
    const rad = Math.min(r, Math.abs(w) * 0.5, Math.abs(h) * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  };

  // 1. Clean Dark Midnight Navy Aesthetic Gradient (zero background glow)
  ctx.save();
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#040914");
  bgGrad.addColorStop(0.52, "#09182E");
  bgGrad.addColorStop(1, "#050E1D");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Palette constants
  const COL_NAVY_DEEP = "#071224";
  const COL_BOARD_BG = "#0B1B33";
  const COL_HEADER_BG = "#0E2240";
  const COL_BORDER = "#1D3E6E";
  const COL_GRID = "#163055";
  const COL_CYAN = "#00E5FF";
  const COL_AZURE = "#38BDF8";
  const COL_MINT = "#2CEAA3";
  const COL_ICE = "#E8F7FF";
  const COL_BEAR = "#1F4473";
  const COL_BEAR_EDGE = "#3E6BA3";

  // 2. Scene Choreography (Seamless 20s Loop)
  // [openN, closeN, highN, lowN, volumeN] normalized inside [0..1]
  const restCandles = [
    [0.22, 0.34, 0.42, 0.14, 0.28],
    [0.34, 0.24, 0.43, 0.16, 0.22],
    [0.24, 0.42, 0.50, 0.18, 0.34],
    [0.42, 0.32, 0.49, 0.24, 0.26],
    [0.32, 0.48, 0.57, 0.24, 0.38],
    [0.44, 0.56, 0.64, 0.36, 0.36],
  ];
  const consolCandles = [
    [0.24, 0.42, 0.50, 0.16, 0.36],
    [0.42, 0.31, 0.50, 0.20, 0.30],
    [0.30, 0.54, 0.62, 0.22, 0.48],
    [0.54, 0.42, 0.62, 0.32, 0.38],
    [0.42, 0.66, 0.74, 0.34, 0.58],
    [0.58, 0.70, 0.78, 0.48, 0.54],
  ];
  const breakoutCandles = [
    [0.24, 0.42, 0.50, 0.16, 0.38],
    [0.42, 0.31, 0.50, 0.20, 0.32],
    [0.30, 0.56, 0.64, 0.22, 0.52],
    [0.54, 0.42, 0.62, 0.32, 0.44],
    [0.44, 0.76, 0.84, 0.36, 0.78],
    [0.68, 0.94, 0.99, 0.60, 0.96],
  ];

  const restTrend = [0.22, 0.30, 0.28, 0.38, 0.44, 0.50];
  const consolTrend = [0.26, 0.36, 0.42, 0.48, 0.58, 0.64];
  const breakoutTrend = [0.26, 0.38, 0.46, 0.58, 0.78, 0.94];

  let cursorT = 0;
  let cursorAlpha = 0;
  let breakoutAmt = 0;
  let arrowProgress = 0;
  let leftBars = [0.38, 0.30, 0.42];
  let rightGauge = 0.36;
  let rightBars = [0.36, 0.30];

  const activeCandles = [];
  const activeTrend = [];

  if (currentScene === 0) {
    // Scene 0: Staggered market formation & trend baseline rise
    for (let i = 0; i < 6; i++) {
      const cp = easeInOutCubic(subRange(sceneProgress, i * 0.08, i * 0.08 + 0.56));
      const row = [];
      for (let k = 0; k < 5; k++) {
        row.push(lerp(restCandles[i][k], consolCandles[i][k], cp));
      }
      activeCandles.push(row);
      activeTrend.push(lerp(restTrend[i], consolTrend[i], cp));
    }
    const g0 = easeInOutCubic(sceneProgress);
    cursorAlpha = easeInOutSine(subRange(sceneProgress, 0.66, 1.0));
    cursorT = 0;
    leftBars = [
      lerp(0.38, 0.66, g0),
      lerp(0.30, 0.56, easeInOutCubic(subRange(sceneProgress, 0.12, 0.9))),
      lerp(0.42, 0.70, easeInOutCubic(subRange(sceneProgress, 0.18, 0.96))),
    ];
    rightGauge = lerp(0.36, 0.62, g0);
    rightBars = [lerp(0.36, 0.60, g0), lerp(0.30, 0.54, g0)];
  } else if (currentScene === 1) {
    // Scene 1: Smooth index cursor traversal -> breakout & upward profit arrow
    const sweepP = easeInOutCubic(subRange(sceneProgress, 0.0, 0.60));
    const brkP = easeInOutCubic(subRange(sceneProgress, 0.48, 0.92));
    cursorT = sweepP;
    cursorAlpha = 1;
    breakoutAmt = brkP;
    arrowProgress = easeInOutCubic(subRange(sceneProgress, 0.52, 0.94));

    for (let i = 0; i < 6; i++) {
      const localBrk = easeInOutCubic(subRange(sceneProgress, 0.44 + i * 0.04, 0.84 + i * 0.025));
      const row = [];
      for (let k = 0; k < 5; k++) {
        row.push(lerp(consolCandles[i][k], breakoutCandles[i][k], localBrk));
      }
      activeCandles.push(row);
      activeTrend.push(lerp(consolTrend[i], breakoutTrend[i], localBrk));
    }

    const rP = easeInOutCubic(subRange(sceneProgress, 0.36, 0.94));
    leftBars = [
      lerp(0.66, 0.94, rP),
      lerp(0.56, 0.86, easeInOutCubic(subRange(sceneProgress, 0.42, 0.96))),
      lerp(0.70, 0.96, easeInOutCubic(subRange(sceneProgress, 0.45, 0.98))),
    ];
    rightGauge = lerp(0.62, 0.95, rP);
    rightBars = [lerp(0.60, 0.92, rP), lerp(0.54, 0.86, rP)];
  } else {
    // Scene 2: Controlled hold & smooth harmonic reset back to exact t=0 state
    const retP = easeInOutCubic(subRange(sceneProgress, 0.22, 0.96));
    breakoutAmt = 1 - retP;
    arrowProgress = 1 - easeInOutCubic(subRange(sceneProgress, 0.20, 0.72));
    cursorAlpha = 1 - easeInOutCubic(subRange(sceneProgress, 0.16, 0.64));
    cursorT = lerp(1, 0, easeInOutCubic(subRange(sceneProgress, 0.20, 0.84)));

    for (let i = 0; i < 6; i++) {
      const colRet = easeInOutCubic(subRange(sceneProgress, 0.22 + (5 - i) * 0.03, 0.80 + (5 - i) * 0.03));
      const row = [];
      for (let k = 0; k < 5; k++) {
        row.push(lerp(breakoutCandles[i][k], restCandles[i][k], colRet));
      }
      activeCandles.push(row);
      activeTrend.push(lerp(breakoutTrend[i], restTrend[i], colRet));
    }

    leftBars = [
      lerp(0.94, 0.38, retP),
      lerp(0.86, 0.30, retP),
      lerp(0.96, 0.42, retP),
    ];
    rightGauge = lerp(0.95, 0.36, retP);
    rightBars = [lerp(0.92, 0.36, retP), lerp(0.86, 0.30, retP)];
  }

  // Smooth continuous 20s heartbeat wave for header activity indicator
  const cycleWave = 0.5 + 0.5 * Math.sin(TAU * u);

  // 3. Central Hero Icon: Rising Stock Chart & Candlestick Board
  const bw = 0.620 * minSide;
  const bh = 0.460 * minSide;
  const bx = cx - bw * 0.5;
  const by = cy - bh * 0.5;
  const bRad = 0.028 * minSide;

  ctx.save();
  // Board Outer Body
  roundRectPath(bx, by, bw, bh, bRad);
  ctx.fillStyle = COL_BOARD_BG;
  ctx.fill();

  // Header strip clipped strictly inside top of board
  ctx.save();
  roundRectPath(bx, by, bw, bh, bRad);
  ctx.clip();
  ctx.fillStyle = COL_HEADER_BG;
  ctx.fillRect(bx, by, bw, 0.068 * minSide);
  ctx.restore();

  // Outer crisp border stroke of board
  roundRectPath(bx, by, bw, bh, bRad);
  ctx.lineWidth = 0.003 * minSide;
  ctx.strokeStyle = COL_BORDER;
  ctx.stroke();

  // Header divider line
  const headerBotY = by + 0.068 * minSide;
  ctx.beginPath();
  ctx.moveTo(bx + 0.002 * minSide, headerBotY);
  ctx.lineTo(bx + bw - 0.002 * minSide, headerBotY);
  ctx.lineWidth = 0.0022 * minSide;
  ctx.strokeStyle = COL_BORDER;
  ctx.stroke();

  // Header Left: Market Ticker Bars & Status Dots (clean horizontal alignment)
  const hCenterY = by + 0.034 * minSide;
  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(bx + 0.034 * minSide + d * 0.020 * minSide, hCenterY, 0.005 * minSide, 0, TAU);
    ctx.fillStyle = d === 0 ? COL_MINT : d === 1 ? COL_CYAN : "#355F94";
    ctx.fill();
  }
  roundRectPath(bx + 0.104 * minSide, hCenterY - 0.0065 * minSide, 0.105 * minSide, 0.013 * minSide, 0.0065 * minSide);
  ctx.fillStyle = "#19355B";
  ctx.fill();

  roundRectPath(
    bx + 0.104 * minSide,
    hCenterY - 0.0065 * minSide,
    0.105 * minSide * lerp(0.55, 0.92, breakoutAmt * 0.75 + cycleWave * 0.25),
    0.013 * minSide,
    0.0065 * minSide
  );
  ctx.fillStyle = COL_CYAN;
  ctx.fill();

  // Header Right: Clean Profit Growth Status Pill
  const badgeW = 0.118 * minSide;
  const badgeH = 0.030 * minSide;
  const badgeX = bx + bw - 0.028 * minSide - badgeW;
  const badgeY = hCenterY - badgeH * 0.5;
  roundRectPath(badgeX, badgeY, badgeW, badgeH, badgeH * 0.5);
  ctx.fillStyle = COL_NAVY_DEEP;
  ctx.fill();
  ctx.lineWidth = 0.002 * minSide;
  ctx.strokeStyle = breakoutAmt > 0.45 ? COL_MINT : "#264B7D";
  ctx.stroke();

  // Mini upward zigzag line inside header pill
  const zigX = badgeX + 0.018 * minSide;
  const zigY = hCenterY + 0.005 * minSide;
  ctx.beginPath();
  ctx.moveTo(zigX, zigY);
  ctx.lineTo(zigX + 0.011 * minSide, zigY - 0.007 * minSide);
  ctx.lineTo(zigX + 0.019 * minSide, zigY - 0.003 * minSide);
  ctx.lineTo(zigX + 0.030 * minSide, zigY - 0.012 * minSide);
  ctx.lineWidth = 0.0028 * minSide;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.strokeStyle = breakoutAmt > 0.45 ? COL_MINT : COL_CYAN;
  ctx.stroke();

  // Mini progress pill beside zigzag inside header badge
  roundRectPath(badgeX + 0.058 * minSide, hCenterY - 0.004 * minSide, 0.044 * minSide, 0.008 * minSide, 0.004 * minSide);
  ctx.fillStyle = "#183358";
  ctx.fill();
  roundRectPath(
    badgeX + 0.058 * minSide,
    hCenterY - 0.004 * minSide,
    0.044 * minSide * lerp(0.45, 1.0, breakoutAmt),
    0.008 * minSide,
    0.004 * minSide
  );
  ctx.fillStyle = COL_MINT;
  ctx.fill();

  // 4. Strictly Partitioned Chart Zones inside Board
  const colPitch = 0.084 * minSide;
  const colStartX = cx - 2.5 * colPitch; // spans cx - 0.210*m .. cx + 0.210*m
  const colXs = [];
  for (let i = 0; i < 6; i++) {
    colXs.push(colStartX + i * colPitch);
  }
  const innerLeft = bx + 0.042 * minSide;
  const innerRight = bx + bw - 0.042 * minSide;

  // Zone Dividers
  const div1Y = by + 0.198 * minSide;
  const div2Y = by + 0.358 * minSide;
  ctx.strokeStyle = COL_GRID;
  ctx.lineWidth = 0.002 * minSide;
  ctx.beginPath();
  ctx.moveTo(innerLeft, div1Y);
  ctx.lineTo(innerRight, div1Y);
  ctx.moveTo(innerLeft, div2Y);
  ctx.lineTo(innerRight, div2Y);
  ctx.stroke();

  // --- ZONE 1: Profit Trend Curve, Upper Target Line & Dedicated Profit Arrow ---
  const upBot = by + 0.184 * minSide;
  const upTop = by + 0.114 * minSide;
  const upH = upBot - upTop;

  // Upper target dashed line strictly ABOVE trend curve peak (y <= by + 0.096*m, gap >= 0.018*m)
  const targetY = lerp(by + 0.098 * minSide, by + 0.092 * minSide, breakoutAmt);
  ctx.save();
  ctx.setLineDash([0.010 * minSide, 0.008 * minSide]);
  ctx.lineWidth = 0.0024 * minSide;
  ctx.strokeStyle = breakoutAmt > 0.5 ? COL_MINT : "rgba(0, 229, 255, 0.50)";
  ctx.beginPath();
  ctx.moveTo(innerLeft, targetY);
  ctx.lineTo(colXs[5] + 0.014 * minSide, targetY);
  ctx.stroke();
  ctx.restore();

  // Trend points
  const trendPts = [];
  for (let i = 0; i < 6; i++) {
    trendPts.push({
      x: colXs[i],
      y: upBot - activeTrend[i] * upH,
    });
  }

  // Smooth Bezier Trend Curve
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(trendPts[0].x, trendPts[0].y);
  for (let i = 0; i < trendPts.length - 1; i++) {
    const p0 = trendPts[i];
    const p1 = trendPts[i + 1];
    const midX = (p0.x + p1.x) * 0.5;
    ctx.bezierCurveTo(midX, p0.y, midX, p1.y, p1.x, p1.y);
  }
  const curveGrad = ctx.createLinearGradient(colXs[0], 0, colXs[5], 0);
  curveGrad.addColorStop(0, COL_CYAN);
  curveGrad.addColorStop(1, COL_MINT);
  ctx.strokeStyle = curveGrad;
  ctx.lineWidth = 0.005 * minSide;
  ctx.lineCap = "round";
  ctx.stroke();

  // Vertex dots on trend curve
  for (let i = 0; i < 6; i++) {
    ctx.beginPath();
    ctx.arc(trendPts[i].x, trendPts[i].y, 0.0046 * minSide, 0, TAU);
    ctx.fillStyle = COL_ICE;
    ctx.fill();
  }

  // Active index node moving cleanly along the Bezier curve
  if (cursorAlpha > 0.02) {
    const segFloat = clamp01(cursorT) * 5;
    const segIdx = Math.min(4, Math.floor(segFloat));
    const localT = segFloat - segIdx;
    const p0 = trendPts[segIdx];
    const p1 = trendPts[segIdx + 1];
    const midX = (p0.x + p1.x) * 0.5;
    const inv = 1 - localT;
    const sx =
      inv * inv * inv * p0.x +
      3 * inv * inv * localT * midX +
      3 * inv * localT * localT * midX +
      localT * localT * localT * p1.x;
    const sy =
      inv * inv * inv * p0.y +
      3 * inv * inv * localT * p0.y +
      3 * inv * localT * localT * p1.y +
      localT * localT * localT * p1.y;

    ctx.globalAlpha = cursorAlpha;
    ctx.beginPath();
    ctx.arc(sx, sy, 0.0115 * minSide, 0, TAU);
    ctx.strokeStyle = COL_CYAN;
    ctx.lineWidth = 0.0026 * minSide;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(sx, sy, 0.0058 * minSide, 0, TAU);
    ctx.fillStyle = COL_MINT;
    ctx.fill();
    ctx.globalAlpha = 1;
  }

  // Dedicated Upward Profit Arrow at right side of Zone 1 (strictly clear of curve & target line)
  if (arrowProgress > 0.02) {
    const arrowX = colXs[5] + 0.044 * minSide; // cx + 0.254*m, safely inside innerRight (cx + 0.268*m)
    const arrowBotY = by + 0.172 * minSide;
    const arrowTopY = lerp(arrowBotY - 0.012 * minSide, by + 0.104 * minSide, arrowProgress);
    const headSz = 0.011 * minSide * arrowProgress;

    ctx.save();
    ctx.globalAlpha = arrowProgress;
    ctx.strokeStyle = COL_MINT;
    ctx.lineWidth = 0.0044 * minSide;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";

    // Vertical stem
    ctx.beginPath();
    ctx.moveTo(arrowX, arrowBotY);
    ctx.lineTo(arrowX, arrowTopY);
    ctx.stroke();

    // Upward chevron head
    ctx.beginPath();
    ctx.moveTo(arrowX - headSz, arrowTopY + headSz * 0.9);
    ctx.lineTo(arrowX, arrowTopY);
    ctx.lineTo(arrowX + headSz, arrowTopY + headSz * 0.9);
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();

  // --- ZONE 2: 6 Precision Market Candlesticks ---
  const midBot = by + 0.346 * minSide;
  const midTop = by + 0.210 * minSide;
  const midH = midBot - midTop;
  const candleW = 0.030 * minSide;

  // Clean subtle vertical column tracks strictly inside Zone 2
  ctx.strokeStyle = "rgba(32, 66, 110, 0.32)";
  ctx.lineWidth = 0.002 * minSide;
  for (let i = 0; i < 6; i++) {
    ctx.beginPath();
    ctx.moveTo(colXs[i], midTop);
    ctx.lineTo(colXs[i], midBot);
    ctx.stroke();
  }

  for (let i = 0; i < 6; i++) {
    const [openN, closeN, highN, lowN] = activeCandles[i];
    const isBull = closeN >= openN;
    const bodyTopN = Math.max(openN, closeN);
    const bodyBotN = Math.min(openN, closeN);

    const yHigh = midBot - highN * midH;
    const yLow = midBot - lowN * midH;
    const yBodyTop = midBot - bodyTopN * midH;
    const yBodyBot = midBot - bodyBotN * midH;
    const bodyH = Math.max(0.010 * minSide, yBodyBot - yBodyTop);

    const xCenter = colXs[i];
    const isHighlight = i === 5 && breakoutAmt > 0.35;
    const bodyColor = isBull ? (isHighlight ? COL_MINT : COL_CYAN) : COL_BEAR;
    const wickColor = isBull ? (isHighlight ? "#A7F3D0" : "#7DD3FC") : "#6488B4";

    // Upper wick (strictly outside body)
    if (yHigh < yBodyTop - 0.002 * minSide) {
      ctx.beginPath();
      ctx.moveTo(xCenter, yHigh);
      ctx.lineTo(xCenter, yBodyTop);
      ctx.lineWidth = 0.0038 * minSide;
      ctx.lineCap = "round";
      ctx.strokeStyle = wickColor;
      ctx.stroke();
    }

    // Lower wick (strictly outside body)
    if (yLow > yBodyBot + 0.002 * minSide) {
      ctx.beginPath();
      ctx.moveTo(xCenter, yBodyBot);
      ctx.lineTo(xCenter, yLow);
      ctx.lineWidth = 0.0038 * minSide;
      ctx.lineCap = "round";
      ctx.strokeStyle = wickColor;
      ctx.stroke();
    }

    // Candlestick body
    roundRectPath(xCenter - candleW * 0.5, yBodyTop, candleW, bodyH, 0.0055 * minSide);
    ctx.fillStyle = bodyColor;
    ctx.fill();
    ctx.lineWidth = 0.002 * minSide;
    ctx.strokeStyle = isBull ? (isHighlight ? COL_ICE : "rgba(232, 247, 255, 0.45)") : COL_BEAR_EDGE;
    ctx.stroke();
  }

  // --- ZONE 3: Aligned Volume Bars & Column Activity Pips ---
  const volBot = by + 0.412 * minSide;
  const volMaxH = 0.044 * minSide;
  const volW = 0.024 * minSide;
  const pipY = by + 0.432 * minSide;

  for (let i = 0; i < 6; i++) {
    const volN = activeCandles[i][4];
    const isBull = activeCandles[i][1] >= activeCandles[i][0];
    const vh = Math.max(0.007 * minSide, volN * volMaxH);
    const vx = colXs[i] - volW * 0.5;
    const vy = volBot - vh;

    roundRectPath(vx, vy, volW, vh, 0.004 * minSide);
    ctx.fillStyle =
      i >= 4 && breakoutAmt > 0.4
        ? COL_MINT
        : isBull
        ? "rgba(0, 229, 255, 0.70)"
        : "rgba(56, 189, 248, 0.34)";
    ctx.fill();

    // Column indicator pip
    const colPosNorm = i / 5;
    const dist = Math.abs(cursorT - colPosNorm);
    const activePip = cursorAlpha * clamp01(1 - dist * 4.5);
    ctx.beginPath();
    ctx.arc(colXs[i], pipY, (0.0038 + 0.002 * activePip) * minSide, 0, TAU);
    ctx.fillStyle = activePip > 0.35 ? COL_MINT : i === 5 && breakoutAmt > 0.5 ? COL_MINT : "#264873";
    ctx.fill();
  }
  ctx.restore();

  // 5. Left & Right Symmetrical Financial KPI Cards (Strictly clear of Central Board)
  const cardW = 0.210 * minSide;
  const cardH = 0.250 * minSide;
  const leftCardX = cx - 0.630 * minSide;
  const rightCardX = cx + 0.420 * minSide;
  const cardY = cy - cardH * 0.5;

  // Left KPI Card: 3 Portfolio / Market Ratio Rows
  if (leftCardX > 0.03 * width) {
    ctx.save();
    roundRectPath(leftCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_BOARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    // Clean top pill header bar
    const padX = 0.024 * minSide;
    roundRectPath(leftCardX + padX, cardY + 0.028 * minSide, 0.088 * minSide, 0.012 * minSide, 0.006 * minSide);
    ctx.fillStyle = "#224678";
    ctx.fill();

    const rowStartY = cardY + 0.072 * minSide;
    const rowGapY = 0.054 * minSide;
    const sqSize = 0.018 * minSide;
    const barX = leftCardX + padX + sqSize + 0.014 * minSide;
    const barW = cardW - padX * 2 - sqSize - 0.014 * minSide;
    const barH = 0.014 * minSide;

    for (let r = 0; r < 3; r++) {
      const ry = rowStartY + r * rowGapY;
      // Crisp square index badge
      roundRectPath(leftCardX + padX, ry, sqSize, sqSize, 0.004 * minSide);
      ctx.fillStyle = r === 2 ? COL_MINT : COL_CYAN;
      ctx.fill();

      // Track
      const byTrack = ry + (sqSize - barH) * 0.5;
      roundRectPath(barX, byTrack, barW, barH, barH * 0.5);
      ctx.fillStyle = COL_NAVY_DEEP;
      ctx.fill();

      // Fill
      roundRectPath(barX, byTrack, Math.max(barH, barW * leftBars[r]), barH, barH * 0.5);
      const bGrad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
      bGrad.addColorStop(0, COL_AZURE);
      bGrad.addColorStop(1, r >= 1 ? COL_MINT : COL_CYAN);
      ctx.fillStyle = bGrad;
      ctx.fill();
    }
    ctx.restore();
  }

  // Right KPI Card: ROI Performance Gauge + 2 Margin Ratio Bars
  if (rightCardX + cardW < width - 0.03 * width) {
    ctx.save();
    roundRectPath(rightCardX, cardY, cardW, cardH, 0.024 * minSide);
    ctx.fillStyle = COL_BOARD_BG;
    ctx.fill();
    ctx.lineWidth = 0.0026 * minSide;
    ctx.strokeStyle = COL_BORDER;
    ctx.stroke();

    // ROI Performance Arc
    const gcx = rightCardX + cardW * 0.5;
    const gcy = cardY + 0.092 * minSide;
    const gr = 0.052 * minSide;
    const startA = Math.PI * 0.78;
    const spanA = Math.PI * 1.44;

    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA);
    ctx.lineWidth = 0.011 * minSide;
    ctx.strokeStyle = COL_NAVY_DEEP;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(gcx, gcy, gr, startA, startA + spanA * rightGauge);
    const gGrad = ctx.createLinearGradient(gcx - gr, gcy, gcx + gr, gcy);
    gGrad.addColorStop(0, COL_CYAN);
    gGrad.addColorStop(1, COL_MINT);
    ctx.strokeStyle = gGrad;
    ctx.stroke();

    // Clean Upward Financial Arrow inside gauge center
    const arrH = 0.026 * minSide;
    const arrW = 0.016 * minSide;
    ctx.strokeStyle = breakoutAmt > 0.5 ? COL_MINT : COL_CYAN;
    ctx.lineWidth = 0.004 * minSide;
    ctx.lineJoin = "round";
    ctx.beginPath();
    ctx.moveTo(gcx, gcy + arrH * 0.5);
    ctx.lineTo(gcx, gcy - arrH * 0.5);
    ctx.moveTo(gcx - arrW * 0.7, gcy - arrH * 0.05);
    ctx.lineTo(gcx, gcy - arrH * 0.55);
    ctx.lineTo(gcx + arrW * 0.7, gcy - arrH * 0.05);
    ctx.stroke();

    // 2 Horizontal Margin Bars beneath gauge
    const rbPadX = 0.024 * minSide;
    const rbW = cardW - rbPadX * 2;
    const rbH = 0.013 * minSide;
    for (let i = 0; i < 2; i++) {
      const rby = cardY + 0.172 * minSide + i * 0.032 * minSide;
      roundRectPath(rightCardX + rbPadX, rby, rbW, rbH, rbH * 0.5);
      ctx.fillStyle = COL_NAVY_DEEP;
      ctx.fill();

      roundRectPath(rightCardX + rbPadX, rby, Math.max(rbH, rbW * rightBars[i]), rbH, rbH * 0.5);
      ctx.fillStyle = i === 0 ? COL_MINT : COL_CYAN;
      ctx.fill();
    }
    ctx.restore();
  }
}
